(13324, 2132, 'اِسْتَتِمُّوا نِعَمَ اللهِ عَلَيْكُمْ بِالصَّبْرِ عَلى طاعَتِه وَ الْمُحافَظَةِ عَلى مَا اسْتَحْفَظَكُمْ مِنْ كِتابِه.', NULL, '7', '26', '201', '739', '2', 0, ''),
(13325, 2133, 'اِتَّقُوا شِرارَ النِّساءِ وَ كُونُوا مِنْ خِيارِهِنَّ عَلى حَذَرٍ.', NULL, '7', '26', '201', '739', '2', 0, ''),
