(14388, 3196, 'إِنَّ أَسْعَدَ النّاسِ مَنْ كانَ لَهُ مِنْ نَفْسِه بِطاعَةِ اللهِ مُتَقاضٍ.', NULL, '7', '26', '209', '747', '2', 0, ''),
(14389, 3197, 'إِنَّ أَهْنَأَ النّاسِ عَيْشاً مَنْ كانَ بِقَسْمِ اللهِ راضِياً.', NULL, '7', '26', '209', '747', '2', 0, ''),
