(14749, 3557, 'إِنّي لَعَلى إِقامَةِ حُجَجِ اللهِ أُقاوِلُ وَ عَلى نُصْرَةِ دينِه أُجاهِدُ وَ أُقاتِلُ.', NULL, '7', '26', '212', '750', '2', 0, ''),
(14750, 3558, 'إِنّي لَعَلى بيِّنَةٍ مِنْ رَبّي وَ بَصيرَةٍ في ديني وَ يَقينٍ في أَمْري.', NULL, '7', '26', '212', '750', '2', 0, ''),
(14751, 3559, 'إِنّي لا أَحُثُّكُمْ عَلى طاعَةِ اللهِ إِلّا وَ أسْبِقُكُمْ إِلَيْها وَ لا أَنْهاكُمْ عَنْ مَعْصِيَةِ اللهِ إِلّا وَ أَنْتَهي قَبْلَكُمْ عَنْها.', NULL, '7', '26', '212', '750', '2', 0, ''),
(14752, 3560, 'إِنّي آمُرُكُمْ بِالْإِسْتِعْدادِ وَ الْإِسْتِكْثارِ مِنَ الزّادِ لِيَوْمٍ تَقْدُمُونَ عَلى ما تُقَدِّمُونَ وَتَنْدَمُونَ عَلى ما تُخَلِّفُونَ وَ تُجْزَوْنَ بِما كُنْتُمْ تُسْلِفُونَ.', NULL, '7', '26', '212', '750', '2', 0, ''),
(14753, 3561, 'إِنّي لَعَلى يَقينٍ مِنْ رَبّي وَ غَيرِ شُبْهَةٍ في ديني.', NULL, '7', '26', '212', '750', '2', 0, ''),
(14754, 3562, 'إِنّي مُسْتَوْفٍ رِزْقي وَ مُجاهِدٌ نَفْسي وَ مُنْتَهٍ إِلى قِسَمي.', NULL, '7', '26', '212', '750', '2', 0, ''),
(14755, 3563, 'إِنّيَ لَعَلى جادَّةِ الْحَقِّ وَ إِنَّهُمْ لَعَلى مَزَلّة الْباطِل.', NULL, '7', '26', '212', '750', '2', 0, ''),
(14756, 3564, 'إِنّي لَأَرْفَعُ نَفْسي أَنْ تَكُونَ لَها حاجَةٌ لا يَسَعُها جُودي أَوْ جَهْلٌ لا يَسَعُهُ حِلْمي أَوْ ذَنْبٌ لا يَسَعُهُ عَفْوي أَو أَنْ يَكُونَ زَمانٌ أَطْوَلُ مِنْ زَماني.', NULL, '7', '26', '212', '750', '2', 0, ''),
(14757, 3565, 'إِنّي كُنْتُ إِذا سَئَلْتُ رَسُولَ اللهِ صلّى الله عليه و آله أَعْطاني وَ إِذا سَكَتُّ عَنْ مَسْألَتِ|هِ| ابْتَدَأَني.', NULL, '7', '26', '212', '750', '2', 0, ''),
(14758, 3566, 'إِنّي لَأَرْفَعُ نَفْسي عَنْ أَنْ أَنْهَى النّاسَ عَمَّا لَسْتُ عَنْهُ أَنْتَهي أَوْ آمُرُهُمْ بِما لا أَسْبِقُهُمْ إِلَيْهِ بِعَمَلي أَوْ أَرْضى مِنْهُمْ إِلّا بِما لا يَرْضى رَبّي.', NULL, '7', '26', '212', '750', '2', 0, ''),
(14759, 3567, 'إِنّي طَلَّقْتُ الدُّنْيا ثَلاثاً |بَتاتاً لا رَجْعَةَ لي فيها وَ أَلْقَيْتُ حَبْلَها عَلى غارِبِها.', NULL, '7', '26', '212', '750', '2', 0, ''),
(14760, 3568, 'إِنّي أَخافُ عَلَيْكُمْ كُلَّ مُذْلِقِ اللِّسانِ مُنافِقِ الْجِنانِ يَقُولُ ما تَعْلَمُونَ وَ يَفْعَلُ ما تُنْكِرُونَ.', NULL, '7', '26', '212', '750', '2', 0, ''),
(14761, 3569, 'إِنّي إِذَا اسْتَحْكَمْتُ فِي الرَّجُلِ خَصْلَةً مِنْ خِصالِ الْخَيرِ احْتَمَلْتُهُ لَها وَ اغْتَفَرْتُ
لَهُ فَقْدَ ما سِواها وَ لا أَغْتَفِرُ لَهُ فَقْدَ عَقْلٍ وَ لا عُدْمَ دينٍ لِأَنَّ مُفارَقَةَ الدِّينِ
مُفارَقَةُ الْأَمْنِ وَ لا تَهْنأُ حَياةٌ مَعَ مَخافَةٍ وَ عَدَمُ الْعَقْلِ عَدَمُ الْحَياةِ وَ لا تُعاشَرُ
الْأَمْواتُ.', NULL, '7', '26', '212', '750', '2', 0, ''),
(14762, 3570, 'إِنَّكَ لَمْ تُخْلَقْ لِلدُّنْيا فَازْهَدْ فيها وَأَعْرِضْ عَنْهَا.', NULL, '7', '26', '213', '751', '2', 0, ''),
(14763, 3571, 'إِنَّكَ إِنْ عَمِلْتَ لِلآخِرَةِ فَازَ قِدْحُكَ.', NULL, '7', '26', '213', '751', '2', 0, ''),
(14764, 3572, 'إِنَّكَ إِنْ عَمِلْتَ لِلدُّنْيَا خَسِرَتْ صَفْقَتُكَ.', NULL, '7', '26', '213', '751', '2', 0, ''),
(14765, 3573, 'إِنَّكَ إِنْ أَقْبَلْتَ عَلى الدُّنْيا أَدْبَرَتْ.', NULL, '7', '26', '213', '751', '2', 0, ''),
(14766, 3574, 'إِنَّكَ إِنْ أَدْبَرْتَ عَنِ الدُّنْيا أَقْبَلَتْ.', NULL, '7', '26', '213', '751', '2', 0, ''),
(14767, 3575, 'إِنَّكَ إِنِ اشْتَغَلْتَ بِقَضاءِ النَّوافِلِ عَنْ أَداءِ الْفَرائِضِ فَلَنْ يَقُومَ فَضْلٌ تَكْسِبُهُ بِفَرْضٍ تُضَيِّعُهُ.', NULL, '7', '26', '213', '751', '2', 0, ''),
(14768, 3576, 'إِنَّكَ لَنْ تَلِجَ الْجَنَّةَ حَتّى تَزْدَجِرَ عَنْ غَيِّكَ وَ تَنْتَهي، وَ تَرْتَدِعَ عَنْ مَعاصيكَ وَتَرْعَوِىَ.', NULL, '7', '26', '213', '751', '2', 0, ''),
(14769, 3577, 'إِنَّكَ إِنْ سالَمْتَ اللهَ سَلِمْتَ وَ فُزْتَ.', NULL, '7', '26', '213', '751', '2', 0, ''),
(14770, 3578, 'إِنَّكَ إِنْ حارَبْتَ الْحَقَّ حُرِبْتَ وَهَلَكْتَ.', NULL, '7', '26', '213', '751', '2', 0, ''),
(14771, 3579, 'إِنَّكَ لَسْتَ بِسابِقٍ أَجَلَكَ وَ لا بِمَرْزُوقٍ ما لَيْسَ لَكَ فَلِماذا تُشْقي نَفْسَكَ يا شَقِيُّ.', NULL, '7', '26', '213', '751', '2', 0, ''),
(14772, 3580, 'إِنَّكَ في سَبيلِ مَنْ كانَ قَبْلَكَ فَاجْعَلْ جِدَّكَ لِاخِرَتِكَ وَ لا تُكْتَرِثْ بِعَمَلِ الدُّنْيا.', NULL, '7', '26', '213', '751', '2', 0, ''),
(14773, 3581, 'إِنَّكَ لَنْ تَبْلُغَ أَمَلَكَ وَ لَنْ تَعْدُوَ أَجَلَكَ فَاتَّقِ اللهَ وَ أَجْمِلْ في الطَّلَبِ.', NULL, '7', '26', '213', '751', '2', 0, ''),
(14774, 3582, 'إِنَّكَ مُدْرِكٌ قِسَمَكَ وَ مَضْمُونٌ رِزْقُكَ وَ مُسْتَوْفٍ ما كُتِبَ لَكَ فَأَرِحْ نَفْسَكَ مِنْ شَقاءِ الْحِرْصِ وَ ذِلَّةِ الطَّلَبِ وَثِقْ بِاللهِ وَ خَفِّضْ فِي الْمُكْتَسِبِ.', NULL, '7', '26', '213', '751', '2', 0, ''),
(14775, 3583, 'إِنَّكَ إِنْ مَلَّكْتَ نَفْسَكَ قِيادَكَ أَفْسَدَتْ مَعادَكَ وَ أَوْرَثَتْكَ بَلاءً لا يَنْتَهي وَ شَقاءً لا يَنْقَضي.', NULL, '7', '26', '213', '751', '2', 0, ''),
(14776, 3584, 'إِنَّكَ لَنْ يُتَقَبَّلَ مِنْكَ إِلّا عَمَلٌ أَخْلَصْتَ فيهِ وَ لَمْ تَشُبْهُ بِالْهَوى وَ اَسْبابِ الدُّنْيا.', NULL, '7', '26', '213', '751', '2', 0, ''),
(14777, 3585, 'إِنَّكَ طَريدُ الْمَوْتِ الَّذي لا يَنْجُو هارِبهُ وَ لابُدَّ أَنَّهُ مُدْرِكُهُ.', NULL, '7', '26', '213', '751', '2', 0, ''),
(14778, 3586, 'إِنَّكَ إِنْ تَواضَعْتَ رَفَعَكَ اللهُ.', NULL, '7', '26', '213', '751', '2', 0, ''),
(14779, 3587, 'إِنَّكَ لَنْ تُدْرِكَ مِنْ رَبِّكَ ما تُحِبُّ إِلّا بِالصَّبْرِ عَمّا تَشْتَهي.', NULL, '7', '26', '213', '751', '2', 0, ''),
(14780, 3588, 'إِنَّكَ إِنْ تَكَبَّرْتَ وَضَعَكَ اللهُ.', NULL, '7', '26', '213', '751', '2', 0, ''),
(14781, 3589, 'إِنَّكَ إِنْ جاهَدْتَ نَفْسَكَ حُزْتَ رِضى اللهِ.', NULL, '7', '26', '213', '751', '2', 0, ''),
(14782, 3590, 'إِنَّكَ إِنْ أَنْصَفْتَ مِنْ نَفْسِك أَزْلَفَكَ اللهُ.', NULL, '7', '26', '213', '751', '2', 0, ''),
(14783, 3591, 'إِنَّكَ إِنِ اجْتَنَبْتَ السَّيِّئاتِ نِلْتَ رَفيعَ الدَّرَجاتِ.', NULL, '7', '26', '213', '751', '2', 0, ''),
(14784, 3592, 'إِنَّكَ إِنْ تَوَرَّعْتَ تَنَزَّهْتَ عَنْ دَنَسِ السَّيِّئاتِ.', NULL, '7', '26', '213', '751', '2', 0, ''),
(14785, 3593, 'إِنَّكَ إَنْ أَطَعْتَ اللهَ نَجّاك وَ أَصْلَحَ مَثْواكَ.', NULL, '7', '26', '213', '751', '2', 0, ''),
(14786, 3594, 'إِنَّكَ إِنْ أَطَعْتَ هَواكَ أَصَمَّكَ وَ أَعْماكَ وَ أَفْسَدَ مُنْقَلَبَكَ وَ أَرْداكَ.', NULL, '7', '26', '213', '751', '2', 0, ''),
(14787, 3595, 'إِنَّكَ إِنْ أَحْسَنْتَ فَلِنَفْسِكَ تُكْرِمُ وَ إِلَيْها تُحْسِنُ.', NULL, '7', '26', '213', '751', '2', 0, ''),
(14788, 3596, 'إِنَّكَ إِنْ أَسَأْتَ فَلِنَفْسِكَ تَمْتَهِنُ وَ إِيّاها تَغْبِنُ.', NULL, '7', '26', '213', '751', '2', 0, ''),
(14789, 3597, 'إِنَّكَ مَخْلُوقٌ لِلْاخِرَةِ فَاعْمَلْ لَها.', NULL, '7', '26', '213', '751', '2', 0, ''),
(14790, 3598, 'إِنَّكَ مَوْزُونٌ بِعَقْلِكَ فَزَكَّه بِالْعِلْمِ.', NULL, '7', '26', '213', '751', '2', 0, ''),
(14791, 3599, 'إِنَّكَ مُقَوِّمٌ بِأَدَبِكَ فَزَيِّنْهُ بِالْحِلْمِ.', NULL, '7', '26', '213', '751', '2', 0, ''),
(14792, 3600, 'إِنَّكَ لَنْ يُغْنِي عَنْكَ بَعْدَ الْمَوْتِ إِلّا صالِحُ عَمَلٍ قَدَّمْتَهُ فَتَزَوَّدْ مِنْ صالِحِ الْعَمَلِ.', NULL, '7', '26', '213', '751', '2', 0, ''),
(14793, 3601, 'إِنَّكَ لَنْ تَلْقَى الله سُبْحانَهُ وَ تَعالى بِعَمَلٍ أَضَرَّ عَلَيْكَ مِنْ حُبِّ الدُّنْيا.', NULL, '7', '26', '213', '751', '2', 0, ''),
(14794, 3602, 'إِنَّكَ لَنْ تَحْمِلَ إِلى الْاخِرَةِ عَمَلاً أَنْفَعَ لَكَ مِنَ الصَّبْرِ وَ الرِّضا وَ الْخَوْفِ وَالرَّجاءِ.', NULL, '7', '26', '213', '751', '2', 0, ''),
(14795, 3603, 'إِنَّكُمْ مُؤاخَذُونَ بِأَقْوالِكُمْ فَلا تَقُولُوا إِلّا خَيْراً.', NULL, '7', '26', '214', '752', '2', 0, ''),
(14796, 3604, 'إِنَّكُمْ إِلى اكْتِسابِ صالِحِ الْأَعْمالِ أَحْوَجُ مِنْكُمْ إِلى مَكاسِبِ الْأَمْوالِ.', NULL, '7', '26', '214', '752', '2', 0, ''),
(14797, 3605, 'إِنَّكُمْ إِنْ رَغِبْتُمْ إِلى اللهِ غَنِمْتُمْ وَ نَجَوْتُمْ وَ إِنْ رَغِبْتُمْ إِلى الدُّنْيا خَسِرْتُمْ وَ هَلَكْتُمْ.', NULL, '7', '26', '214', '752', '2', 0, ''),
(14798, 3606, 'إِنَّكُمْ إِنْ أَقْبَلْتُمْ عَلى اللهِ أَقْبَلْتُمْ وَ إِنْ أَدْبَرْتُمْ عَنْهُ أَدْبَرْتُمْ.', NULL, '7', '26', '214', '752', '2', 0, ''),
(14799, 3607, 'إِنَّكُمْ إِنْ أَمَّرْتُمْ عَلَيْكُمُ الْهَوى أَصَمَّكُمْ وَ أَعْماكُمْ وَ أَرْداكُمْ.', NULL, '7', '26', '214', '752', '2', 0, ''),
(14800, 3608, 'إِنَّكُمْ إِنْ زَهِدْتُمْ تَخَلَّصْتُمْ مِنْ شَقاءِ الدُّنْيا وَ فُزْتُمْ بِدارِ الْبَقاءِ.', NULL, '7', '26', '214', '752', '2', 0, ''),
(14801, 3609, 'إِنَّكُمْ إِلى اكْتِسابِ الْأَدَبِ أَحْوَجُ مِنْكُمْ إِلى اكْتِسابِ الْفِضّةِ وَ الذَّهَبِ.', NULL, '7', '26', '214', '752', '2', 0, ''),
(14802, 3610, 'إِنَّكُمْ أَغْبَطُ بِما بَذَلْتُمْ مِنَ الرّاغِبِ إِلَيْكُمْ بِما وَصَلَهُ مِنْكُمْ.', NULL, '7', '26', '214', '752', '2', 0, ''),
(14803, 3611, 'إِنَّكُمْ إِلى عَمارَةِ دارِ الْبَقاءِ أَحْوَجُ مِنْكُمْ إِلى عِمارَةِ دارِ الْفَناءِ.', NULL, '7', '26', '214', '752', '2', 0, ''),
(14804, 3612, 'إِنَّكُمْ في زَمانٍ الْقائِلُ بِالحَقِّ فيهِ قَليلٌ وَ اللِّسانُ فيهِ عَنِ الصِّدْقِ كَليلٌ وَ
اللّازِمُ فيهِ لِلْحَقِّ ذَليلٌ، أَهْلُهُ مَعْتَكِفُونَ عَلى الْعِصْيانِ، مُصْطَلِحُونَ عَلى الْإِدِّهانِ،
فَتاهُمْ عارِمٌ وَ شَيْخُهُمْ آثِمٌ وَ عالِمُهُمْ مُنافِقٌ وَ قاريهِمْ مُماذِقٌ، لا يُعَظِّمُ صَغيرُهُمْ
كَبيرَهُمْ وَ لا يَعُولُ غَنِيُّهُمْ فَقيرَهُمْ.', NULL, '7', '26', '214', '752', '2', 0, ''),
(14805, 3613, 'إِنَّكُمْ سَتُعْرَضُونَ عَلى سَبِّي وَ الْبَراءَ ةِ مِنِّي، فَسُبُّوني وَ لا تَتَبَرَّؤُا مِنّي فَإِنّي وُلِدْتُ عَلى الْفِطْرَةِ.', NULL, '7', '26', '214', '752', '2', 0, ''),
(14806, 3614, 'إِنَّكُمْ بِأَعْمالِكُمْ مُجازُونَ وَ بِها مُرْتَهَنُونَ.', NULL, '7', '26', '214', '752', '2', 0, ''),
(14807, 3615, 'إِنَّكُمْ إِلى الْاخِرَةِ صائِرُونَ وَ عَلى اللهِ مُعْرَضُونَ.', NULL, '7', '26', '214', '752', '2', 0, ''),
(14808, 3616, 'إِنَّكُمْ حَصائِدُ الْاجالِ وَ أَغْراضُ الْحِمامِ.', NULL, '7', '26', '214', '752', '2', 0, ''),
(14809, 3617, 'إِنَّكُمْ إِلى الْإِهْتِمامِ بِما يَصْحَبُكُمْ مِنَ الْاخِرَةِ أَحْوَجُ مِنْكُمْ إِلى كُلِّ ما يَصْحَبُكُمْ مِنَ الدُّنْيا.', NULL, '7', '26', '214', '752', '2', 0, ''),
(14810, 3618, 'إِنَّكُمْ إِلى أَزْوادِ التَّقْوى أَحْوَجُ مِنْكُمْ إِلى أَزْوادِ الدُّنْيا.', NULL, '7', '26', '214', '752', '2', 0, ''),
(14811, 3619, 'إِنَّكُمْ هَدَفُ النَّوائِبِ وَ دَرِيئةُ الْأَسْقامِ.', NULL, '7', '26', '214', '752', '2', 0, ''),
