(15309, 4117, 'تَحَبَّبْ إِلى خَليلِكَ يُحْبِبْ وَ أَكْرِمْهُ يُكْرِمْكَ وَ آثِرْهُ عَلى نَفْسِكَ يُؤْثِرْكَ عَلى نَفْسِه وَ أَهْلِه.', NULL, '7', '28', '221', '759', '2', 0, ''),
(15310, 4118, 'تَحَرَّ رِضَى اللهِ بِرِضاكَ بِقَدَرِه.', NULL, '7', '28', '221', '759', '2', 0, ''),
