(15420, 4228, 'ثَلاثٌ تُمْتَحَنُ بِهِنَّ عُقُولُ الرِّجالِ: هُنَّ الْوَلايَةُ، وَ الْمالُ، وَ الْمُصيبَةُ.', NULL, '7', '29', '223', '761', '2', 0, ''),
(15421, 4229, 'ثَلاثٌ مُهْلِكاتٌ: طاعَةُ النِّساءِ، وَ طاعَةُ الْغَضَبِ، وَ طاعَةُ الشَّهْوَةِ.', NULL, '7', '29', '223', '761', '2', 0, ''),
(15422, 4230, 'ثَلاثٌ لا يُسْتَحْيى مِنْهُنَّ: خِدْمَةُ الرَّجُلِ ضَيْفَهُ، وَ قِيامُهُ عَنْ مَجْلِسِه لِأَبيهِ وَمُعَلِّمِه، وَ طَلَبُ الْحَقِّ وَ إِنْ قَلَّ.', NULL, '7', '29', '223', '761', '2', 0, ''),
(15423, 4231, 'ثَلاثٌ مَنْ جِماعِ الْمَوَدَّةِ: عَطاءٌ مِنْ غَيرِ مَسْأَلَةٍ، وَ وَفاءٌ مِنْ غَيرِ عَهْدِ، وُجُودٌ مَعَ إِقْلالٍ.', NULL, '7', '29', '223', '761', '2', 0, ''),
(15424, 4232, 'ثَلاثٌ مِنْ كُنُوزِ الْجَنَّةِ: كِتْمانُ الْمُصيبَةِ، وَ الصَّدَقَةُ، وَ الْمَرَضُ.', NULL, '7', '29', '223', '761', '2', 0, ''),
(15425, 4233, 'ثَلاثٌ مِنْ أَعْظَمِ الْبَلاءِ: كَثْرَةُ الْعائِلَةِ، وَ غَلَبَةُ الدَّيْنِ، وَ دَوامُ الْمَرَضِ.', NULL, '7', '29', '223', '761', '2', 0, ''),
(15426, 4234, 'ثَلاثٌ هُنَّ الْمُحْرِقاتُ الْمُوبِقاتُ: فَقْرٌ بَعْدَ غِنىً، وَ ذُلٌّ بَعْدَ عِزٍّ، وَ فَقْدُ الْأَحِبَّةِ.', NULL, '7', '29', '223', '761', '2', 0, ''),
(15427, 4235, 'ثَلاثٌ يُوجِبْنَ الْمَحَبَّةَ: حُسْنُ الْخُلْقِ، وَ حُسْنُ الرِّفْقِ، وَ التَّواضُعُ.', NULL, '7', '29', '223', '761', '2', 0, ''),
(15428, 4236, 'ثَلاثَةٌ يُدْخِلُهُمُ اللهُ الْجَنَّةَ بِغَيرِ حِسابٍ: إِمامٌ عادِلٌ، وَ تاجِرٌ صَدُوقٌ، وَ شَيْخٌ أَفْنى عُمْرَهُ في طاعَةِ اللهِ.', NULL, '7', '29', '223', '761', '2', 0, ''),
(15429, 4237, 'ثَلاثَةٌ يُدْخِلُهُمُ اللهُ النّارَ بِغَيرِ حِسابٍ: إِمامٌ جائِرٌ، وَ تاجِرٌ كَذُوبٌ، وَ شَيْخٌ زانٍ.', NULL, '7', '29', '223', '761', '2', 0, ''),
(15430, 4238, 'ثَلاثَةٌ في ظِلِّ عَرْشِ اللهِ تَعالى يَوْمَ لا ظِلَّ إِلّا ظِلُّهُ: رَجُلٌ أَنْصَفَ النّاسَ مِنْ
نَفْسِه، وَ رَجُلٌ لَمْ يُقَدِّمْ رِجْلاً وَ لَمْ يُؤَخِّرْ رِجْلاً حَتّى يَعْلَمَ أَنَّ ذلِكَ لِلّهِ رِضىً أَوْ سَخَطٌ،
وَ رَجُلٌ لَمْ يَعِبْ أَخاهُ بِعَيْبٍ حَتّى يَنْفي ذلِكَ مِنْ نَفْسِه فَإِنَّهُ لا يَخْفى مِنْهُ عَيْبٌ إِلّا بَدا
لَهُ عَيْبٌ آخَرُ وَ كَفى بِالْمَرْءِ شُغْلاً بِنَفْسِه عَنِ النّاسِ.', NULL, '7', '29', '223', '761', '2', 0, ''),
(15431, 4239, 'ثَلاثَةٌ هُمْ أَقْرَبُ الْخَلْقِ إِلى اللهِ تَعالى: رَجُلٌ مَشى بَينَ اثْنَيْنِ فَلَمْ يَمِلْ مَعَ
أَحَدِهِما عَلى الْاخَرِ بِشَعيرَةٍ، وَ رَجُلٌ لَمْ تَدْعُهُ قُدْرَتُهُ في حالِ غَضَبِه إِلى أَنْ يَحيفَ عَلى
مَنْ تَحْتَ يَدَيْهِ، وَ رَجُلٌ قالَ الْحَقَّ فيما لَهُ وَ عَلَيْهِ.', NULL, '7', '29', '223', '761', '2', 0, ''),
(15432, 4240, 'ثَلاثٌ منْ كُنَّ فيهِ فَقَدْ كَمُلَ إِيمانُهُ: سُنَّةٌ مِنْ رَبِّه، وَ سُنَّةٌ مِنْ نَبِيِّه، وَ سُنَّةٌ
مِنْ وَلِيِّه، فَالسُّنّةُ مِنْ رَبِّه كِتْمانُ سِرِّه قالَ اللهُ تَعالى: ''عالِمُ الْغَيْبِ فَلا يُظْهِرُ
عَلى غَيْبِه أَحَداً إِلّا مَنِ ارْتَضى مِنْ رَسُولٍ''، وَ أَمَّا السُّنَّةُ مِنْ نَبِيِّه فَمُداراةُ النّاسَ
قالَ اللهُ عَزَّ وَ جَلَّ: ''خُذِ الْعَفْوَ وَ أْمُرْ بِالْعُرْفِ وَ أَعْرِضْ عَنِ الْجاهِلينَ''، وَ أَمَّا
السُّنَّةُ مِنْ وَلِيِّه فَالصَّبْرُ فِي الْبَأْساءِ وَ الضَّرّاءِ قالَ اللهُ تَعالى: ''وَ الصّابِرينَ فِي
الْبَأْساءِ وَ الضَّرّاءِ''.', NULL, '7', '29', '223', '761', '2', 0, ''),
(15433, 4241, 'ثَلاثٌ لا تَكُونُ فِي الْمُؤْمِنِ: لا يَكُونُ جَباناً، وَ لا حَريصاً، وَ لا شَحيحاً.', NULL, '7', '29', '223', '761', '2', 0, ''),
(15434, 4242, 'ثَلاثَةٌ لا يَنْتَصِفُونَ مِنْ ثَلاثَةٍ: شَريفٌ مِنْ وَضيعٍ، وَ حَليمٌ مِنْ سَفيهٍ، وَ بَرٌّ مِنْ فاجِرٍ.', NULL, '7', '29', '223', '761', '2', 0, ''),
(15435, 4243, 'ثَلاثَةٌ حَقٌّ أَنْ يُرْحَمُوا: عَزيزٌ أَصابَتْهُ مَذَلَّةٌ بَعْدَ الْعِزِّ، وَ غَنِيٌّ أَصابَتْهُ حاجَةٌ بَعْدَ الْغِنى، وَ عالِمٌ يَسْتَخِفُّ بِه قَوْمُهُ وَ جُهّالُ أَهْلِه.', NULL, '7', '29', '223', '761', '2', 0, ''),
(15436, 4244, 'ثَلاثٌ يَحْسُنُ فيهِ الْكِذْبُ: الْمَكيدَةُ فِي الْحَرْبِ، وَ عِدَتُكَ زَوْجَتَكَ، وَ الْإِصْلاحُ بَينَ النّاسِ.', NULL, '7', '29', '223', '761', '2', 0, ''),
(15437, 4245, 'ثَلاثٌ يَقْبُحُ فيهِنَّ الصِّدْقُ: النَّميمَةُ، وَ إِخْبارُ|كَ| الرَّجُلِ عَنْ أَهْلِه بِما يَكْرَهُهُ، وَ تَكْذيبُكَ الرَّجُلَ عَنِ الْخَبَرِ.', NULL, '7', '29', '223', '761', '2', 0, ''),
(15438, 4246, 'ثَلاثةٌ مُجالَسَتُهُمْ تُميتُ الْقُلُوبَ: مُجالَسَةُ الْأَنْذالِ، وَ الْحَديثُ مَعَ النِّساءِ، وَمُجالَسَةُ الْأَغْنِياءِ.', NULL, '7', '29', '223', '761', '2', 0, ''),
(15439, 4247, 'ثَلاثٌ هُنَّ جِماعُ الْخَيرِ: إِسْداءُ النِّعَمِ، وَ رِعايَةُ الذِّمَمِ، وَ صِلَةُ الرَّحِمِ.', NULL, '7', '29', '223', '761', '2', 0, ''),
(15440, 4248, 'ثَلاثٌ بِثَلاثٍ: مَنْ صَدَقَ لِسانُهُ زَكى عَمَلُهُ، وَ مَنْ حَسُنَتْ نِيَّتُهُ زادَ اللهُ في رِزْقِه، وَ مَنْ حَسُنَ بِرُّهُ بِأَهْلِه زادَ اللهُ في عُمْرِه.', NULL, '7', '29', '223', '761', '2', 0, ''),
(15441, 4249, 'ثَلاثُ خِصالٍ هِيَ أُصُولُ الْكُفْرِ: الْحِرْصُ، وَ الْإِسْتِكْبارُ، وَ الْحَسَدُ. فَأَمَّا الْحِرْصُ
فَآدَمُ حينَ نُهِيَ عَنِ الشَّجَرَةِ حَمَلَهُ الْحِرْصُ عَلى أَنْ يَأْكُلَ مِنْها، وَ أَمَّا الْإِسْتِكْبارُ
فَإِبْليسُ حينَ أُمِرَ بِالسُّجُودِ فَأَبى، وَ أَمَّا الْحَسَدُ فَابْنا آدَمَ حينَ قَتَلَ أَحَدُهُمَا الْاخَرَ
حَسَداً.', NULL, '7', '29', '223', '761', '2', 0, ''),
(15442, 4250, 'ثَلاثٌ لا يَنْظُرُ اللهُ إِلَيْهِمْ: الْعامِلُ بِالظُّلْمِ، وَ الْمُعينُ عَليْهِ، وَ الرّاضي بِه.', NULL, '7', '29', '223', '761', '2', 0, ''),
(15443, 4251, 'ثَلاثٌ قاصِماتٌ لِلظَّهْرِ، رَجُلٌ اسْتَكْثَرَ عِلْمَهُ، وَ نَسِيَ ذُنوبَهُ، وَ أُعْجِبَ بِرَأْيِه.', NULL, '7', '29', '223', '761', '2', 0, ''),
(15444, 4252, 'ثَلاثٌ تُكْمِلُ الْمُسْلِمَ: الفِقْهُ فِي الدِّيْنِ، وَ التَّقْديرُ فِي الْمَعيشَةِ، وَ الصَّبْرُ عَلى النَّوائِبِ.', NULL, '7', '29', '223', '761', '2', 0, ''),
(15445, 4253, 'ثَلاثٌ لَمْ يَجْعَلِ اللهُ لِأَحَدٍ مِنَ النّاسِ فيهِنَّ رُخْصَةً: بِرُّ الوالِدَيْنِ بَرَّيْنِ كانا أوْ فاجِرَيْنِ، وَ وَفاءٌ بِالْعَهْدِ لِلْبَرِّ وَ الْفاجِرِ، وَ أَداءُ الْأَمانَةِ لِلْبَرِّ وَ الْفاجِرِ.', NULL, '7', '29', '223', '761', '2', 0, ''),
(15446, 4254, 'ثَلاثَةٌ يَشْكُونَ إِلى اللهِ: مَسْجِدٌ خَرابٌ لا يُصَلّي فيهِ أَهْلُهُ، وَ عالِمٌ بَينَ جاهِلٍ، وَ مُصْحَفٌ مُعَلَّقٌ قَدْ وَقَعَ عَلَيْهِ غُبارٌ لا يُقْرَءُ فيهِ.', NULL, '7', '29', '223', '761', '2', 0, ''),
(15447, 4255, 'ثَلاثَةٌ يَشْكُونَ يَوْمَ الْقِيامَةِ: المُصْحَفُ، وَ المَسْجِدُ، وَ العِتْرَةُ، يَقُولُ الْمُصْحَفُ:
يا رَبِّ حَرَّقُوني وَ مَزَّقُوني، وَيَقُولُ الْمَسْجِدُ: يا رَبِّ عَطَّلُوني وَ ضَيَّعُوني، وَ تَقُولُ
الْعِتْرَةُ: يا رَبِّ غَصَبُوني وَ طَرَدُوني وَ شَرَّدُوني.
', NULL, '7', '29', '223', '761', '2', 0, ''),
(15448, 4256, 'ثَلاثَةٌ لا يَدْخُلُونَ الْجَنَّةَ: سَفّاكُ دَمٍ حَرامٍ، وَ عاقُّ والِدَيْهِ، ومَشَّاءٌ بِنَميمَةٍ.', NULL, '7', '29', '223', '761', '2', 0, ''),
(15449, 4257, 'ثَلاثةٌ لا يُكَلِّمُهُمُ اللهُ تَعالى: المنّانُ الَّذي لا يُعْطي شَيْئاً إِلّا يَمُنُّهُ، وَ الْمُسْبِلُ إِزارَهُ، وَ الْمُنْفِقُ سِلْعَتَهُ بِالأيْمانِ الْفاجِرَةِ.', NULL, '7', '29', '223', '761', '2', 0, ''),
(15450, 4258, 'ثَلاثَةٌ لا يَدْخُلُونَ الْجَنَّةَ: مُدْمِنُ خَمْرٍ، وَ مُدْمِنُ سِحْرٍ، وَ قاطِعُ رَحِمٍ.', NULL, '7', '29', '223', '761', '2', 0, ''),
(15451, 4259, 'ثَمانِيَةٌ إِنْ أُهينُوا فَلا يَلوُمُوا إِلّا أَنْفُسَهُمْ: الذّاهِبُ إِلى مائِدَةٍ لَمْ يُدْعَ
إِلَيْها، وَ الْمُتَأَمِّرُ عَلى رَبِّ الْبَيْتِ، وَ طالِبُ الْخَيْرِ مِنْ أَعْدائِه، وَ طالِبُ الْفَضْلِ مِنَ
اللِّئامِ، وَ الدّاخِلُ بَينَ اثْنَيْنِ في شَيْ ءٍ لا يُدْخِلانِه فيهِ، وَ الْمُسْتَخِفُّ بِالسُّلْطانِ، وَ
الْجالِسُ في مَجْلِسٍ لَيْسَ لَهُ بِأَهْلٍ، وَ الْمُقْبِلُ بِالْحَديثِ عَلى مَنْ لا يَسْمَعُ مِنْهُ.', NULL, '7', '29', '224', '762', '2', 0, ''),
(15452, 4260, 'ثَوْبُ التُّقى أَشْرَفُ الْمَلابِسِ.', NULL, '7', '29', '224', '762', '2', 0, ''),
(15453, 4261, 'ثَوْبُ الْعافِيَةِ أَهْنَأُ الْمَلابِسِ.', NULL, '7', '29', '224', '762', '2', 0, ''),
(15454, 4262, 'ثَوابُ الْعَمَلِ ثَمَرَةُ الْعَمَلِ.', NULL, '7', '29', '224', '762', '2', 0, ''),
(15455, 4263, 'ثَبَاتُ الْدُّوَلِ بِإِقامَةِ الْعَدْلِ.', NULL, '7', '29', '224', '762', '2', 0, ''),
(15456, 4264, 'ثَوابُ الْجِهادِ أَعْظَمُ الثَّوابِ.', NULL, '7', '29', '224', '762', '2', 0, ''),
(15457, 4265, 'ثَوابُ الْاخِرَةِ يُنْسي مَشَقَّةَ الدُّنْيا.', NULL, '7', '29', '224', '762', '2', 0, ''),
(15458, 4266, 'ثَوابُ الْمُصيبَةِ عَلى قَدْرِ الصَّبْرِ عَلَيْها.', NULL, '7', '29', '224', '762', '2', 0, ''),
(15459, 4267, 'ثَرْوَةُ الدُّنْيا فَقْرُ الْاخِرَةِ.', NULL, '7', '29', '224', '762', '2', 0, ''),
(15460, 4268, 'ثَرْوَةُ الْاخِرَةِ تُنْجي وَ تَبْقى.', NULL, '7', '29', '224', '762', '2', 0, ''),
(15461, 4269, 'ثَرْوَةُ الْمالِ تُطْغي وَ تُرْدي وَ تَفْنى.', NULL, '7', '29', '224', '762', '2', 0, ''),
(15462, 4270, 'ثابِرُوا عَلى الطّاعاتِ وَ سارِعُوا إِلى الْخَيراتِ وَ تَجَنَّبُوا السَّيِّئاتِ وَ بادِرُوا إِلى الْحَسَناتِ وَ تَجَنَّبُوا ارْتِكابَ الْمَحارِمِ.', NULL, '7', '29', '224', '762', '2', 0, ''),
(15463, 4271, 'ثَباتُ الدِّينِ بِقُوَّةِ الْيَقينِ.', NULL, '7', '29', '224', '762', '2', 0, ''),
(15464, 4272, 'ثَمَنُ الْجَنَّةِ الزُّهْدُ في الدُّنْيا.', NULL, '7', '29', '224', '762', '2', 0, ''),
(15465, 4273, 'ثَوْبُ الْعِلمِ يُخَلِّدُكَ وَ لا يَبْلى وَ يُبْقيكَ وَ لا يَفْنى.', NULL, '7', '29', '224', '762', '2', 0, ''),
