(15799, 4607, 'خَفْضُ الصَّوْتِ وَ غَضُّ الْبَصَرِ وَ مَشْيُ الْقَصْدِ مِنْ أَمارَةِ الْإِيمانِ وَ حُسْنِ الدِّين.', NULL, '7', '32', '229', '767', '2', 0, ''),
(15800, 4608, 'خُذْ عَلى عَدُوِّكَ بِالْفَضْلِ فَإِنَّهُ أَحَدُ الظَّفَرَيْنِ.', NULL, '7', '32', '229', '767', '2', 0, ''),
(15801, 4609, 'خَرَق عِلْمُ اللهِ سُبْحانَهُ باطِنَ غَيْبِ السُّتَراتِ وَ أَحاطَ بِغُمُوضِ عَقائِدِ السَّريراتِ.', NULL, '7', '32', '229', '767', '2', 0, ''),
(15802, 4610, 'خُذُوا مَهَلَ الْأَيّامِ وَ حُوطُوا قَواصِيَ الْإِسْلامِ وَ بادِرُوا هُجُومَ الْحَمامِ.', NULL, '7', '32', '229', '767', '2', 0, ''),
(15803, 4611, 'خُضِ الْغَمراتِ إِلى الْحَقِّ حَيْثُ كانَ.', NULL, '7', '32', '229', '767', '2', 0, ''),
(15804, 4612, 'خَوْضُ النّاسِ فِي الشَّيْ ءِ مُقَدِّمَةُ الْكائِنِ.', NULL, '7', '32', '229', '767', '2', 0, ''),
(15805, 4613, 'خُلْطَةُ أَبْناءِ الدُّنْيا تَشينُ الدِّينَ وَ تُضْعِفُ الْيَقينَ.', NULL, '7', '32', '229', '767', '2', 0, ''),
(15806, 4614, 'خَطَرُ الدُّنْيا يَسيرٌ وَ عاجِلُها حَقيرٌ وَ بَهْجَتُها زور وَ مَواهبُها غُرُورٌ.', NULL, '7', '32', '229', '767', '2', 0, ''),
(15807, 4615, 'خِيانَةُ الْمُسْتَسْلِم وَ الْمُسْتَشيرِ مِنْ أَفْظَعِ الْاُمُورِ وَ أَعْظَمِ الشُّرُورِ وَ مُوجِبَةُ عَذابِ السَّعير.', NULL, '7', '32', '229', '767', '2', 0, ''),
(15808, 4616, 'خُذْ مِنْ صالِحِ الْعَمَلِ وَ خالِلْ خَيْرَ خليلٍ فَإِنَّ لِلْمَرْء مَا اكْتَسَبَ وَ هُوَ فِي الْقِيامَةِ مَعَ مَنْ أَحَبَّ.', NULL, '7', '32', '229', '767', '2', 0, ''),
(15809, 4617, 'خَشْيَةُ اللهِ جَناحُ الْإِيمانِ.', NULL, '7', '32', '229', '767', '2', 0, ''),
(15810, 4618, 'خَوْفُ اللهِ يُوجِبُ الْأَمانَ.', NULL, '7', '32', '229', '767', '2', 0, ''),
(15811, 4619, 'خَفِ اللهَ يُؤْمِنْكَ وَ لا تَأْمَنْهُ يُعَذِّبْكَ.', NULL, '7', '32', '229', '767', '2', 0, ''),
(15812, 4620, 'خُذِ الْعَفْوَ مِنَ النّاسِ وَ لا تَبْلُغْ مِنْ أَحَدٍ مَكْرُوهَهُ.', NULL, '7', '32', '229', '767', '2', 0, ''),
(15813, 4621, 'خَليلُ الْمَرْءِ دَليلُ عَقْلِه وَ كَلامُهُ بُرْهانُ فَضْلِه.', NULL, '7', '32', '229', '767', '2', 0, ''),
(15814, 4622, 'خالفْ نَفْسَكَ تَسْتَقِمْ وَ خالِطِ الْعُلَماءَ تَعْلَمْ.', NULL, '7', '32', '229', '767', '2', 0, ''),
(15815, 4623, 'خُذْ مِنْ كُلِّ عِلْمٍ أَحْسَنَهُ فَإِنَّ النَّحْلَ يَأْكُلُ مِنْ كُلِّ زَهْرٍ أَزْيَنَهُ فَتُولَدُ مِنْهُ جَوْهَرانِ نَفيسانِ: أَحَدُهُما فيهِ شِفاءٌ لِلنّاسِ وَ الْاخَرُ يُسْتَضاءُ بِه.', NULL, '7', '32', '229', '767', '2', 0, ''),
(15816, 4624, 'خُذِ الْعَدْلَ وَ ائْتِ بِالْفَضْلِ تَحُزِ الْمَنْقَبَتَينِ.', NULL, '7', '32', '229', '767', '2', 0, ''),
(15817, 4625, 'خُذْ مِنْ أَمْرِكَ ما يَقُومُ بِه عُذْرُكَ وَ تَثْبُتَ بِه حُجَّتُكَ.', NULL, '7', '32', '229', '767', '2', 0, ''),
(15818, 4626, 'خُذْ مِمّا لا يَبْقى لَكَ لِما يَبْقى لَكَ وَ لا يُفارِقُك.', NULL, '7', '32', '229', '767', '2', 0, ''),
(15819, 4627, 'خُذِ الْقَصْدَ فِي الْاُمُورِ فَمَنْ أَخَذَ الْقَصْدَ خَفَّتْ عَلَيْه الْمُؤُنُ.', NULL, '7', '32', '229', '767', '2', 0, ''),
(15820, 4628, 'خُذِ الْحِكْمَةَ أَنّى كانَتْ فَإِنَّ الْحِكْمَةَ ضالَّةُ كُلِّ مُؤْمِنٍ.', NULL, '7', '32', '229', '767', '2', 0, ''),
(15821, 4629, 'خُذْ بِالْحَزْمِ وَ الْزَمِ الْعَزْمَ تُحْمَدْ عَواقِبُكَ.', NULL, '7', '32', '229', '767', '2', 0, ''),
(15822, 4630, 'خُذُوا مِنْ كَرائِمِ أَمْوالِكُمْ ما يَرْفَعُ لَكُمْ بِه اللهِ سَنِيَّ الْأَعْمالِ.', NULL, '7', '32', '229', '767', '2', 0, ''),
(15823, 4631, 'خُذْ مِنَ الدُّنْيا ما أَتاكَ وَ تَوَلَّ عَمَّا تَوَلَّى مِنْها عَنْكَ فَإِنْ لَمْ تَفْعَلْ فَأَجْمِلْ فِي الطَّلَبِ.', NULL, '7', '32', '229', '767', '2', 0, ''),
(15824, 4632, 'خالِطُوا النّاسَ بِأَلْسِنَتِكُمْ وَ أَجْسادِكُمْ وَ زايِلُوُهْم بِقُلُوبِكُمْ وَ أَعْمالِكُمْ.', NULL, '7', '32', '229', '767', '2', 0, ''),
(15825, 4633, 'وَ قال عليه السّلام في حقِّ قومٍ ذَمَّهُمْ: خفَّتْ عُقُولُكُمْ وَسَفِهَتْ حُلُومُكُمْ فَأَنْتُمْ غَرَضٌ لِنابِلٍ وَأْكْلَةٌ لِاكِلٍ وَ فَريسَةٌ لِصائِلٍ.', NULL, '7', '32', '229', '767', '2', 0, ''),
(15826, 4634, 'وَ قال أيضاً: خَذلُوا الْحَقَّ وَ لَمْ يَنْصُرُوا الْباطِلَ.', NULL, '7', '32', '229', '767', '2', 0, ''),
(15827, 4635, 'خُلُوُّ الْقَلْبِ مِنَ التَّقْوى يَمْلَاُهُ مِنْ فِتَنِ الدُّنْيا.', NULL, '7', '32', '229', '767', '2', 0, ''),
(15828, 4636, 'خَمْسَةٌ يَنْبَغي أَنْ يُهانُوا: الدّاخِلُ بَينَ اثْنَينِ لَمْ يُدْخِلاهُ في أَمْرِهِما، وَ
الْمُتَأَمِّرُ عَلى صاحِبِ الْبَيْتِ في بَيْتِه، وَ الْمُتَقَدِّمُ إِلى مائِدَةٍ لَمْ يُدْعَ إِلَيْها، وَ
الْمُقْبِلُ بِحَديثِه عَلى غَيرِ مُسْتَمِعٍ، وَ الْجالِسُ فِي الْمَجالِسِ الَّتي لا يَسْتَحِقُّها.', NULL, '7', '32', '229', '767', '2', 0, ''),
(15829, 4637, 'خَمْسٌ تُسْتَقْبَحُ مِنْ خَمْسَةٍ: كَثْرَةُ الْفُجُورِ مِنَ الْعُلَماءِ، وَ الْحِرْصُ مِنَ الْحُكَماءِ، وَ الْبُخْلُ مِنَ الْأَغْنِياءِ، وَ الْقِحَةُ مِنَ النِّساء، وَ مِنَ الْمَشايِخِ الزِّنا.', NULL, '7', '32', '229', '767', '2', 0, ''),
(15830, 4638, 'خُلُوُّ الصَّدْرِ مِنَ الْغِلِّ وَ الْحَسَدِ مِنْ سَعادَةِ الْمُتَعَبِّدِ.', NULL, '7', '32', '229', '767', '2', 0, ''),
(15831, 4639, 'خُذْ مِمّا لا تَبْقَى لَهُ وَ لا يَبْقى لَكَ لِما لا تُفارِقُهُ وَ لا يُفارِقُكَ.', NULL, '7', '32', '229', '767', '2', 0, ''),
(15832, 4640, 'خَمْسُ خِصالٍ مِنْ عَلاماتِ الْمُؤْمِنِ: الوَرَعُ فِي الْخَلْوَةِ، وَ الصَّدَقَةُ فِي الْقِلَّةِ، وَ
الصَّبْرُ عِنْدَ الْمُصيبَةِ، وَ الْحِلْمُ عِنْدَ الْغَضَبِ، وَ الصِّدْقُ عِنْدَ الْخَوْفِ.', NULL, '7', '32', '229', '767', '2', 0, ''),
(15833, 4641, 'خَمْسٌ مِنْ خَمْسَةٍ مُحالٌ: النَّصيحَةُ مِنَ الْحاسِدِ مُحالٌ، وَ الشَّفَقَةُ مِنَ الْعَدُوِّ مُحالٌ،
وَ الْحُرْمَةُ مِنَ الْفاسِقِ مُحالٌ، وَ الْوَفاءُ مِنَ الْمَرْأةِ مُحالٌ، وَ الْهَيْبَةُ مِنَ الْفَقيرِ مُحالٌ.', NULL, '7', '32', '229', '767', '2', 0, ''),
(15834, 4642, 'خَمْسَةٌ مِنْ عَلاماتِ الْقائِمِ عليه السّلام: اليَمانِيُّ مِنَ الْيَمَنِ، وَ السُّفْيانِيُّ،
وَ الْمُنادي يُنادي بِالسَّماءِ، وَ خَسْفٌ بِالْبَيْداءِ، وَ قَتْلُ النَّفْسِ الزَّكِيَّةِ.', NULL, '7', '32', '229', '767', '2', 0, ''),
(15835, 4643, 'خَمْسٌ لَوْ رَحِلْتُمْ لَهُنَّ ما قَدَرْتُمْ عَلى مِثْلِهِنَّ: لا يَخافُ عَبْدٌ إِلّا ذَنْبَهُ، وَ لا
يَرْجُو إِلّا رَبَّهُ، وَ لا يَسْتَحْيي |الجاهِلُ| إِذا سُئِلَ عَمّا لا يَعْلَمُ أَنْ يَتَعَلَّمَ، وَ الصَّبْرُ
مِنَ الْإِيمانِ بِمَنْزِلَةِ الرَّأْسِ مِنَ الْجَسَدِ وَ لا إِيمانَ لِمَنْ لا صَبْرَ لَهُ.', NULL, '7', '32', '229', '767', '2', 0, ''),
(15836, 4644, 'خالِفُوا أَصْحابَ السُّكْرِ وَ كُلُوا التَّمْرَ فَإِن فيهِ شِفاءٌ مِنَ الْأَدْواءِ.', NULL, '7', '32', '229', '767', '2', 0, ''),
(15837, 4645, 'خِيارُ خِصالِ النِّساءِ شَرُّ خِصالِ الرَّجُلِ: الزَّهْوُ وَ الْجُبْنُ وَ الْبُخْلُ فَإِذا كانَتِ
الْمَرْأَةُ مَزْهُوَّةً لَمْ تُمَكِّنْ مِنْ نَفْسِها وَ إِذا كانَتْ بَخيلَةً حَفِظَتْ ما لَها وَ مالَ بَعْلِها وَ
إِذا كانَتْ جَبانَةً فَرَّتْ مِنْ كُلِّ شيْ ءٍ يَعْرُضُ لَها.', NULL, '7', '32', '229', '767', '2', 0, ''),
(15838, 4646, 'خَصْلَتانِ فيهِما جِماعُ الْمُرُوَّةِ: اجْتِنابُ الرَّجُل ما يَشينُهُ، وَ اكْتِسابُهُ ما يَزينُهُ.', NULL, '7', '32', '229', '767', '2', 0, ''),
(15839, 4647, 'خَوافِي الْأَخْلاقِ يَكْشِفُهَا الْمُعاشَرَةُ.', NULL, '7', '32', '229', '767', '2', 0, ''),
(15840, 4648, 'خَوافِي الْاراءِ يَكْشِفُهَا الْمُشاوَرَةُ.', NULL, '7', '32', '229', '767', '2', 0, ''),
(15841, 4649, 'خِدْمَةُ النَّفْسِ صِيانَتُها عَنِ اللَّذّاتِ وَالْمُقْتَنَياتِ وَ رِياضَتُها بِالْعُلُومِ وَ الْحِكَمِ وَ اجْتِهادُها بِالْعِباداتِ وَ الطّاعاتِ وَ في ذلِكَ نَجاةُ النَّفْسِ.', NULL, '7', '32', '229', '767', '2', 0, ''),
(15842, 4650, 'خِدْمَةُ الْجَسَدِ إِعْطاءُ هُ ما يَسْتَدْعيهِ مِنَ الْمَلاذِّ وَ الشَّهَواتِ وَ الْمُقْتَنَياتِ وَ في ذلِكَ هَلاكُ النَّفْسِ.', NULL, '7', '32', '229', '767', '2', 0, ''),
(15843, 4651, 'وَ قال عليه السّلام في ذكر رسول الله صلّى الله عليه و آله:

خَرَجَ مِنَ الدُّنْيا خَميصاً وَ وَرَدَ الْاخِرَةَ سَليماً لَمْ يَضَعْ حَجَراً عَلى حَجَرٍ حَتَّى مَضى لِسَبيلِه وَ أَجابَ داعِيَ رَبِّه.
', NULL, '7', '32', '229', '767', '2', 0, ''),
(15844, 4652, 'دَليلُ دينِ الرَّجُلِ وَرَعُهُ.', NULL, '7', '33', '230', '768', '2', 0, ''),
(15845, 4653, 'دَليلُ وَرَعِ الرَّجُلِ نَزاهَتُهُ.', NULL, '7', '33', '230', '768', '2', 0, ''),
(15846, 4654, 'دَعْ ما لا يَعْنيكَ وَ اشْتَغِلْ بِمُهِمَّكَ الَّذي يُنْجيكَ.', NULL, '7', '33', '230', '768', '2', 0, ''),
(15847, 4655, 'دَعْ ما يُريبُكَ إِلى ما لا يُريبُكَ.', NULL, '7', '33', '230', '768', '2', 0, ''),
(15848, 4656, 'دَوامُ الصَّبْرِ عِنْوانُ الظَّفَرِ |وَ النَّصر|.', NULL, '7', '33', '230', '768', '2', 0, ''),
(15849, 4657, 'دَعِ السَّفَهَ فَإِنَّهُ يُزْري بِالْمَرْءِ وَ يَشْينُهُ.', NULL, '7', '33', '230', '768', '2', 0, ''),
(15850, 4658, 'دَعِ الْقَوْلَ فيما لا تَعْرِفُ وَالْخِطابَ فيما لاتُكَلَّفُ وَ أَمْسِكْ عَنْ طَريقٍ إِذا خِفْتَ ضَلالَتَهُ.', NULL, '7', '33', '230', '768', '2', 0, ''),
(15851, 4659, 'دَعِ الْإِنْتِقامَ فَإِنَّهُ مِنْ أَسْوَءِ أَفْعالِ الْمُقْتَدِرِ وَ لَقَدْ أَخَذَ بِجَوامِعِ الْفَضْلِ مَنْ رَفَعَ نَفْسَهُ عَنْ سَيِّى ءِ الْمُجازاةِ.', NULL, '7', '33', '230', '768', '2', 0, ''),
(15852, 4660, 'دَوامُ الْفِتَنِ مِنْ أَعْظَمِ الْمِحَنِ.', NULL, '7', '33', '230', '768', '2', 0, ''),
(15853, 4661, 'دَوامُ الطّاعاتِ وَ فِعْلُ الْخَيراتِ وَالْمُبادَرَةُ إِلى الْمَكْرُماتِ مِنْ كَمالِ الْإِيمانِ وَ أَفْضَلِ الْإِحْسانِ.', NULL, '7', '33', '230', '768', '2', 0, ''),
(15854, 4662, 'دَليلُ عَقْلِ الرَّجُلِ قَوْلُهُ.', NULL, '7', '33', '230', '768', '2', 0, ''),
(15855, 4663, 'دَليلُ أَصْلِ الرَّجُلِ فِعْلُهُ.', NULL, '7', '33', '230', '768', '2', 0, ''),
