(18210, 7018, 'لَمْ يَخْلُقِ اللهُ سُبْحانَهُ الْخَلْقَ لِوَحْشَتِهِ وَ لَمْ يَسْتَعْمِلْهُمْ لِمَنْفَعَتِهِ.', NULL, '7', '48', '268', '806', '2', 0, ''),
(18211, 7019, 'لَمْ يُخْلِ اللهُ سُبْحانَهُ عِبادَهُ مِنْ حُجَّةٍ لازِمَةٍ أَوْ مَحَجَّةٍ قائِمَةٍ.', NULL, '7', '48', '268', '806', '2', 0, ''),
(18212, 7020, 'لَمْ يَتْرُكِ اللهُ سُبْحانَهُ خَلْقَهُ مُغْفَلاً وَ لا تَرَكَ أَمْرَهُمْ مُهْمَلاً.', NULL, '7', '48', '268', '806', '2', 0, ''),
(18213, 7021, 'لَمْ يَخْلُقْكُمْ اللهُ سُبْحانَهُ عَبَثاً وَ لَمْ يَتْرُكْكُمْ سُدىً وَ لَمْ يَدَعْكُمْ في ضَلالَةٍ وَ عَمىً.', NULL, '7', '48', '268', '806', '2', 0, ''),
(18214, 7022, 'لَمْ يَحْلِلِ اللهُ سُبْحانَهُ فِي الْأَشْياءِ فَيَكُونَ فيها كائِناً وَلَمْ يَنْأَ عَنْها فَيُقالُ هُوَ عَنْها بائِنٌ.', NULL, '7', '48', '268', '806', '2', 0, ''),
(18215, 7023, 'لَمْ يَأْمُرْكَ اللهُ إِلَّا بِحَسَنٍ وَ لَمْ يَنْهَكَ إِلَّا عَنْ قَبيحٍ.', NULL, '7', '48', '268', '806', '2', 0, ''),
(18216, 7024, 'لَمْ يُوَفَّقْ مَنِ اسْتَحْسَنَ الْقَبيحَ وَأَعْرَضَ عَنْ قَوْلِ الْنَّصيحِ.', NULL, '7', '48', '268', '806', '2', 0, ''),
(18217, 7025, 'لَمْ يُدْرِكِ الْمَجْدَ مَنْ عَداهُ الْحَمْدُ.', NULL, '7', '48', '268', '806', '2', 0, ''),
(18218, 7026, 'لَمْ يَهْنَإِ الْعيْشَ مَنْ قارَنَ الضِّدَّ.', NULL, '7', '48', '268', '806', '2', 0, ''),
(18219, 7027, 'لَمْ يَسُدْ مَنِ افْتَقَرَ إِخْوانُهُ إِلى غَيْرِه.', NULL, '7', '48', '268', '806', '2', 0, ''),
(18220, 7028, 'لَمْ يُوَفَّقْ مَنْ بَخِلَ عَلى نَفْسِه بِخَيْرِه وَ خَلَّفَ مالَهُ لِغَيرِه.', NULL, '7', '48', '268', '806', '2', 0, ''),
(18221, 7029, 'لَمْ يَتَعَرَّ مِنَ الشَّرِّ مَنْ لَمْ يَتَجَلْبَبْ بِالْخَيرِ.', NULL, '7', '48', '268', '806', '2', 0, ''),
(18222, 7030, 'لَمْ يَعْدَمِ النَّصْرَ مَنِ انْتَصَرَ بِالصَّبْرِ.', NULL, '7', '48', '268', '806', '2', 0, ''),
(18223, 7031, 'لَمْ يَلْقَ أَحَدٌ مِنْ سَرّاءِ الدُّنْيا بطْناً إِلَّا مَنَحَتْهُ مِنْ ضَرّائِها ظَهْراً.', NULL, '7', '48', '268', '806', '2', 0, ''),
(18224, 7032, 'لَمْ يَكْتَسِبْ مالاً مَنْ لَمْ يُصْلِحْهُ.', NULL, '7', '48', '268', '806', '2', 0, ''),
(18225, 7033, 'لَمْ يُرْزَقِ الْمالَ مَنْ لَمْ يُنْفِقْهُ.', NULL, '7', '48', '268', '806', '2', 0, ''),
(18226, 7034, 'لَمْ يَضِقْ شَيْ ءٌ مَعَ حُسْنِ الْخُلْقِ.', NULL, '7', '48', '268', '806', '2', 0, ''),
(18227, 7035, 'لَمْ يَفُتْ نَفْساً ما قُدِّرَ لَها مِنَ الرِّزْقِ.', NULL, '7', '48', '268', '806', '2', 0, ''),
(18228, 7036, 'لَمْ يَذْهَبْ مِنْ مالِكَ ما وَقى عِرْضَكَ.', NULL, '7', '48', '268', '806', '2', 0, ''),
(18229, 7037, 'لَمْ يَعْقِلْ مَواعِظَ الزَّمانِ مَنْ سَكَنَ إِلى حُسْنِ الظَّنِّ بِالْأَيّامِ.', NULL, '7', '48', '268', '806', '2', 0, ''),
(18230, 7038, 'لَمْ يَضَعِ امْرُؤٌ مالَهُ في غَيرِ حَقِّه أَوْ مَعْرُوفَهُ في غَيرِ أَهْلِه إِلَّا حَرَّمَهُ اللهُ شُكْرَهُمْ وَ كانَ لِغَيرِه وُدُّهُمْ.', NULL, '7', '48', '268', '806', '2', 0, ''),
(18231, 7039, 'لَمْ يُخْلِ اللهُ سُبْحانَهُ عِبادَهُ مِنْ نَبِيٍّ مُرْسَلٍ أَوْ كِتابٍ مُنْزَلٍ.', NULL, '7', '48', '268', '806', '2', 0, ''),
(18232, 7040, 'لَمْ تُظِلَّ امْرَءً مِنَ الدُّنْيا ديمَةُ رَخاءٍ إِلَّا هَطَلتْ عَلَيْهِ مُزْنَةُ بَلاءٍ.', NULL, '7', '48', '268', '806', '2', 0, ''),
(18233, 7041, 'لَمْ يُفَكِّرْ في عَواقِبِ الْاُمُورِ مَنْ وَثِقَ بِالْغُرُورِ وَ صَبا إِلى زُورِ السُّرُورِ.', NULL, '7', '48', '268', '806', '2', 0, ''),
(18234, 7042, 'لَمْ يَصْدُقْ يَقينُ مَنْ أَسْرَفَ فِي الطَّلَبِ وَ أَجْهَدَ نَفْسَهُ فِي الْمُكْتَسَبِ.', NULL, '7', '48', '268', '806', '2', 0, ''),
(18235, 7043, 'لَمْ يَعْقِلْ مَنْ وَلَهَ بِاللَّعَبِ وَ اسْتُهْتِرَ بِاللَّهْوِ وَ الطَّرَبِ.', NULL, '7', '48', '268', '806', '2', 0, ''),
(18236, 7044, 'لَمْ يَنَلْ أَحَداً مِنْ الدُّنْيا حَبْرَةٌ إِلَّا أَعْقَبَتْهُ عَبْرَةً.', NULL, '7', '48', '268', '806', '2', 0, ''),
(18237, 7045, 'لَمْ تَرَهُ', NULL, '7', '48', '268', '806', '2', 0, ''),
(18238, 7046, 'لَمْ يَتَناهَ فِي الْعُقُولِ فَيَكُونَ في مَهَبِّ فِكْرِها مُكيَّفاً وَ لا في رَوِيَّاتِ خاطِرِها مُحَدَّداً مُصَرَّفاً.', NULL, '7', '48', '268', '806', '2', 0, ''),
(18239, 7047, 'وَ قال عليه السّلام في حقِّ مَنْ أَثنى عليه:

لَمْ يَقْتُلْهُ قاتِلاتُ الْغُرُورِ وَ لَمْ يَغُمَّ عَلَيْهِ مُشْتَبِهاتُ الْاُمُورِ.', NULL, '7', '48', '268', '806', '2', 0, ''),
(18240, 7048, 'لَوْ ظَهَرَتِ الْاجالُ لَافْتَضَحَتِ الْامالُ.', NULL, '7', '48', '269', '807', '2', 0, ''),
(18241, 7049, 'لَوْ خَلُصَتِ النِّيَّاتُ لَزكَتِ الْأَعْمالُ.', NULL, '7', '48', '269', '807', '2', 0, ''),
(18242, 7050, 'لَوْ رَأَيْتُمُ الأَجَلَ وَ مَسيرَهُ لَأَبْغَضْتُمُ الْأَمَلَ وَ غُرُورَهُ.', NULL, '7', '48', '269', '807', '2', 0, ''),
(18243, 7051, 'لَوْ فَكَّرْتُمْ في قُرْبِ الْأَجَلِ وَ حُضُورِه لَأَمَرَّ عِنْدَكمْ حُلْوُ الْعَيْشِ وَ سُرُورُهُ.', NULL, '7', '48', '269', '807', '2', 0, ''),
(18244, 7052, 'لَوْ صَحَّ يَقينُكَ لَمَا اسْتَبْدَلْتَ الْفانِيَ بِالْباقي وَ لا بِعْتَ السَّنِيَّ بِالْدَّنِيِّ.', NULL, '7', '48', '269', '807', '2', 0, ''),
(18245, 7053, 'لَوِ اعْتَبَرْتَ بِما أَضَعْتَ مِنْ ماضِيَ عُمْرِكَ لَحَفِظْتَ ما بَقِيَ.', NULL, '7', '48', '269', '807', '2', 0, ''),
(18246, 7054, 'لَوْ كُنّا نَأْتي ما تَأْتُونَ ما قامَ لِلدِّينِ عَمُودٌ وَ لَا اخْضَرَّ لِلْإِيمانِ عُودٌ.', NULL, '7', '48', '269', '807', '2', 0, ''),
(18247, 7055, 'لَوْ رَأَيْتُمُ السَّخاءَ رَجُلاً لَرَأَيْتُمُوهُ حَسَناً جَميلاً يَسُرُّ النَّاظِرين.', NULL, '7', '48', '269', '807', '2', 0, ''),
(18248, 7056, 'لَوْ كانَتِ الدُّنْيا عِنْدَ اللهِ مَحْمُودَةً لَاْختَصَّ بِها أَوْلِياءَ هُ لكِنَّهُ صَرَفَ قُلُوبَهُمْ
عَنْها وَ مَحا عَنْهُمْ مِنْهَا الْمَطامِعَ.', NULL, '7', '48', '269', '807', '2', 0, ''),
(18249, 7057, 'لَوْ رَأَيْتُمُ الْإِحْسانَ شَخْصاً لَرَأَيْتُمُوهُ شَكْلاً جَميلاً يَفُوقُ الْعالَمينَ.', NULL, '7', '48', '269', '807', '2', 0, ''),
(18250, 7058, 'لَوْ جَرَتِ الْأَرْزاقُ بِا|لأْلبابِ وَا|لْعُقُولِ لَمْ تَعِشِ الْبَهائِمُ وَ الْحَمْقى.', NULL, '7', '48', '269', '807', '2', 0, ''),
(18251, 7059, 'لَوْ كُشِفَ الْغِطاءُ مَا ازْدَدْتُ يَقيناً.', NULL, '7', '48', '269', '807', '2', 0, ''),
(18252, 7060, 'لَوِ اسْتَوَتْ قَدَمايَ في هذِهِ الْمَداحِضِ لَغَيَّرْتُ أَشْياءَ.', NULL, '7', '48', '269', '807', '2', 0, ''),
(18253, 7061, 'لَوْ ضَرَبْتُ خَيْشُومَ الْمُؤْمِنِ عَلى أَنْ يُبْغِضَني ما أبْغَضَني.', NULL, '7', '48', '269', '807', '2', 0, ''),
(18254, 7062, 'لَوْ صَبَبْتُ الدُّنْيا عَلى الْمُنافِقِ بِجُمْلَتِها عَلى أَنْ يُحِبَّني ما أَحَبَّني.', NULL, '7', '48', '269', '807', '2', 0, ''),
(18255, 7063, 'لَوْ أَنَّ الْمَوْتَ يُشْتَرى لَاشْتَراهُ الْأَغنِياءُ.', NULL, '7', '48', '269', '807', '2', 0, ''),
(18256, 7064, 'لَوْ رَأَيْتُمُ الْبُخْلَ رَجُلاً لَرَأَيْتُمُوهُ شَخْصاً مُشَوَّهاً يُغَضُّ عَنْهُ كُلُّ بَصَرٍ وَ يَنْصَرِفُ عَنْهُ كُلُّ قَلْبٍ.', NULL, '7', '48', '269', '807', '2', 0, ''),
(18257, 7065, 'لَوْ عَقَلَ أَهْلُ الدُّنْيا لَخَزِيَتِ الدُّنْيا.', NULL, '7', '48', '269', '807', '2', 0, ''),
(18258, 7066, 'لَوْ أَنَّ أَهْلَ الْعِلْمِ حَمَلُوهُ بِحَقِّه لَأَحَبَّهُمُ اللهُ وَ مَلائِكَتُهُ وَ لكِنَّهُمْ حَمَلُوهُ لِطلَبِ الدُّنْيا فَمَقَتَهُمُ اللهُ وَ هانُوا عَلَيْهِ.', NULL, '7', '48', '269', '807', '2', 0, ''),
(18259, 7067, 'لَوْ زَهَدْتُمْ فِي الشَّهَواتِ لَسَلِمْتُمْ مِنَ الْافاتِ.', NULL, '7', '48', '269', '807', '2', 0, ''),
(18260, 7068, 'لَوْ أَنَّ السَّماواتِ وَ الْأَرْضَ كانَتا عَلى عَبْدٍ رَتْقاً ثُمَّ اتَّقَى اللهَ لَجَعَلَ لَهُ مِنْها مَخْرَجاً وَ رَزَقَهُ مِنْ حَيْثُ لا يَحْتَسِبُ.', NULL, '7', '48', '269', '807', '2', 0, ''),
(18261, 7069, 'وَ قال عليه السّلام في حقِّ الْأَشْتَرِ النَّخعيِّ لَمّا بَلَغَهُ وَفاتَه رحمه الله:
لَوْ كانَ جَبَلاً لَكانَ فِنْداً لا يَرْتَقيهِ الْحافِرُ وَ لا يَرْقى عَلَيْهِ الطّائِرُ.', NULL, '7', '48', '269', '807', '2', 0, ''),
(18262, 7070, 'لَوْ أَنَّ الْمُرُوَّةَ لَم تَشْتَدَّ مَؤُنَتُها وَ لَمْ يَثْقَلْ مَحْمِلُها ما تَركَ اللِّئامُ لِلْكِرامِ
مِنْها مَبيتَ لَيْلَةٍ لكِنَّها حَيْثُ اشْتَدَّتْ مَؤُنَتُها وَ ثَقُلَ مَحْمِلُها حادَ عَنْهَا اللِّئامُ
الْأَغْمارُ وَ حَمَلَهَا الْكِرامُ الْأَبْرارُ.', NULL, '7', '48', '269', '807', '2', 0, ''),
(18263, 7071, 'لَوْ شِئْتُ أَنْ أُخْبِرَ كُلَّ رَجُلٍ مِنْكُمْ بِمَخْرَجِه وَ مَوْلِجِه وَ جَميعِ شَأْنِه لَفَعَلْتُ وَ
لكِنِّي أَخافُ أَنْ تَكْفُرُوا فِيَّ بِرَسُولِ اللهِ إِلَّا أَنّي أُفَوِّضُهُ إِلى الْخَاصَّةِ مِمَّنْ يُؤْمَنْ ذلِكَ
مِنْهُمْ وَ الَّذي بَعَثَهُ بِالْحَقِّ نَبِيّاً وَ اصْطَفاهُ عَلى الْخَلْقِ ما أَنْطِقُ إِلَّا صادِقاً وَ لَقَدْ
عَهِدَ إِلَيَّ بِذَلِكَ كُلِّه وَ بِمَهْلِكِ مَنْ يَهْلِكُ وَ بِمَنْجا مَنْ يَنْجُو وَ ما أَبْقى شَيْئاً يَمُرُّ عَلى
رَأْسي إِلَّا أَفْرَغَهُ في أُذُنيَّ وَ أَفْضى بِه إِلَيَّ.', NULL, '7', '48', '269', '807', '2', 0, ''),
(18264, 7072, 'لَوْ كانَ لِرَبِّكَ شَريكٌ لَأَتَتْكَ رُسُلُهُ.', NULL, '7', '48', '269', '807', '2', 0, ''),
(18265, 7073, 'لَوِ ارْتَفَعَ الْهَوى لَأَنِفَ غَيرُ الْمُخْلِصِ مِنْ عَمَلِه.', NULL, '7', '48', '269', '807', '2', 0, ''),
(18266, 7074, 'لَوْ صَحَّ الْعَقْلُ لَاغْتَنَمَ كُلُّ امْرِى ءٍ مَهَلَهُ.', NULL, '7', '48', '269', '807', '2', 0, ''),
(18267, 7075, 'لَوْ عَرَفَ الْمَنْقُوصُ نَقْصَهُ لَساءَ هُ ما يَرى مِنْ عَيْبِه.', NULL, '7', '48', '269', '807', '2', 0, ''),
(18268, 7076, 'لَوْ أَنَّ الْعِبادَ حينَ جَهِلُوا وَ قَفُوا، لَمْ يَكْفُرُوا وَ لَمْ يَضِلُّوا.', NULL, '7', '48', '269', '807', '2', 0, ''),
(18269, 7077, 'لَوْ أَنَّ النّاسَ حينَ عَصَوْا تابوا وَ اسْتَغْفرُوا لَمْ يُعَذَّبُوا وَ لَمْ يَهْلِكُوا.', NULL, '7', '48', '269', '807', '2', 0, ''),
(18270, 7078, 'لَوْ حَفِظْتُمْ حُدُودَ اللهِ لَعَجَّلَ لَكُمْ مِنْ فَضْلِهِ الْمَوْعُودِ.', NULL, '7', '48', '269', '807', '2', 0, ''),
(18271, 7079, 'لَوْ عَلِمَ الْمُصَلِّي ما يَغْشاهُ مِنَ الرَّحْمَةِ لَما رَفَعَ رَأْسَهُ مِنَ السُّجُودِ.', NULL, '7', '48', '269', '807', '2', 0, ''),
(18272, 7080, 'لَوْ لَمْ يَتَوَعَّدِ اللهُ سُبْحانَهُ عَلى مَعْصِيَتِه لَوَجَبَ أَنْ لا يُعْصى شُكْراً لِنِعْمَتِه.', NULL, '7', '48', '269', '807', '2', 0, ''),
(18273, 7081, 'لَوْ لَمْ يُرَغِّبِ اللهُ سُبْحانَهُ في طاعَتِه لَوَجَبَ أَنْ يُطاعَ رَجاءً لِرَحْمَتِه.', NULL, '7', '48', '269', '807', '2', 0, ''),
