(20733, 9541, 'لا تَأْمَنَنَّ مَلُولاً وَ إِنْ تَحَلَّى بِالصِّلَةِ فَإِنَّهُ لَيْسَ فِي الْبَرْقِ الْخاطِفِ مُسْتَمْتَعٌ لِمَنْ يَخُوضُ الظُّلْمَةَ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20734, 9542, 'لا يَكُنِ الْمَضْمُونُ لَكَ طَلَبُهُ أَوْلى بِكَ مِنَ الْمَفْرُوضِ عَلَيْكَ عَمَلُهُ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20735, 9543, 'لا تَنْصَبَنَّ نَفْسَكَ لِحَرْبِ اللهِ فَلا يَدَ لَكَ بِنَقِمَتِه وَ لا غَناءَ بِكَ عَنْ رَحْمَتِه.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20736, 9544, 'لا تَمْهَرِ الدُّنْيا دينَكَ فَإِنَّ مَنْ أَمْهَرَ الدُّنْيا دينَهُ زَفَّتْ إِلَيْهِ بِالشَّقاءِ وَالْعَناءِ وَالْمِحْنَةِ وَ الْبَلاءِ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20737, 9545, 'لا تَبيعُوا الْاخِرَةَ بِالْدُّنْيا وَ لا تَسْتَبْدِلُوا الْبَقاءَ بِالْفَناءِ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20738, 9546, 'لا تَجْعَلُوا يَقينَكُمْ شَكَّاً وَ لا عِلْمَكُمْ جَهْلاً.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20739, 9547, 'لا تَجْهَلْ نَفْسَكَ فَإِنَّ الْجاهِلَ بِمَعْرِفَةِ نَفْسِه جاهِلٌ بِكُلِّ شَيْ ءٍ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20740, 9548, 'لا يَفْتِنَنَّكُمُ الْدّنْيَا وَ لا يَغْلِبَنَّكُمْ الْهَوى وَ لا يَطُولَنَّ عَلَيْكُمْ الْامَدُ وَ لا يَغُرَّنَّكُمُ الْأَمَلُ فَإِنَّ الْأَمَلَ لَيْسَ مِنَ الدِّينِ بِشَيْ ءٍ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20741, 9549, 'لا تَقُولَنَّ مَا لا تَفْعَلُهُ فَإِنَّكَ لا تَخْلُوَ في ذلِكَ مِنْ عَجْزٍ يَلْزَمُكَ وَ ذَمٍّ تَكْسِبُهُ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20742, 9550, 'لا تَجْعَلْ ذَرَبَ لِسانِكَ عَلى مَنْ أَنْطَقَكَ وَ لا بَلاغَةَ قَوْلِكَ عَلى مَنْ سَدَّدَكَ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20743, 9551, 'لا تُكْثِرَنَّ مِنْ صُحْبَةِ اللَّئيمِ فَإِنَّهُ إِنْ صَحِبَتْكَ نِعْمَةٌ حَسَدَكَ وَ إِنْ طَرَقَتْكَ نائِبَةٌ قَذَفَكَ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20744, 9552, 'لا تَتَّخِذَنَّ عَدُوَّ صَديقِكَ صَديقاً فَتُعادِيَ صَديقَكَ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20745, 9553, 'لا تُعاجِلِ الذَّنْبَ بِالْعُقُوبَةِ وَ اجْعَلْ بَيْنَهُما لِلْعَفْوِ مَوْضِعاً تَحْرُزُ بِهِ الْأَجْرَ وَ الْمَثُوبَةَ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20746, 9554, 'لا تُطيعُوا النِّساءَ فِي الْمَعْرُوفِ حَتّى لا يَطْمَعْنَ فِي الْمُنْكَرِ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20747, 9555, 'لا تَسْتَشِرِ الْكَذّابَ فَإِنَّهُ كَالسَّرابِ يُقرِّبُ عَلَيْكَ الْبَعيدَ وَ يُبَعِّدُ عَلَيْكَ الْقَريبَ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20748, 9556, 'لا تَكُونَنَّ مِمَّنْ لا تَنْفَعُهُ الْعِظَةُ إِلَّا إِذا بالَغْتَ في إِيلامِه فَإِنَّ الْعاقِلَ يَتَّعِظُ بِالْأَدَبِ وَ الْبَهائِمَ لا تَرْتَدِعُ إِلَّا بِالضَّرْبِ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20749, 9557, 'لا تَعْتَذِرْ مِنْ أَمْرٍ أَطَعْتَ اللهَ فيهِ فَكَفى بِذلِكَ مَنْقَبَةً.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20750, 9558, 'لا تُبْدِ عَنْ واضِحَةٍ وَ قَدْ فَعَلْتَ الْاُمُورَ الْفاضِحَةَ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20751, 9559, 'لا تَسْتَعْمِلُوا الرَّأْيَ فيما لا يُدْرِكُهُ الْبَصَرُ وَ لا يَتَغَلْغَلُ فيهِ الْفِكَرُ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20752, 9560, 'لا تُدْخِلَنَّ في مَشُورَتِكَ بَخيلاً فَيَعْدِلَ بِكَ عَنِ الْقَصْدِ وَ يَعِدَكَ الْفَقْرَ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20753, 9561, 'لا تُشْرِكَنَّ في رَأْيِكَ جَباناً يُضْعفُكَ عَنِ الْأَمْرِ وَ يُعَظّمُ عَلَيْكَ مَا لَيْسَ بِعَظيمٍ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20754, 9562, 'لا تُقْدِمْ وَ لا تُحْجمْ إِلَّا عَلى طاعَةِ اللهِ وَ تَقْواهُ تَظْفَرْ بِالنُّجْح وَ الْنَّهْجِ الْقَويمِ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20755, 9563, 'لا تُشْرِكَنَّ في مَشْوَرَتِكَ حَريصاً يُهَوِّنُ عَلَيْكَ الشَّرَّ وَ يُزَيِّنُ لَكَ الشَّرَهَ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20756, 9564, 'لا يَكْبُرَنَّ عَلَيْكَ ظُلْمُ مَنْ ظَلَمَكَ فَإِنَّهُ يَسْعى في مَضَرَّتِه وَ نَفْعِكَ وَ مَا جَزاءُ مَنْ يسُرُّكَ أَنْ تَسُوءَ هُ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20757, 9565, 'لا يَكُونَنَّ أَفْضَلُ مَا نِلْتَ مِنْ دُنْياكَ بُلُوغَ لَذَّةٍ أَوْ شِفاءَ غَيْظٍ وَ لْيَكُنْ إِحْياءَ حَقٍّ وَ إِماتَةَ باطِلٍ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20758, 9566, 'لا يَقْنَطَنَّكَ تَأَخُّرُ إِجابَةِ الدُّعاءِ فَإِنَّ الْعَطِيَّةَ عَلى قَدْرِ النِّيَّةِ وَ رُبَّما
تَأَخَّرَتِ الْإِجابَةُ لِيَكُونَ ذلِكَ أَعْظَمَ لأَِجْرِ السَّائِلِ وَ أَجْزَلَ لِعَطاءِ النّائِلِ.
', NULL, '7', '53', '279', '817', '2', 0, ''),
(20759, 9567, 'لا تَذْكُرِ اللهَ ساهِياً وَ لا تَنْسَهُ لاهِياً وَ اذْكُرْهُ ذِكراً كامِلاً يُوافِقُ فيهِ
قَلْبُكَ لِسانَكَ وَ يُطابِقُ إِضْمارُكَ إِعْلانَكَ وَ لَنْ تَذْكُرَهُ حَقيقَةَ الذِّكْرِ حَتّى تَنْسى نَفْسَكَ في
ذِكْرِكَ وَ تَفْقِدَها في أَمْرِكَ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20760, 9568, 'لا تُفْنِ عُمْرَكَ فِي الْمَلاهي فَتَخْرُجَ مِنَ الدُّنْيا بِلا أَمَلٍ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20761, 9569, 'لا تَصْرِفْ مالَكَ فِي الْمَعاصي فَتَقْدَمَ عَلى رَبِّكَ بِلا عَمَلٍ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20762, 9570, 'لا تُفْنِ دُنْياكَ بِحُسْنِ الْعَواري فَعَواري الدُّنْيا تُرْتَجعُ وَ يَبْقى عَلَيْكَ مَا احْتَقَبْتَهُ مِنَ الْمَحارِمِ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20763, 9571, 'لا تَغُرَّنَّكَ الْعاجِلَةُ بِزُورِ الْمَلاهي فَإِنَّ اللَّهْوَ يَنْقَطِعُ وَ يَلْزَمُكَ مَا اكْتَسَبْتَهُ مِنَ الْمَآثِمِ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20764, 9572, 'لا تُؤْخِّرْ إِنالَةَ الْمُحْتاجِ إِلى غَدٍ فَإِنَّكَ لا تَدْري مَا يعْرُضُ لَكَ وَ لَهُ في غَدٍ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20765, 9573, 'لا تَتْرُكِ الْإِجْتِهادَ في إِصْلاحِ نَفْسِكَ فَإِنَّهُ لا يُعْينُكَ عَلَيْها إِلَّا الْجِدُّ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20766, 9574, 'لا تُضَيِّعَنَّ حَقَّ أَخيكَ اتِّكالاً عَلى مَا بَيْنَكَ وَ بَيْنَهُ فَلَيْسَ هُوَ لَكَ بِأَخٍ مَا أَضَعْتَ حَقَّهُ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20767, 9575, 'لا تُحَدِّثِ الْجُهّالَ بِما لا يَعْقِلُونَهُ فَيُكَذِّبُوكَ فَإِنَّ بِهِ لِعِلْمِكَ عَلَيْكَ حَقّاً وَ حَقَّهُ عَلَيْكَ بَذْلُهُ لِمُسْتَحِقِّه وَ مَنْعُهُ عَنْ غَيْرِ مُسْتَحِقِّه.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20768, 9576, 'لا يَكُونَنَّ أَخُوكَ عَلى الْإِسْاءَ ةِ إِلَيْكْ أَقْوى مِنْكَ عَلى الْإِحْسانِ إِلَيْهِ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20769, 9577, 'لا يَكُونَنَّ أَخوكَ عَلى قَطيعَتِكَ أَقْوى مِنْكَ عَلى صِلَتِه.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20770, 9578, 'لا تَغْدَرَنَّ بِعَهْدِكَ وَ لا تَخْفُرَنَّ ذِمَّتَكَ وَ لا تَخْتَلْ عَدُوَّكَ فَقَدْ جَعَلَ اللهُ عَهْدَهُ وَ ذِمَّتَهُ أَمْناً لَهُ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20771, 9579, 'لا تَكُونَنَّ عَبْدَ غَيْرِكَ وَ قَدْ جَعَلَكَ اللهُ حُرَّاً، فَما خَيرُ خَيْرٍ لا يُنالُ إِلَّا بِشَرٍّ، وَ يُسْرٍ لا يُنالُ إِلَّا بِعُسْرٍ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20772, 9580, 'لا تُمَلِّكِ الْمَرْأةَ مَا جاوَزَ نَفْسَها فَإِنَّ الْمَرْأةَ رَيْحانَةٌ وَلَيْسَتْ بِقَهْرَمانَةٍ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20773, 9581, 'لا تَقُلْ مَا لا تَعْلَمُ فَإِنَّ اللهَ سُبْحانَهُ قَدْ فَرَضَ عَلى جَوارِحِكَ فَرائِضَ يَحْتَجُّ بِها عَلَيْكَ يَوْمَ الْقِيامَةِ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20774, 9582, 'لا تَحاسَدُوا فَإِنَّ الْحَسَدَ يَأْكُلُ الْإِيْمانَ كَما تَأْكُلُ النّارُ الْحَطَبَ وَ لا تَباغَضُوا فَإِنَّها الْحالِقَةُ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20775, 9583, 'لا تَنْقُضَنَّ سُنَّةً صالِحَةً عُمِلَ بِها وَاجْتَمَعَتِ الْاُلْفَةُ لَها وَ صَلُحَتِ الرَّعِيَّةُ عَلَيْها.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20776, 9584, 'لا تُصاحِبْ مَنْ فاتَهُ الْعَقْلُ وَ لا تُصْطَنِعْ مَنْ خانَهُ الْأَصْلُ فَإِنَّ مَنْ فاتَهُ الْعَقْلُ
يَضُرُّكَ مِنْ حَيْثُ يَرى أَنَّهُ يَنْفَعُكَ وَ مَنْ خانَهُ الْأَصْلُ يُسي ءُ إِلى مَنْ أَحْسَنَ إِلَيْهِ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20777, 9585, 'لا يَسُوءَ نَّكَ مَا يَقُولُ النّاسُ فِيكَ فَإِنَّهُ إِنْ كانَ كَما يَقُولُونَ كانَ ذَنْباً عُجلَتْ
عُقُوبَتُهُ وَ إِنْ كانَ عَلى خِلافِ مَا قالُوا كانَتْ حَسَنَةً لَمْ تَعْمَلْها.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20778, 9586, 'لا تَقْتَحِمُوا مَا اسْتَقْبَلْتُمْ مِنْ فَوْرِ الْفِتْنَةِ وَ أَميطُوا عَنْ سُنَّتِها وَ خَلُّوا قَصْدَ السَّبيلِ لَها.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20779, 9587, 'لا تَدْعُونَّ إِلى مُبارَزَةٍ ؛ وَ إِنْ دُعيتَ إِلَيْها فَأَجِبْ فَإِنَّ الدّاعِيَ إِلَيْها باغٍ وَ الْباغي مَصْرُوعٌ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20780, 9588, 'لا تَسْتَكْثِرَنَّ مِنْ إِخْوانِ الدُّنْيا فَإِنَّكَ إِنْ عَجَزْتَ عَنْهُمْ تَحَوَّلُوا أَعْداءً وَ إِن مَثَلَهُمْ كَمَثَلِ النّارِ كَثيرُها يُحْرِقُ وَ قَليلُها يَنْفَعُ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20781, 9589, 'لا تَشْتَغِلْ بِما لا يَعْنيكَ وَ لا تَتَكَلَّفْ فَوْقَ مَا يَكْفيكَ وَ اجْعَلْ كُلَّ هَمِّكَ لِما يُنْجيكَ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20782, 9590, 'لا تُؤْيِسْ مُذْنِباً عاكِفاً عَلى ذَنْبِه فَكَمْ مِنْ مُذْنِبٍ خُتِمَ لَهُ بِالْمَغْفِرَةِ وَ كَمْ مِنْ مُقْبِلٍ عَلى عَمَلٍ هُوَ مُفْسِدٌ لَهُ خُتِمَ لَهُ في آخِرِ عُمْرِه بِالنّارِ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20783, 9591, 'لا يَزْهَدَنَّكَ في اصْطِناعِ الْمَعْرُوفِ قِلَّةُ مَنْ يَشْكُرُهُ فَقَدْ يَشْكُرُكَ عَلَيْهِ مَنْ لا يَنْتَفِعُ بِشَيْ ءٍ مِنْهُ وَ قَدْ تُدْرِكُ مِنْ شُكْرِ الشّاكِرِ أَكْثَرَ مِمّا أَضاعَ الْكافِرُ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20784, 9592, 'لا تُرَخِّصْ لِنَفْسِكَ في مُطاوَعَةِ الْهَوى وَ إِيثارِ لَذّاتِ الدُّنْيا فَيفْسُدَ دينُكَ وَ لا يَصْلُحَ وَ تَخْسَرَ نَفْسُكَ وَ لا تَرْبَحَ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20785, 9593, 'لا تَنْتَصِحْ مَنْ فاتَهُ الْعَقْلُ وَ لا تَثِقْ بِمَنْ خانَهُ الْأَصْلُ فَإِنَّ مَنْ لا عَقْلَ لَهُ
يَغُشُّ مِنْ حَيْثُ يَنْصَحُ وَ مَنْ لا أَصْلَ لَهُ يُفْسِدُ مِنْ حَيْثُ يُصْلِحُ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20786, 9594, 'لا تُسِى ءْ إِلى مَنْ أَحْسَنَ إِلَيْكَ فَمَنْ أَساءَ إِلى مَنْ أَحْسَنَ إِلَيْهِ فَقَدْ مَنَعَ الْإِحْسانَ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20787, 9595, 'لا تَكُنْ مِمَّنْ يَرْجُو الْاخِرَةَ بِغَيْرِ عَمَلٍ وَ يُسَوِّفُ التَّوْبَةَ بِطُولِ الْأَمَلِ يَقُولُ فِي الدُّنْيا بِقَوْلِ الزّاهِدينَ وَ يَعْمَلُ فيها بِعَمَلِ الرّاغِبينَ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20788, 9596, 'لا تَلْتَمِسِ الدُّنْيا بِعَمَلِ الْاخِرَةِ وَ لا تُؤْثِرِ الْعاجِلَةَ عَلى الْاجِلَةِ فَإِنَّ ذلِكَ شيمَةُ الْمُنافِقينَ وَ سَجِيَّةُ الْمارِقينَ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20789, 9597, 'لا يَغْرَّنَّكَ مَا أَصْبَحَ فيهِ أَهْلُ الْغُرُورِ بِالدُّنْيا فَإِنَّما هُوَ ظِلٌّ مَمْدُودٌ إِلى أَجَلٍ مَحْدُودٍ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20790, 9598, 'لا تَكُنْ غافِلاً عَنْ دينِكَ حَريصاً عَلى دُنْياكَ مُسْتَكْثِراً مِمّا لا يَبْقى عَلَيْكَ مُسْتَقِلّاً مِمّا يَبْقى لَكَ فَيُورِدَكَ ذلِكَ الْعَذابَ الشَّديدَ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20791, 9599, 'لا تَلْتَبِسْ بِالْسُّلْطانِ في وَقْتِ اضْطِرابِ الْامُورِ عَلَيْهِ فَإِنَّ الْبَحْرَ لا يَكادُ
يَسْلَمُ راكِبُهُ مَعَ سُكُونِه فَكَيْفَ "لا يَهْلِكُ"|22| مَعَ اخْتِلافِ رِياحِه وَ اضْطِرابِ أَمْواجِه.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20792, 9600, 'لا تَسْتَحْي مِنْ إِعْطاءِ الْقَليلِ فَإِنَّ الْحِرْمانَ أَقَلَّ مِنْهُ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20793, 9601, 'لا تَسْتَكْثِرَنَّ الْكَثيرَ مِنَ نَوالِكَ فَإِنَّكَ أَكْثَرُ مِنْهُ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20794, 9602, 'لا تُسِرَّ إِلى الْجاهِلِ مَا لا يُطيقُ كِتْمانَهُ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20795, 9603, 'لا تَرُدَّ السَّائِلَ وَ صُنْ مُرُوَّتَكَ عَنْ حِرْمانِه.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20796, 9604, 'لا تُسِى ءِ اللَّفْظَ وَ إِنْ ضاقَ عَلَيْكَ الْجَوابُ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20797, 9605, 'لا تَصْرِمْ أَخاكَ عَلى ارْتِيابٍ وَ لا تَهْجُرْهُ "إِلَّا" بَعْدَ اسْتِعْتابٍ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20798, 9606, 'لا تَعْتَذِرْ إِلى مَنْ يُحِبُّ أَنْ لا يَجِدَ لَكَ عُذْراً.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20799, 9607, 'لا تَقُولَنَّ مَا يُوافِقُ هَواكَ وَ إِنْ قُلْتَهُ لَهْواً أَوْ خِلْتَهُ لَغْواً، فَرُبَّ لَهْوٍ يُوحِشُ مِنْكَ خَيْراً وَ لَغْوٍ يَجْلِبُ عَلَيْكَ شَرّاً.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20800, 9608, 'لا تُعَوِّدْ نَفْسَكَ الْيَمينَ فَإِنَّ الْحَلّافَ لا يَسْلَمُ مِنَ الْإِثْمِ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20801, 9609, 'لا يُؤْنِسْكَ إِلَّا الْحَقُّ وَ لا يُوحِشْكَ إِلَّا الْباطِلُ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20802, 9610, 'لا تَجْعَلْ عِرْضَكَ غَرَضاً لِقَوْلِ كُلِّ قائِلٍ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20803, 9611, 'لا تَبْخَلْ فَتُقْتِرَ وَ لا تُسْرِفْ فَتُفْرِطَ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20804, 9612, 'لا تَتَّبِعِ الْهَوى فَمَنِ اتَّبَعَ الْهَوى ارْتَبَكَ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20805, 9613, 'لا تَسْتَبِدَّ بِرَأْيِكَ فَمَنِ اسْتَبَدَّ بِرَأْيِه هَلَكَ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20806, 9614, 'لا يَسْتَرِقَّنَّكَ الطَّمَعُ وَ قَدْ جَعَلَكَ اللهُ حُرّاً.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20807, 9615, 'لا تَعَرَّضْ لِمَعاصي اللهِ وَ اعْمَلْ بِطاعَتِه يَكُنْ لَكَ ذُخْراً.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20808, 9616, 'لا تَنْدَمَنَّ عَلى عَفْوٍ وَ لا تَبْتَهِجَنَّ بِعُقُوبَةٍ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20809, 9617, 'لا تَسْعَ إِلَّا فِي اغْتِنامِ مَثُوبَةٍ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20810, 9618, 'لا تُسِى ءِ الْخِطابَ فَيَسُؤْكَ نَكيرُ الْجَوابِ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20811, 9619, 'لا تَعْجَلَنَّ إِلى تَصْديقِ واشٍ وَ إِنْ تَشَبَّهَ بِالنَّاصِحينَ فَإِنَّ السّاعِيَ ظالِمٌ لِمَنْ سَعى بِه غاشٌّ لِمَنْ سَعى إِلَيْهِ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20812, 9620, 'لا تَمْنَعَنَّكُمْ رِعايَةُ الْحَقِّ لأَِحَدٍ عَنْ إِقامَةِ الْحَقِّ عَلَيْهِ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20813, 9621, 'لا يَدْعُوَنَّكَ ضيقٌ لَزِمَكَ في عَهْدِ اللهِ إِلى النَّكْثِ فيهِ فَإِنَّ صَبْرَكَ عَلى ضيقٍ
تَرْجُو انْفِراجَهُ وَ فَضْلَ عاقِبَتِه خَيرٌ لَكَ مِنْ غَدْرٍ تَخافُ تَبِعَتَهُ وَ تُحيطُ بِكَ مِنَ اللهِ
تَعالى |لِأَجْلِهِ الْعُقُوبَةُ.
', NULL, '7', '53', '279', '817', '2', 0, ''),
(20814, 9622, 'لا تَسْرَعَنَّ إِلى بادِرَةٍ وَ لا تَعْجَلَنَّ بِعُقُوبَةٍ وَجَدْتَ عَنْها مَنْدُوحَةً فَإِنَّ ذلِكَ مَنْهَكَةٌ لِلدِّينِ مُقَرِّبٌ مِنَ الْغِيَرِ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20815, 9623, 'لا تُضِعْ نِعْمَةً مِنْ نِعَمِ اللهِ عِنْدَكَ وَ لْيُرَ عَلَيْكَ أَثَرُ مَا أَنْعَمَ اللهُ بِه عَلَيْكَ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20816, 9624, 'لا تَأْمَنْ عَدُوَّكَ وَ لا تَقْرَعْ إِلى صَديقِكَ وَ اقْبلِ الْعُذْرَ وَ إِنْ كانَ كَذِباً وَ دَعِ الْجَوابَ عَنْ قُدْرَةٍ وَ إِنْ كانَ لَكَ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20817, 9625, 'لا يَكُنِ الْمُحْسِنُ وَ الْمُسي ءُ إِلَيْكَ سَواءً فَإِنَّ ذلِكَ يُزَهِّدُ الْمُحْسِنَ فِي الْإِحْسانِ وَ يُتابِعُ الْمُسي ءَ إِلى الْإِسائَةِ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20818, 9626, 'لا تَحْمِلْ هَمَّ يَوْمِكَ الَّذي لَمْ يَأْتِكَ عَلى يَوْمِكَ الَّذي أَنْتَ فيهِ فَإِنَّهُ إِنْ يَكُنْ مِنْ
عُمْرِكَ فَإِنَّكَ تُؤْتَ فيهِ مِنَ اللهِ بِرِزْقِكَ وَ إِنْ لَمْ يَكُنْ مِنْ عُمْرِكَ فَما هَمُّكَ بِما لَيْسَ مِنْ
أَجْلِكَ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20819, 9627, 'لا تَعِبْ غَيرَكَ بِما تَأْتيهِ وَ لا تُعاقِبْ غَيْركَ عَلى ذَنْبٍ تُرَخِّصُ لِنَفْسِكَ فيهِ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20820, 9628, 'لا تُصَعِّرَنَّ خَدَّكَ وَ أَلِنْ جانِبَكَ وَ تَواضَعْ لِلّهِ الَّذي رَفَعَكَ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20821, 9629, 'لا تُعِنْ عَلى مَنْ أَنْعَمَ عَلَيْكَ فَمَنْ أَعانَ عَلى مَنْ أَنْعَمَ عَلَيْهِ سَلَبَ الْإِمْكانَ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20822, 9630, 'لا تُدِلَّنَّ بِحالَةٍ بَلَغْتَها بِغَيْرِ آلَةٍ وَ لا تَفْخَرَنَّ بِمَرْتِبَةٍ نِلْتَها بِغَيْرِ مَنْقَبَةٍ فَإِنَّ مَا يَبْنيهِ الْإِتِّفاقُ يَهْدِمُهُ الْإِسْتِحْقاقُ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20823, 9631, 'لا تُحَقِّرَنَّ صَغائِرَ الْاثامِ فَإِنَّها الْمُوبِقاتُ وَ مَنْ أَحاطَتْ بِه مُحَقَّراتُها أَهْلَكَتْهُ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20824, 9632, 'لا تُمازِحَنَّ صَديقاً فَيُعادِيَكَ وَ لا عَدُوّاً فَيُرْدِيَكَ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20825, 9633, 'لا تُكْثِرَنَّ الْخَلْوَةَ بِالنّساءِ فَيَمْلِلْنَكَ وَ تَمِلَّهُنَّ وَ اسْتَبْقِ مِنْ نَفْسِكَ وَ عَقْلِكَ بِالْإِبْطاءِ عَنْهُنَّ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20826, 9634, 'لا تَحْمِلُوا النِّساءَ أَثْقالَكُمْ وَ اسْتَغْنُوا عَنْهُنَّ مَا اسْتَطَعْتُمْ فَإِنَّهُنَّ يُكْثِرْنَ الْإِمْتِنانَ وَيَكْفُرْنَ بِالْإِحْسانِ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20827, 9635, 'لا تَكُنْ فيما تُورِدُ كَحاطِبِ لَيْلٍ وَ غُثاءِ سَيْلٍ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20828, 9636, 'لا تُمَلِّكْ نَفْسَكَ بِغُرُورِ الطَّمَعِ وَ لا تُجِبْ دَواعِي الشَّرَهِ فَإِنَّهُما يُكْسِبانِكَ الشَّقاءَ وَ الذُّلَّ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20829, 9637, 'لا تُشْعِرْ قَلْبَكَ الْهَمَّ عَلى مَا فاتَ فَيَشْغَلَكَ عَنِ الْإِسْتِعْدادِ لِما هُوَ آتٍ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20830, 9638, 'لا تَسْئَلُوا إِلَّا اللهَ سُبْحانَهُ فَإِنَّهُ إِنْ أَعْطاكُمْ أَكْرَمَكُمْ وَ إِنْ مَنَعَكُمْ حَازَ لَكُمْ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20831, 9639, 'لا تَقُلْ مَا لا تَعْلَمُ فَتُتَّهَمَ في إِخْبارِكَ بِما تَعْلَمُ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20832, 9640, 'لا تَفْضَحُوا أَنْفُسَكُمْ عِنْدَ عَدُوِّكُمْ فِي الْقِيامَةِ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20833, 9641, 'لا تُكَذِّبُوا أَنْفُسَكُمْ عِنْدَكُمْ في مَنْزِلَتِكُمْ عِنْدَ اللهِ بِالْحَقيرِ مِنَ الْدُّنْيا.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20834, 9642, 'لا تَكُونُوا عَبيدَ الْأَهْواءِ وَ الْمَطامِعِ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20835, 9643, 'لا تَكُونُوا مَساييحَ وَ لا مَذاييعَ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20836, 9644, 'لا تَشْتَدَّنَّ عَلَيْكُمْ فَرَّةٌ بَعْدَها كَرَّةٌ وَ لا جَوْلَةٌ بَعْدَها صَوْلَةٌ وَ أَعْطُوا السُّيُوفَ
حُقُوقَها وَ أَقْصُوا لِلْحَرْبِ مَصارِعَها وَ اذْمرُوا أَنْفُسَكُمْ عَلى الطَّعْنِ الْدِّعْسِيِّ وَ الضَّرْبِ
الطَّلْحَفِيِّ وَ أَميتُوا الْأَصْواتَ فَإِنَّهُ أَطْردُ لِلْفَشَلِ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20837, 9645, 'لا تَطْمَعَنَّ في مَوَدَّةِ الْمُلُوكِ فَإِنَّهُمْ يُوحِشُونَكَ آنَسَ مَا تَكُونُ بِهِمْ وَ يَقْطَعُونَكَ
أَقْرَبَ مَا تَكُون إِلَيْهِمْ.', NULL, '7', '53', '279', '817', '2', 0, ''),
(20838, 9646, 'لا زادَ كَالتَّقْوى.', NULL, '7', '53', '280', '818', '2', 0, ''),
