(21296, 10104, 'لا لِباسَ أَفْضَلُ مِنَ الْعافِيَةِ.', NULL, '7', '53', '280', '818', '2', 0, ''),
(21297, 10105, 'لا غِنى مَعَ سُوءِ تَدْبيرٍ.', NULL, '7', '53', '280', '818', '2', 0, ''),
(21298, 10106, 'لا فَقْرَ مَعَ حُسْنِ تَدْبيرٍ.', NULL, '7', '53', '280', '818', '2', 0, ''),
(21299, 10107, 'لا يَكُونُ حازِماً مَنْ لا يَجُودُ بِما فِي يَدِه وَ يُؤَخِّرُ عَمَلَ يَوْمِه إِلى غَدِه.', NULL, '7', '53', '280', '818', '2', 0, ''),
(21300, 10108, 'لا يَدُومُ حَبْرةُ الدُّنْيا وَ لا يَبْقى سُرُورُها وَ لا يُؤْمَنْ فَجْعَتَها.', NULL, '7', '53', '280', '818', '2', 0, ''),
(21301, 10109, 'لا يَكُونُ الْعالِمُ عالِماً حَتّى لا يَحْسُدَ مَنْ فَوْقَهُ وَ لا يَحْتَقِرَ مَنْ دُونَهُ وَ لا يَأْخُذَ عَلى عِلْمِه شَيْئاً مِنْ حُطامِ الدُّنْيا.', NULL, '7', '53', '280', '818', '2', 0, ''),
(21302, 10110, 'لا خَيرَ فِي الدُّنْيا إِلَّا لِأَحَدِ رَجُلَينِ رَجُلٌ أَذْنَبَ ذُنُوباً |فَهُوَ يَتَدارَكُها بِالتَّوْبَةِ وَ رَجُلٌ مُسارِعٌ بِالْخَيْراتِ.', NULL, '7', '53', '280', '818', '2', 0, ''),
(21303, 10111, 'لا يُقَرِّبُ مِنَ اللهِ إِلَّا كَثْرَةُ السُّجُودِ وَ الرُّكُوعِ.', NULL, '7', '53', '280', '818', '2', 0, ''),
(21304, 10112, 'لا يُذْهِبُ الْفاقَةَ مِثْلُ الرِّضا وَ الْقُنُوعِ.', NULL, '7', '53', '280', '818', '2', 0, ''),
(21305, 10113, 'وَ قال عليه السّلام في وصف جَهَنَّم لا يَظْعَنُ مُقيمُها وَ لا يُفادى أَسيرُها وَ لا تُقْصَمُ كُبُولُها لا مُدَّةَ لِلدَّارِ فَتُفْنى وَ لا أَجَلَ لِلْقَوْمِ فَيُقْضى.', NULL, '7', '53', '280', '818', '2', 0, ''),
(21306, 10114, 'لا مَرْحَباً بِوُجُوهٍ لا تُرى إِلَّا عِنْدَ كُلِّ سَوْءَ ةٍ.', NULL, '7', '53', '280', '818', '2', 0, ''),
(21307, 10115, 'لا رِئاسَةَ كَالْعَدْلِ فِي السِّياسَةِ.', NULL, '7', '53', '280', '818', '2', 0, ''),
(21308, 10116, 'لا شَيْ ءَ أَحْسَنُ مِنْ عَمَلٍ مَعَ عِلْمٍ وَ عِلْمٍ مَعَ حِلْمٍ وَ حِلْمٍ مَعَ قُدْرَةٍ.', NULL, '7', '53', '280', '818', '2', 0, ''),
(21309, 10117, 'لا شَيْ ءَ أَفْضَلُ مِنْ إِخْلاصِ عَمَلٍ في صِدْقِ نِيَّةٍ.', NULL, '7', '53', '280', '818', '2', 0, ''),
(21310, 10118, 'لا يَنْصَحُ اللَّئيمُ أَحَداً إِلَّا عَنْ رَغْبَةٍ أَوْ رَهْبَةٍ فَإِذا زالَتِ الرَّغْبَةُ أَوِ الرَّهْبَةُ عادَ إِلى جَوْهَرِه.', NULL, '7', '53', '280', '818', '2', 0, ''),
(21311, 10119, 'لا نِعْمَةَ أَهْنَأُ مِنَ الْأَمْنِ.', NULL, '7', '53', '280', '818', '2', 0, ''),
(21312, 10120, 'لا سَوءَ ةَ أَقْبَحُ مِنَ الْمَنِّ.', NULL, '7', '53', '280', '818', '2', 0, ''),
(21313, 10121, 'لا يَسْكُنُ الْحِكْمَةُ قَلْباً "مُلِى ءَ مِنْ حُبِّ شَهْوَةٍ".', NULL, '7', '53', '280', '818', '2', 0, ''),
(21314, 10122, 'لا حِكْمَةَ إِلَّا بِعِصْمَةٍ.', NULL, '7', '53', '280', '818', '2', 0, ''),
(21315, 10123, 'لا تَخَتَّمُوا بِغَيْرِ الْفِضَّةِ فَإِنَّ رَسُولَ اللهِ صلّى الله عليه و آله قال: مَا ظَهُرَتْ يَدٌ فيها خاتَمُ حَديدٍ.', NULL, '7', '53', '280', '818', '2', 0, ''),
(21316, 10124, 'لا تَنْتَفُوا الشَّيْبَ فَإِنَّهُ نُورُ الْمُسْلِمِ.', NULL, '7', '53', '280', '818', '2', 0, ''),
(21317, 10125, 'لا تَبُولَنَّ في سَطْحٍ فِي الْهَواءِ.', NULL, '7', '53', '280', '818', '2', 0, ''),
(21318, 10126, 'لا يَنامُ الرَّجُلُ عَلى وَجْهِه.', NULL, '7', '53', '280', '818', '2', 0, ''),
(21319, 10127, 'لا تُجالِسُوا لَنا عائِباً وَ لا تَمْدَحُونا عِنْدَ أَعْدائِنا مُعْلِنينَ بِإِظْهارِ حُبِّنا فَتُذِلُّوا أَنْفُسَكُمْ عِنْدَ سُلْطانِكُمْ.', NULL, '7', '53', '280', '818', '2', 0, ''),
(21320, 10128, 'لا يَضِلُّ مَنْ تَبِعَنا وَ لا يَهْتَدي مَنْ أَنْكَرَنا وَ لا يَنْجُو مَنْ أَعانَ |عَلَينا عَدُوَّنا وَ لا يُعانُ مَنْ أَسْلَمَنا.', NULL, '7', '53', '280', '818', '2', 0, ''),
(21321, 10129, 'يَنْبَغي لِمَنْ عَرَفَ الْاخِرَةَ أَنْ يَرْغَبَ فيها.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21322, 10130, 'يَنْبَغي لِمَنْ عَرَفَ زَوالَ الدُّنْيا أَنْ يَزْهَدَ فيها.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21323, 10131, 'يَنْبَغي لِمَنْ عَرَفَ اللهَ أَنْ يَرْغَبَ فيما لَدَيْهِ.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21324, 10132, 'يَنْبَغي لِمَنْ رَضِيَ بِقَضاءِ اللهِ أَنْ يَتَوَكَّلَ عَلَيْهِ.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21325, 10133, 'يَنْبَغي لِمَنْ عَرَفَ نَفْسَهُ أَنْ لا يُفارِقَهُ الْحُزْنُ وَ الْحَذَرُ.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21326, 10134, 'يَنْبَغي لِمَنْ عَرَفَ الْزَّمانَ أَنْ لَا يَأْمَنَ صُرُوْفَهُ وَ الْغِيَرِ.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21327, 10135, 'يَنْبَغي لِمَنْ عَرَفَ النّاسَ أَنْ يَزْهَدَ فيما في أَيْديهِمْ.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21328, 10136, 'يُمْتَحَنُ الرَّجُلُ بِفِعْلِه لا بِقَوْلِه.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21329, 10137, 'يُنْبى ءُ عَنْ قيمَةِ كُلِّ امْرِى ءٍ عِلْمُهُ وَ عَقْلُهُ.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21330, 10138, 'يَحْتَاجُ الْإِسْلامُ إِلى الْإِيْمان.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21331, 10139, 'يَحْتاجُ الْإِيْمانُ إِلى الْإِيقانِ.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21332, 10140, 'يَحْتاجُ الْعَمَلُ إِلى الْعِلْمِ.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21333, 10141, 'يَسيرُ الطَّمَعِ يُفْسِدُ كَثيرَ الْوَرَعِ.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21334, 10142, 'يَسيرُ الْحِرْصِ يَحْمِلُ عَلى كَثيرِ الطَّمَعِ.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21335, 10143, 'يَحْتاجُ الشَّرَفُ إِلى التَّواضُعَ.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21336, 10144, 'يَسيرُ الْهَوى يُفْسِدُ الْعَقْلَ.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21337, 10145, 'يَسيرُ الْأَمَل يُفْسِدُ الْعَمَلَ.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21338, 10146, 'يَسيرٌ يَكْفي خَيْرٌ مِنْ كَثْيرٍ يُطْغي.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21339, 10147, 'يَسيرُ الْعِلْمِ يَنْفي كَثيرِ الْجَهْلِ.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21340, 10148, 'يَسيرُ الْعَطاءِ أَحْسَنُ مِنَ التَّعلُّلِ بِالْإِعْتِذارِ.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21341, 10149, 'يَسِّرُوا وَ لا تُعَسِّرُوا وَ خَفِّفُوا وَ لا تُثقِّلُوا.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21342, 10150, 'يَحْتاجُ الْإِيْمانُ إِلى الْإِخْلاصِ.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21343, 10151, 'يُمْتَحَنُ الْمُؤْمِنُ بِالْبَلاءِ كَما يُمْتَحَنُ بِالنّارِ الْخَلاصُ.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21344, 10152, 'يُسْتَدَلُّ عَلى دينِ الرَّجُلِ بِصِدْقِه وَ وَرَعِه.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21345, 10153, 'يُسْتَدَلُّ عَلى شَرِّ الرَّجُلِ بِكَثْرَةِ شَرَهِه وَ شِدَّةِ طَمَعِه.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21346, 10154, 'يُسْتَدَلُّ عَلى عَقْلِ الرَّجُلِ بِحُسْنِ مَقالِه وَ عَلى طَهارَةِ أَصْلِه بِجَميلِ أَفْعالِه.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21347, 10155, 'يُسْتَدَلُّ عَلى نُبْلِ الرَّجُلِ بِقِلَّةِ مَقالِه وَعَلى تَفَضُّلِه بِكَثْرَةِ احْتِمالِه.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21348, 10156, 'يُسْتَدَلُّ عَلى الْكَريمِ بِحُسْنِ بِشْرِه وَ بَذْلِ بِرِّه.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21349, 10157, 'يُسْتَدَلُّ عَلى زَوالِ الدُّوَلِ بِأَرْبَعٍ: تَضْييع الْاُصُولِ، وَ التَّمَسُّكِ بِالْفُرُوعِ، وَ
تَقْدُّمِ الْأَراذِلِ، وَ تَأْخيرِ الْأَفاضِلِ.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21350, 10158, 'يَا ابْنَ آدَمَ إِذا رَأْيتَ اللهَ يُتابِعُ عَلَيْكَ نِعَمَهُ فَاحْذَرْهُ وَ حَصِّنِ النِّعْمَةَ بِشُكْرِها.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21351, 10159, 'يَكْتَسِبُ الصّادِقُ بِصِدْقِه ثَلاثاً: حُسْنَ الثِّقَةِ بِه، وَ الْمَحَبَّةَ لَهُ، وَ الْمَهابَةَ مِنْهُ.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21352, 10160, 'يَكْتَسِبُ الْكاذِبُ بِكذِبِه ثَلاثاً: سَخَطَ اللهِ عَلَيْهِ، وَ اسْتِهانَةَ النّاسِ بِه، وَ
مَقْتَ الْمَلائِكَةِ لَهُ.
', NULL, '7', '54', '281', '819', '2', 0, ''),
(21353, 10161, 'يَا عَبْدَ اللهِ لا تَعْجَلْ في عَيْبِ عَبْدٍ بِذَنْبِه فَلَعَلَّهُ مَغْفُورٌ لَهُ وَ لا تَأْمَنْ عَلى نَفْسِكَ صَغيرَ مَعْصِيَةٍ فَلَعَلَّكَ مُعَذَّبٌ عَلَيْها.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21354, 10162, 'وَ قال عليه السّلام في حَقِّ مَنْ ذَمَّهُ يَقُولُ فِي الدُّنْيا بِقوْلِ الزّاهِدينَ وَ
يَعْمَلُ فيها بِعَمَلِ الرّاغِبينَ، يُظْهِرُ شيمَةَ الصّالِحينَ وَ يُبْطِنُ عَمَلَ الْمُسيئينَ، يَكْرَهُ
الْمَوْتَ لِكَثْرَةِ ذُنُوبِه وَ لا يَتْرُكُها فِي حَياتِه، يُسْلِفُ الذَّنْبَ وَ يُسَوِّفُ بِالتَّوْبَةِ، يُحِبُّ
الصَّالِحينَ وَ لا يَعْمَلُ أَعْمالَهُمْ، يُبْغِضُ الْمُسيئينَ وَ هُوَ مِنْهُمْ، يَقُولُ لَمْ أَعْمَلْ فَأَتَعَنّى
بَلْ أَجْلِسُ فَأَتَمَنّى، يُبادِرُ دائِباً مَا يَفْنى وَ يَدَعُ أَبَداً مَا يَبْقى، يَعْجِزُ عَنْ شُكْرِ مَا
أُوتِيَ وَ يَبْتَغي الزِّيادَةَ فيما بَقِيَ، يُرْشِدُ غَيرَهُ وَ يُغْوي نَفْسَهُ وَ يَنْهَى النّاسَ بِما لا
يَنْتَهي وَ يَأْمُرُهُمْ بِما لا يَأْتي، يَتَكَلَّفُ مِنَ النّاسِ مَا لَمْ يُؤْمَرْ وَ يُضَيِّعُ مِنْ نَفْسِه مَا
هُوَ أَكْثَرُ، يَأْمُرُ النّاسَ وَ لا يَأْتَمِرُ وَ يُحَذِّرُهُمْ وَ لا يَحْذَرُ، يَرْجُو ثَوابَ مَا لَمْ يَعْمَلُ
وَ يَأْمَنُ عِقابَ جُرْمٍ مُتَيَقِّنٍ، يَسْتَميلُ وُجُوهَ النّاسِ بِتَدَيُّنِه وَ يُبْطِنُ ضِدَّ مَا يُعْلِنُ، يَعْرِفُ
لِنَفْسِه عَلى غَيْرِه وَ لا يَعْرِفُ عَلَيْها لِغَيْرِه، يَخافُ عَلى غَيْرِه بِأَكْثَرَ مِنْ ذَنْبِه وَ يَرْجُو
لِنَفْسِه أَكْثَرَ مِنْ عَمَلِه وَ يَرْجُو اللهَ فِي الْكَبيرِ وَ يَرْجُو الْعِبادَ فِي الصَّغْيرِ فَيُعْطي
الْعَبْدَ مَا لا يُعْطي الرَّبَّ، يَخافُ الْعَبيدَ فِي الرَّبِّ وَ لا يَخافُ فِي الْعَبيدِ الرَّبَّ.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21355, 10163, 'يُعْجِبُني مِنَ الرَّجُلِ أَنْ يُرى عَقْلُهُ زائِداً عَلى لِسانِه وَ لا يُرى لِسانُهُ زائِداً عَلى عَقْلِه.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21356, 10164, 'يَنْبَغي لِمَنْ عَرَفَ |شَرَفَ نَفْسَهُ أَنْ يُنزِّهَها عَنْ دَناءَ ةِ الدُّنْيا.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21357, 10165, 'يُكْرَمُ السُّلْطانُ لِسُلْطانِه وَ الْعالِمُ لِعِلْمِه وَ ذُو الْمَعْروفِ لِمَعْروفِه وَ الْكَبيرُ لسِنِّه.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21358, 10166, 'يُسْتَدَلُّ عَلى إِيمانِ الرَّجُلِ بِلُزُومِ الطّاعَةِ وَ التَّحَلّي بِالْوَرَعِ وَ الْقَناعَةِ.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21359, 10167, 'يَنْبَغي لِمَنْ عَرَفَ اللهَ سُبْحانَهُ أَنْ لا يَخْلُوَ قَلْبُهُ مِنْ خَوْفِه وَ رَجائِه.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21360, 10168, 'يَنْبَغي لِمَنْ عَرَفَ دارَ الْفَناءِ أَنْ يَعْمَلَ لِدارِ الْبَقاءِ.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21361, 10169, 'يَنْبَغي لِمَنْ رََضِيَ بِقَضَاءِ اللهَ أَنْ يَتَوَكَّلَ عَلَيْهِ.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21362, 10170, 'يَنْبَغي لِمَنْ عَرَفَ الْأَشْرارَ أَنْ يَعْتَزِلَهُمْ.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21363, 10171, 'يَنْبَغي لِمَنْ عَرَفَ الْفُجّارَ أَنْ لا يَعْمَلَ عَمَلَهُمْ.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21364, 10172, 'يَنْبَغي لِلْعاقِلِ أَنْ يَكْتَسِبَ بِمالِهِ الْمَحْمَدَةَ وَ يَصُونَ نَفْسَهُ عَنِ الْمَسْألَةِ.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21365, 10173, 'يَبْلُغُ الصّادِقُ بِصِدْقِه مَا لا يَبْلُغُهُ الْكاذِبُ بِحيلَتِه.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21366, 10174, 'يَنْبَغي لِلْعاقِلِ أَنْ يُخاطِبَ الْجاهِلَ مُخاطَبَةَ الطَّبيبِ الْمَريضَ.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21367, 10175, 'يَنْبَغي لِلْعاقِلِ أَنْ يَحْتَرِسَ مِنْ سُكْرِ الْمالِ وَ سُكْرِ الْقُدْرَةِ وَ سُكْرِ الْعِلْمِ وَ
سُكْرِ الْمَدْحِ وَ سُكْرِ الشَّبابِ فَإِنَّ لِكُلِّ ذلِكَ ريحاً خَبيثَةً تَسْلُبُ الْعَقْلَ وَ تَسْتَخِفُّ الْوَقارَ.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21368, 10176, 'يُسْتَدَلُّ عَلى الْإِدْبارِ بِأَرْبَعٍ: سُوءِ التَّدْبيرِ، وَ قُبْحِ التَّبْذيرِ، وَ قِلَّةِ الْإِعْتِبارِ، وَ كَثْرَةِ الْإِغْتِرارِ.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21369, 10177, 'يُسْتَدَلُّ عَلى الْإِيْمانِ بِكَثْرَةِ التُّقى وَ مِلْكِ الشَّهْوَةِ وَ غَلَبَةِ الْهَوى.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21370, 10178, 'يَسيرُ الرِّياءِ شِرْكٌ.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21371, 10179, 'يَسيرُ الظَّنِّ شَكٌّ.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21372, 10180, 'يَسيرُ الْغيبَةِ إِفْكٌ.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21373, 10181, 'يَسيرُ الشَّكِّ يُفْسِدُ الْيَقينَ.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21374, 10182, 'يَنْبَغي لِلْعاقِلِ إِذا عَلَّمَ أَنْ لا يُعنِّفَ وَ إِذا عُلِّمَ أَنْ لا يَأْنَفَ "وَ يَهْتَمَّ بِأَمْرِ الْمَعادِ فَكَمْ مِنْ ذاهِبٍ مَا عادَ وَاللهُ بَصيرٌ بِالْعِبادِ".', NULL, '7', '54', '281', '819', '2', 0, ''),
(21375, 10183, 'يَا أَيُّها النّاسُ اقْبلُوا النَّصيحَةَ مِمَّنْ نَصَحَكُمْ وَ تَلَقَّوْها بِالطّاعَةِ مِمَّنْ
حَمَلَها إِلَيْكُمْ وَ اعْلَمُوا أَنَّ اللهَ سُبْحانَهُ لَمْ يَمْدَحْ مِنَ الْقُلُوبِ إِلَّا أَوْعاها لِلْحِكْمَةِ
وَ مِنَ النّاسِ إِلَّا أَسْرَعَهُمْ إِلى الْحَقِّ إِجابَةً وَ اعْلَمُوا أَنَّ الْجِهادَ الْأَكْبَرَ جِهادُ
النَّفْسِ فَاشْتَغِلُوا بِجِهادِ أَنْفُسِكُمْ تَسْعَدُوا وَ ارْفُضُوا الْقيلَ وَ الْقالَ تَسْلَمُوا وَ
أَكْثِرُوا ذِكْرَ اللهِ تَغْنَمُوا وَ كُونُوا عِبادَ اللهِ إِخْواناً تَفُوزُوا لَدَيْهِ بِالْنَّعيمِ الْمُقيمِ.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21376, 10184, 'يَا أَيُّها النّاسُ إِلى كَمْ تُوعَظُونَ فَلا تَتَّعِظُونَ وَ كَمْ قَدْ وَعَظَكُمْ الْواعِظُونَ وَ
حَذَّرَكُمُ الْمُحَذِّرُونَ وَ زَجَرَكُمُ الزّاجِرُونَ وَ بَلَّغَكُمُ الْعالِمُونَ وَ عَلى سَبيلِ النَّجاةِ دَلَّكُمُ
الْأَنْبِياءُ الْمُرْسَلُونَ وَ أَقامُوا عَلَيْكُمُ الْحُجَّةَ وَ أَوْضَحُوا لَكُمُ الْمَحَجَّةَ فَبادِرُوا الْعَمَلَ
وَ اغْتَنِمُوا الْمَهَلَ فَإِنَّ الْيَوْمَ عَمَلٌ وَ لا حِسابَ وَ غَداً حِسابٌ وَ لا عَمَلَ وَ سَيَعْلَمُ
الَّذينَ ظَلَمُوا أَيَّ مُنْقَلَبٍ يَنْقَلِبُونَ.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21377, 10185, 'يَا أَبا ذَرٍّ إِنَّكَ غَضِبْتَ لِلّهِ فَارْجُ مَنْ غَضِبْتَ لَهُ فَإِنَّ الْقَوْمَ خافُوكَ عَلى
دُنْياهُمْ وَ خِفْتَهُمْ عَلى دينِكَ فَاتْرُكْ في أَيْدِيهِمْ مَا خافُوكَ عَلَيْهِ وَ اهْرَبْ مِنْهُمْ بِما
خِفْتُمْ عَلَيْهِ فَما أَحْوَجَهُمْ إِلى مَا مَنَعْتَهُمْ وَ مَا أَغْناكَ عَمّا مَنَعُوكَ وَ لوْ أَنَّ
السَّماواتِ وَ الْأَرْضَ كَانَتَا عَلى عَبْدٍ رَتْقاً ثُمَّ اتَّقَى اللهَ لَجَعَلَ لهُ مِنْهُما مَخْرَجاً فَلا
يُؤْنِسْكَ إِلَّا الْحَقُّ وَ لا يُوحِشْكَ إِلَّا الْباطِلُ فَلَوْ قَبِلْتَ دُنْياهُمْ لَأَحَبُّوكَ وَ لَوْ قَرَضْتَ
مِنْها لَامَنُوكَ.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21378, 10186, 'يَا عَبيدَ الدُّنْيا الْعامِلينَ لَها إِذا كُنْتُمْ فِي النَّهارِ تَبيعُونَ وَ تَشْتَرُونَ وَ
فِي اللَّيلِ عَلى فُرُشِكُمْ تَتَقَبَّلُونَ وَ تَنَامُونَ وَ فيما بينَ ذلك عَنِ الاخِرَةِ تَغْفُلُونَ وَ
بِالْعَمَلِ تُسَوِّفُونَ فَمَتى تُفَكِّرُونَ فِي الْإِرْتِيادِ وَ مَتى تُقَدِّمونَ الزّادَ وَ مَتى تَهْتَمُّونَ
لِيَوْمِ الْمَعادِ.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21379, 10187, 'يَنْبَغي أَنْ يَسْتَحْيِيَ الْمُؤْمِنُ إِذا اتَّصَلَتْ لَهُ فِكْرَةٌ في غَيرِ طاعَةٍ.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21380, 10188, 'يَنْبَغي أَنْ يَتَداوى الْمَرْءُ مِنْ أَدْواءِ الدُّنْيا كَما يَتَداوى ذُو الْعِلَّةِ، وَ يَحْتَمي مَِنْ لَذّاتِها وَ شَهَواتِها كَحِمْيَةِ الْمَريضِ.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21381, 10189, 'يَنْبَغي أَنْ يَكُونَ عِلْمُ الرَّجُلِ زائِداً عَلى نُطْقِه وَ عَقْلُهُ غالِباً عَلى لِسانِه.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21382, 10190, 'يُنْبِى ءُ عَنْ عَقْلِ كُلِّ امْرِى ءٍ مَا يَجْري عَلى لِسانِه.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21383, 10191, 'يُسْتَدَلُّ عَلى الْمُحْسِنينَ بِما يَجْري لَهُمْ عَلى أَلْسُنِ الْأَخْيارِ مِنْ حُسْنِ السِّيرَةِ وَ الْفِعْلِ.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21384, 10192, 'يُسْتَدَلُّ عَلى الْمُرُوَّةِ بِكَثْرَةِ الْحَياءِ وَ بَذْلِ النَّدى وَ كَفِّ الْأَذى.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21385, 10193, 'يَسيرُ الدُّنْيا يُفْسِدُ الدِّينَ.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21386, 10194, 'يَسيرُ الدِّينِ خَيرٌ مِنْ كَثيرِ الدُّنْيا.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21387, 10195, 'يُفْسِدُ الْيَقينَ الشَّكُّ وَ غَلَبَةُ الْهَوى.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21388, 10196, 'يَسيرُ الْحَقِّ يَدْفَعُ كَثيراً مِنَ الْباطِلِ.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21389, 10197, 'يُسْتَثْمَرُ الْعَفْوُ بِالْإِقْرارِ أَكْثَرَ مِنَ اسْتِثْمارِه بِالْإِعْتِذارِ.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21390, 10198, 'يُبْتَلى مُخالِطُ النّاس بِقَرينِ السَّوْءِ وَمُداجاةِ الْعَدُوِّ.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21391, 10199, 'يَحْتاجُ ذُو النّائِلِ إِلى السّائِلِ.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21392, 10200, 'يَحْتاجُ الْعِلْمُ إِلى الْحِلْمِ.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21393, 10201, 'يَحْتَاجُ الْحِلْمُ إِلى الْكَظْمِ.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21394, 10202, 'يَنامُ الرَّجُلُ عَلى الثُّكْلِ وَ لا يَنامُ عَلى الظُّلْمِ.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21395, 10203, 'يَوْمُ الْمَظْلُومِ عَلى الظَّالِمِ أَشَدُّ مِنْ يَوْمِ الظّالِمِ عَلى الْمَظْلُومِ.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21396, 10204, 'يَشْفيكَ مِنْ حاسِدِكَ أَنَّهُ يَغْتاظُ عِنْدَ سُرُورِكَ.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21397, 10205, 'يُسْتَدَلُّ عَلى فَضْلِكَ بِعَمَلِكَ وَ عَلى كَرَمِكَ بِبَذْلِكَ.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21398, 10206, 'يَغْلِبُ الْأَقْدارُ عَلى التَّقْديرِ حَتَّى يَكُونَ الْحَتْفُ فِي التَّدْبيرِ.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21399, 10207, 'يَجْرِي الْقَضاءُ بِالْمَقاديرِ عَلى خِلافِ الْإِخْتِيارِ وَ التَّدْبيرِ.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21400, 10208, 'يُعْجِبُني أَنْ يَكُونَ الرَّجُلُ حَسَنَ الْوَرَعِ مُتَنَزِّهاً عَنِ الطَّمَعِ كَثير الْإِحْسانِ قَليلَ الْإِمْتِنانِ.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21401, 10209, 'وَ قال عليه السّلام في وصف الْمنافقين يَمْشُونَ الْخَفاءَ وَ يَدُبُّونَ الضَّرّاءَ
قَوْلُهُمُ الدَواءُ وَ فِعْلُهُمُ الدّاءُ الْعَياءُ، يَتَقارَضُونَ الثَّناءَ وَ يَتَراقَبُونَ الْجَزاءَ،
يَتَوَصَّلُونَ إِلى الطَّمَعِ بِالْيَأْسِ وَ يَقُولُونَ فَيُشَبَّهُونَ، يُنافِقُونَ فِي الْمَقالِ وَ يَصِفُونَ
فَيُمَوِّهُونَ.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21402, 10210, 'وَ قال عليه السّلام في حَقّ منْ أَثْنى عَليه يَعْطِفُ الْهَوى عَلى الْهُدى إِذا
عَطَفُوا الْهُدى عَلى الْهَوى، |وَ| يَعْطِفُ الرَّأْي عَلى الْقُرْآنِ إِذا عَطَفُوا الْقُرْآنَ عَلى
الرَّأْيِ.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21403, 10211, 'يَأْتي عَلى النّاسِ زَمانٌ لا يَبْقى مِنَ الْقُرْآنِ إِلَّا رَسْمُهُ وَ مِنَ الْإِسْلامِ إِلَّا اسْمُهُ مَساجِدُهُمْ يَوْمَئِذٍ عامِرَةٌ مِنَ الْبَناءِ خالِيَةٌ مِنَ الْهُدى.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21404, 10212, 'يَأْتي عَلى النّاسِ زَمانٌ لا يُقَرَّبُ فيهِ إِلَّا الْماجِنُ وَ لا يُسْتَطْرَفُ فيهِ إِلَّا
الْفاجِرُ وَ لا يُضَعِّفُ فيهِ إِلَّا الْمُنْصِفُ يَعُدُّونَ الصَّدَقَةَ غُرْماً وَ صِلَةَ الرَّحِمِ مَنّاً وَ
الْعِبادَةَ اسْتِطالَةً عَلى النّاسِ وَ يَظْهَرُ عَلَيْهِمُ الْهَوى وَ يَخْفى بَيْنَهُمُ الْهُدى.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21405, 10213, 'يُنْبِى ءُ عَنْ عِلْمِ كُلِّ امْرِى ءٍ لِسانُهُ وَ يَدُلُّ عَلى فَضْلِه حُسْنُ بَيانِه.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21406, 10214, 'يَؤُلُ أَمْرُ الصَّبُورِ إِلى إِدْراكِ بُغْيَتِه وَ بُلُوغِ أَمَلِه.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21407, 10215, 'يَطْلُبُكَ رِزْقُكَ أَشَدَّ مِنْ طَلَبِكَ لَهُ فَأَجْمِلْ في طَلَبِه.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21408, 10216, 'يُسْتَدَلُّ عَلى عِلْمِ الرَّجُلِ بِقِلَّةِ كَلامِه وَ عَلى مُرُوَّتِه بِجَزيلِ إِنْعامِه.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21409, 10217, 'يُسْتَدَلُّ عَلى خَيرِ كُلِّ امْرِى ءٍ وَ شَرِّه وَ طَهارَةِ أَصْلِه وَ خُبْثِه بِفِعْلِه.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21410, 10218, 'يَنْبَغي أَنْ يَكُونَ فِعْلُ الرَّجُلِ أَحْسَنَ مِنْ قَوْلِه وَ لا يَكُونَ قَوْلُهُ أَحْسَنَ مِنْ فِعْلِه.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21411, 10219, 'يَقْبَحُ بِالرَّجُلِ أَنْ يَقْصُرَ عَمَلُهُ عَنْ عِلْمِه وَ يَعْجِزَ فِعْلُهُ عَنْ قَوْلِه.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21412, 10220, 'يَنْبَغي أَنْ يُهانَ مُغْتَنِمُ مَوَدَّةِ الْحَمْقى.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21413, 10221, 'يَنْبَغي لِلْعاقِلِ أَنْ يَتجَنَّبَ مُخالَطَةَ أَبْناءِ الدُّنْيا.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21414, 10222, 'يَنْبَغي لِمَنْ عَرَفَ نَفْسَهُ أَنْ لا يُفارِقَهُ الْحَذَرُ وَ النَّدَمُ خَوْفاً أَنْ يَزِلَّ بِه بَعْدَ الْعِلْمِ الْقَدَمُ.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21415, 10223, 'يَنْبَغي أَنْ يَكُونَ التَّفاخُرُ بِعُلُوِّ الْهِمَمِ وَ الْوَفاءِ بِالذِّمَمِ وَ الْمُبالَغَةِ فِي الْكَرَمِ لا بِبَوالِي الرِّمَمِ وَ رَذائِلِ الشِّيَمِ.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21416, 10224, 'يَنْبَغي لِلْعاقِلِ أَنْ لا يَخْلُوَ في كُلِّ حالٍ مِنْ طاعَةِ رَبِّه وَ مُجاهَدَةِ نَفْسِه.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21417, 10225, 'يَنْبَغي لِلْعاقِلِ أَنْ يَعْمَلَ لِلْمَعادِ وَ يَسْتَكْثِرَ مِنَ الزّادٍ قَبْلَ زُهُوقِ نَفْسِه وَ حُلُولِ رَمْسِه.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21418, 10226, 'يَنْبَغي لِلْمُؤْمِنِ أَنْ يَلْزَمَ الطّاعَةَ وَ يَلْتَحِفَ الْوَرَعَ وَ الْقَناعَةَ.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21419, 10227, 'يَنْبَغي لِمَنْ عَرَفَ نَفْسَهُ أَنْ يَلْزَمَ الْقَناعَةَ وَ الْعِفَّةَ.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21420, 10228, 'يَنْبَغي لِمَنْ عَرَفَ الدُّنْيا أَنْ يَزْهَدَ فيها وَ يَعْزِفَ عَنْها.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21421, 10229, 'يَنْبَغي لِمَنْ أَيْقَنَ بِبَقاءِ الْاخِرَةِ وَ دَوامِها أَنْ يَعْمَلَ لَها.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21422, 10230, 'يَنْبَغي لِمَنْ عَرَفَ سُرْعَةَ رِحْلَتِه أَنْ يُحْسِنَ التَّأَهُّبَ لِنَقْلَتِه.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21423, 10231, 'يَنْبَغي لِلْعاقِلِ أَنْ يُقَدِّمَ لِاخِرَتِه وَ يَعْمُرَ دارَ إِقامَتِه.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21424, 10232, 'يَنْبَغي لِلْعاقِلِ أَنْ يُكْثِرَ صُحْبَةَ الْعُلَماءِ الْأَبْرارِ وَ يُجَنِّبَ مُقارَنَةَ الْأَشْرارِ وَ الْفُجّارِ.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21425, 10233, 'يُسْتَدَلُّ عَلى اللَّئيمِ بِسُوءِ الْفِعْلِ وَ قُبْحِ الْخُلْقِ وَ ذميمِ الْبُخْلِ.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21426, 10234, 'يُسْتَدَلُّ عَلى الْيَقينِ بِقَصْرِ الْأَمَلِ وَ إِخْلاصِ الْعَمَلِ وَ الزُّهْدِ فِي الدُّنْيا.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21427, 10235, 'يُسْتَدَلُّ عَلى مَا لَمْ يَكُنْ بِما قَدْ كانَ.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21428, 10236, 'يُسْتَدَلُّ عَلى مُرُوَّةِ الرَّجُلِ بِبَثِّ الْمَعْرُوفِ وَ بَذْلِ الْإِحْسانِ وَتَرْكِ الْإِمْتِنانِ.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21429, 10237, 'يُسْتَدَلُّ عَلى عَقْلِ الرَّجُلِ بِكَثْرَةِ وَقارِه وَ حُسْنِ احْتِمالِه وَ |عَلى كَرَمِ أَصْلِه بِجَميلِ أَفْعالِه.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21430, 10238, 'يَسيرُ الدُّنْيا يَكْفي وَ كَثيرُها يُرْدي.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21431, 10239, 'يَسيرُ التَّوْبَةِ وَ الْإِسْتِغْفارِ يُمَحِّصُ الْمَعاصيَ وَ الْإِصْرارَ.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21432, 10240, 'يَسيرُ الدُّنْيا خَيرٌ مِنْ كَثيرِها وَ بُلْغَتُها أَجْدَرُ مِنْ هَلْكَتِها.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21433, 10241, 'يا أُسَراءَ الرَّغْبَةِ أَقْصِرُوا فَإِنَّ الْمُعرِّجَ عَلى الدُّنْيا لا يُرَوِّعُهُ مِنْها إلَّا صَريفُ أَنْيابِ الْحِدْثانِ.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21434, 10242, 'يَا أَهْلَ الْمَعْرُوفِ وَ الْإِحْسانِ لا تَمُنُّوا بِإِحْسانِكُمْ فَإِنَّ الْإِحْسانَ وَ الْمَعْرُوفَ يُبْطِلُهُما قُبْحُ الْإِمْتِنانِ.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21435, 10243, 'يَا أَيُّها النّاسُ ازْهَدُوا فِي الدُّنْيا فَإِنَّ عَيْشَها قَصيرٌ وَ خَيرَها يَسيرٌ وَ
إِنَّها لَدارُ شُخُوصٍ وَ مَحَلَّةُ تَنْغيصٍ وَ إِنَّها لَتُدْني الْاجالَ وَ تَقْطَعُ الْامالَ أَلا وَ هِيَ
الْمُتصَدِّيَةُ الْعَنُونُ وَ الجامِحَةُ الْحَرُونُ وَ الْمانِيَةُ الْخَؤونُ.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21436, 10244, 'يَا أَهْلَ الْغُرُورِ مَا أَلْهَجَكُمْ بِدارٍ خَيرُها زَهيدٌ وَ شَرُّها عَتيدٌ وَ نَعيمُها
مَسْلُوبٌ |وَ عَزيزُها مَنْكوبٌ| وَ مُسالِمُها مَحْرُوبٌ وَ مالِكُها مَمْلُوكٌ وَ تُراثُها مَتْرُوكٌ.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21437, 10245, 'يَحْتاجُ الْإِمامُ إِلى قَلْبٍ عَقُولٍ وَ لِسانٍ قَؤولٍ وَ جَنانٍ عَلى إِقامَةِ الْحَقِّ صَؤولٍ.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21438, 10246, 'وَ قال عليه السّلام في حَقِّ مَنْ ذَمَّهُ يُحِبُّ أَنْ يُطاعَ وَ يَعْصي وَ يَسْتَوْفِيَ وَلا
يُوفي، يُحِبُّ أَنْ يُوصَفَ بِالْسَّخاءِ وَ لا يُعْطي وَ يَقْتَضِيَ وَ لا يَقْضِي.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21439, 10247, 'يُفْسِدُ الطَّمَعُ الْوَرَعَ وَ الْفُجُورُ وَ التَّقْوى.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21440, 10248, 'يُغْتَنَمُ مُؤاخاةُ الْأَخْيارِ وَ يُتَجَنَّبُ مُصاحَبَةُ الْأَشْرارِ وَ الْفُجّارِ.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21441, 10249, 'يُعْجِبُني مِنَ الرَّجُلِ أَنْ يَعْفُوَ عَمَّنْ ظَلَمَهُ وَ يَصِلَ مَنْ قَطَعَهُ وَ يُعْطِيَ مَنْ حَرَمَهُ وَ يُقابِلَ الْإِساءَ ةَ بِالْإِحْسانِ.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21442, 10250, 'يَكْثُرُ حَلْفُ الرَّجُلِ لِأَرْبَعٍ: مَهانَةٍ يَعْرِفُها مِنْ نَفْسِه، أَوْ ضَراعَةٍ يَجْعَلُها
سَبيلاً إِلى تَصْديقِه، أَوْ عَيٍّ بِمَنْطقِه فَيَتَّخِذُ الْإِيْمانَ حَشْواً وَ صِلَةً لِكَلامِه، أَوْ لِتُهْمَةٍ
قَدْ عُرِفَ بِها.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21443, 10251, 'يَقْبَحُ عَلى الرَّجُلِ أَنْ يُنْكِرَ عَلى النّاسِ مُنْكَراتٍ وَ يَنْهاهُمْ عَنْ رَذائِلَ وَ
سَيِّئاتٍ وَ إِذا خَلا بِنَفْسِه ارْتَكَبَها وَ لا يَسْتَنْكِفَ مِنْ فِعْلِها.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21444, 10252, 'يَا دُنْيا يَا دُنْيا إِلَيْكِ عَنِّي! أَبي تَعَرَّضْتِ أَمْ إِلَيَّ تَشَوَّقْتِ لا حانَ حينُكَ غُرّي
غَيري لا حاجَةَ لي فيكِ قَدْ طَلَّقْتُكِ ثَلاثاً لا رَجْعَةَ لي فيها فَعَيْشُكِ قَصيرٌ وَ خَطَرُكِ
يَسيرٌ وَ أَمَلُكِ حَقيرٌ، آهْ! مِنْ قِلَّةِ الزّادِ وَ طُولِ الطَّريقِ وَ بُعْدِ السَّفَرِ وَ عِظَمِ الْمَوْرِدِ.', NULL, '7', '54', '281', '819', '2', 0, ''),
(21445, 10253, 'يَا أَيُّهَا النّاسُ إِنَّهُ لَمْ يَكُنْ لِلّهِ سُبْحانَهُ حُجَّةٌ في أَرْضِه أَوْكدُ مِنْ نَبِيِّنا
مُحَمَّدٍ صَلَّى اللهُ عَلَيْهِ وَ آلِه وَ سَلَّمْ وَ لا حِكْمَةٌ أَبْلَغُ مِنْ كِتابِهِ الْعَظيمِ وَ لا مَدَحَ
اللهُ تَعالى مِنْكُمْ إِلَّا مَنِ اعْتَصَمَ بِحَبْلِه وَ اقْتَدى بِنَبِيِّه وَ إِنَّما هَلَكَ مَنْ هَلَكَ عِنْدَمَا
عَصاهُ وَ خالَفَهُ وَ اتَّبَعَ هَواهُ فَلِذلِكَ يَقُولُ عَزَّ مِنْ قائِلٍ: ''فَلْيَحْذَرِ الَّذينَ يُخالِفُونَ عَنْ
أَمْرِه أَنْ تُصيبَهُمْ فِتْنَةٌ أَوْ يُصيبَهُمْ عَذابٌ أَليمٌ''.
', NULL, '7', '54', '281', '819', '2', 0, '');