(12608, 1416, 'العالِمُ كُلُّ العالم مَنْ لَمْ يَمْنَعِ النَّاسَ الرَّجاءَ لِرَحْمَةِ اللهِ وَلَمْ يُؤْمِنْهُمْ مِنْ مَكْرِ اللهِ.', NULL, '7', '26', '198', '736', '2', 0, ''),
(12609, 1417, 'الفَقيهُ كُلُّ الفَقيهِ مَنْ لَمْ يُقْنِطِ النّاسَ مِنْ رَحْمَةِ اللهِ وَ لَمْ يُؤْيسهُمْ مِنْ رَوْحِ اللهِ.', NULL, '7', '26', '198', '736', '2', 0, ''),
(12610, 1418, 'المُحْتَكِرُ وَ الْبَخيلُ جامِعٌ لِمَنْ لا يَشْكُرُهُ وَ قادِمٌ عَلى مَنْ لا يُعْذِرُهُ.', NULL, '7', '26', '198', '736', '2', 0, ''),
(12611, 1419, 'الكَرَمُ إِيثارُ عُذُوبَةِ الثَّناءِ عَلى حُبِّ الْمالِ.', NULL, '7', '26', '198', '736', '2', 0, ''),
(12612, 1420, 'الْأَخُ الْمُكْتَسبُ فِي اللهِ أقْرَبُ القُرَباءِ وَ أَرْحَمُ مِنَ الْأمَّهاتِ وَ الْاباءِ.', NULL, '7', '26', '198', '736', '2', 0, ''),
(12613, 1421, 'اللُّؤْمُ إِيثارُ حُبِّ الْمالِ عَلى لَذَّةِ الْحَمْدِ وَ الثَّناءِ.', NULL, '7', '26', '198', '736', '2', 0, ''),
(12614, 1422, 'العامِلُ بِجَهْلٍ كَالسّائِرِعَلى غيرِ طَريقٍ فَلا يُجْديهِ جدُّهُ فِي السَّيرِ إِلّا بُعْداً عَنْ حاجَتِهِ.', NULL, '7', '26', '198', '736', '2', 0, ''),
(12615, 1423, 'النّاسُ أبْناءُ الدُّنْيا وَالْوَلَدُ مَطْبُوعٌ عَلى حُبِّ أُمِّهِ.', NULL, '7', '26', '198', '736', '2', 0, ''),
(12616, 1424, 'العاقِلُ مَنِ اتَّهَمَ َرأْيَهُ وَلَمْ يَثِقْ بِكُلِّ ما تُسَوِّلُ لَهُ نَفْسُهُ.', NULL, '7', '26', '198', '736', '2', 0, ''),
(12617, 1425, 'المُؤْمِنُ حَيِيٌّ غَنِيٌّ مُوقَّرٌتَقِيٌّ.', NULL, '7', '26', '198', '736', '2', 0, ''),
(12618, 1426, 'المُنافِقُ وَقِحٌ غَبِيٌّ مُتَمَلِّقٌ شَقِيٌّ.', NULL, '7', '26', '198', '736', '2', 0, ''),
(12619, 1427, 'الكَلامُ بَينَ خَلَّتَيْ سَوْءٍ هُمَا الْإِكْثارُ وَ الْإِقْلالُ فَالْإِكْثارُ هَذَرٌ وَ الْإِقْلالُ عَيٌّ.', NULL, '7', '26', '198', '736', '2', 0, ''),
(12620, 1428, 'المُشاوَرَةُ راحَةٌ لَكَ وَتَعَبٌ لِغَيرِكَ.', NULL, '7', '26', '198', '736', '2', 0, ''),
(12621, 1429, 'الذِّكْرُ يُؤنِسُ اللُّبَّ وَيُنْيرُ الْقَلْبَ وَ يَسْتَنْزِلُ الرَّحْمَةَ.', NULL, '7', '26', '198', '736', '2', 0, ''),
(12622, 1430, 'ألْأَوَّلُ مِنْ عِوَضِ الْحَليمِ عَنْ حِلْمِهِ أنَّ النّاسَ كُلِّهُمْ أَنْصارُهُ عَلى خَصْمِهِ.', NULL, '7', '26', '198', '736', '2', 0, ''),
(12623, 1431, 'العَمَلُ بِطاعَةِ اللهِ أرْبَحُ وَلِسانُ الصِّدْقِ أَزْيَنُ وَ أَرْجَحُ.', NULL, '7', '26', '198', '736', '2', 0, ''),
(12624, 1432, 'الغَدْرُ بِكُلِّ أَحَدٍ قَبيحٌ وَهُوَ بِذَوِي الْقُدْرَةِ وَ السُّلْطانِ أَقْبَحُ.', NULL, '7', '26', '198', '736', '2', 0, ''),
(12625, 1433, 'الكَريمُ إِذا قَدَرَ صَفَحَ وَإِذا مَلَكَ سَمَحَ وَ إِذا سُئِلَ أَنْجَحَ.', NULL, '7', '26', '198', '736', '2', 0, ''),
(12626, 1434, 'الْوَرَعُ يُصْلِحُ الدِّينَ وَيَصُونُ النَّفْسَ وَ الْيَقينَ وَ يَزينُ الْمُرُوَّةَ.', NULL, '7', '26', '198', '736', '2', 0, ''),
(12627, 1435, 'العاقِلُ مَنْ زَهِدَ فِي دَنِيَّةٍ فانِيَةٍ وَ رَغِبَ فِي جَنَّةٍ سَنِيَّةٍ خالِدَةٍ عالِيَةٍ.', NULL, '7', '26', '198', '736', '2', 0, ''),
(12628, 1436, 'الصَّبْرُ أفْضَلُ سَجِيَّةٍ وَالْعِلْمُ أَفْضَلُ حُلْيَةٍ وَ عَطِيَّةٍ.', NULL, '7', '26', '198', '736', '2', 0, ''),
(12629, 1437, 'المُتَّقي مَنِ اتَّقى مِنَ الذُّنوبِ وَ المُتَنَزِّهُ مَنْ تَنَزَّهَ عَنِ الْعُيُوبِ.', NULL, '7', '26', '198', '736', '2', 0, ''),
(12630, 1438, 'الفِكْرُ فِي الْأَمْرِ قَبْلَ مُلابَسَتِهِ يُؤْمِنُ الزَّلَلَ.', NULL, '7', '26', '198', '736', '2', 0, ''),
(12631, 1439, 'الصَّبْرُ أنْ يَحْتَمِلَ الرَّجُلُ مَا يَنُوبُهُ وَ يَكْظِمُ ما يُغْضِبُهُ.', NULL, '7', '26', '198', '736', '2', 0, ''),
(12632, 1440, 'الصَّفْحُ أنْ يَعْفُوَ الرَّجُلُ عَمَّا يُجْنى عَلَيْهِ وَ يَحْلُمُ عَمّا يَغيظُهُ.', NULL, '7', '26', '198', '736', '2', 0, ''),
(12633, 1441, 'الحازِمُ مَنْ لا يَشْغَلُهُ النَّعْمَةُ عَنِ الْعَمَلِ لِلْعاقِبَةِ.', NULL, '7', '26', '198', '736', '2', 0, ''),
(12634, 1442, 'الرّابِحُ مَنْ باعَ الدُّنْيابِالْاخِرَةِ وَ ابْتاعَ الْاجِلَةِ بِالْعاجِلَةِ.', NULL, '7', '26', '198', '736', '2', 0, ''),
(12635, 1443, 'الشَّرَهُ مَرْكَبُ الْحِرْصِ وَالْهَوى مَرْكَبُ الْفِتْنَةِ.', NULL, '7', '26', '198', '736', '2', 0, ''),
(12636, 1444, 'البَلاغَةُ مَا سَهُلَ عَلى النُّطْقِ وَ خَفَّ عَلى الْفِطْنَةِ.', NULL, '7', '26', '198', '736', '2', 0, ''),
(12637, 1445, 'النّاسُ كَصُوَرٍ فِي صَحيفَةٍ كُلَّما طُوِيَ بَعْضُها نُشِرَ بَعْضُها.', NULL, '7', '26', '198', '736', '2', 0, ''),
(12638, 1446, 'البَخيلُ يَبْخَلُ عَلى نَفْسِهِ بِالْيَسيرِ مِنْ دُنْياهُ وَ يَسْمَحُ لِوارِثِهِ بِكُلِّها.', NULL, '7', '26', '198', '736', '2', 0, ''),
(12639, 1447, 'المَرْأَةُ شَرٌّ كُلُّها، وَشَرٌّمِنْها أَنَّهُ لا بُدَّ مِنْها.', NULL, '7', '26', '198', '736', '2', 0, ''),
(12640, 1448, 'الحَسَدُ داءٌ عَياءٌ لايَزُولُ إِلّا بِهُلْكِ الْحاسِدِ أَوْ بِمَوْتِ الْمَحْسُودِ.', NULL, '7', '26', '198', '736', '2', 0, ''),
(12641, 1449, 'الذُّنُوبُ الدّاءُ، وَالدَّواءُ الْإِسْتِغْفارُ، وَ الشِّفاءُ أَنْ لا تَعُودَ.', NULL, '7', '26', '198', '736', '2', 0, ''),
(12642, 1450, 'الحَسَدُ يَأْكُلُ الْحَسَناتِ كَما تَأْكُلُ النّارُ الْحَطَبَ.', NULL, '7', '26', '198', '736', '2', 0, ''),
(12643, 1451, 'الصَّبْرُ صَبْرانِ: صَبْرٌ عَلى ما تُحِبُّ وَ صَبْرٌ عَلى ما تَكْرَهُ.', NULL, '7', '26', '198', '736', '2', 0, ''),
(12644, 1452, 'الصَّبْرُ أَحْسَنُ خِلالِ الْإِيمانِ وَ أَشْرَفُ خَلائِقِ الْإِنْسانِ.', NULL, '7', '26', '198', '736', '2', 0, ''),
(12645, 1453, 'الكَيِّسُ مَنْ أَحْيى فَضائِلَهُ وَ أَماتَ رَذائِلَهُ بِقَمْعِهِ شَهْوَتَهُ وَ هواهُ.', NULL, '7', '26', '198', '736', '2', 0, ''),
(12646, 1454, 'الْأَمَلُ كَالسَّرابِ يُغِرُّ مَنْ رَآهُ وَ يُخْلِفُ مَنْ رَجاهُ.', NULL, '7', '26', '198', '736', '2', 0, ''),
(12647, 1455, 'السُّلْطانُ الْجائِرُ وَالْعالِمُ الْفاجِرُ أَشَدُّ النّاسِ نِكايَةً.', NULL, '7', '26', '198', '736', '2', 0, ''),
(12648, 1456, 'الكافِرُ خِبٌّ لَئيمٌ خَؤُنٌ مَغْرُورٌ بِجَهْلِهِ مَغْبُونٌ.', NULL, '7', '26', '198', '736', '2', 0, ''),
(12649, 1457, 'المُؤْمِنُ غِرٌّ كَريمٌ مَأْمُونٌ عَلى نَفْسِهِ |حَذِرٌ| مَحْزُونٌ.', NULL, '7', '26', '198', '736', '2', 0, ''),
(12650, 1458, 'الرّاضي عَنْ نَفْسِهِ مَفْتُونٌ وَ الْواثِقُ بِها مَغْرُورٌ مَغْبُونٌ.', NULL, '7', '26', '198', '736', '2', 0, ''),
(12651, 1459, 'الشرِّيرُ لا يَظُنُّ بِأَحَدٍخَيْراً لِأَنَّهُ لا يَراهُ إلّا بِطَبْعِ نَفْسِهِ.', NULL, '7', '26', '198', '736', '2', 0, ''),
(12652, 1460, 'المَرْءُ حَيْثُ وَضَعَ نَفْسَهُ بِرياضَتِهِ |وَ طاعَتِهِ| فَإِنْ نَزَّهَهاتَنَزَّهَتْ وَ إِنْ دَنَّسَها تَدَنَّسَتْ.', NULL, '7', '26', '198', '736', '2', 0, ''),
(12653, 1461, 'العَوافي إِذا دامَتْ جُهِلَتْ وَ إِذا فُقِدَتْ عُرِفَتْ.', NULL, '7', '26', '198', '736', '2', 0, ''),
(12654, 1462, 'الجَوادُ مَحْبُوبٌ مَحْمُودٌوَ إِنْ لَمْ يَصِلْ مِنْ جُودِهِ شَيْ ءٌ إِلى مادِحِهِ وَ الْبَخيلُ ضِدُّ ذلِكَ.', NULL, '7', '26', '198', '736', '2', 0, ''),
(12655, 1463, 'الجائِرُ مَمْقُوتٌ مَذْمُومٌ وَإِنْ لَمْ يَصِلْ إِلى ذامِّهِ شَي ءٌ مِنْ جَوْرِهِ وَ الْعادِلُ ضِدُّ ذلِكَ.', NULL, '7', '26', '198', '736', '2', 0, ''),
(12656, 1464, 'الدُّنْيا دُوَلٌ فَأَجْمِلْ فِي طَلَبِها وَ اصْطَبِرْ حَتّى تَأْتِيَكَ دَوْلَتُكَ.', NULL, '7', '26', '198', '736', '2', 0, ''),
(12657, 1465, 'الخُرْقُ الْإِسْتِهْتارُ بِالْفُضُولِ وَ مُصاحَبَةُ الْجَهُولِ.', NULL, '7', '26', '198', '736', '2', 0, ''),
(12658, 1466, 'التَّوَكُّلُ التَّبَرّي مِنَ الْحَوْلِ وَ الْقُوَّةِ وَ انْتِظارُ ما يَأْتي بِهِ الْقَدَرُ.', NULL, '7', '26', '198', '736', '2', 0, ''),
(12659, 1467, 'الكَيِّسُ مَنْ دانَ بِتَقْوَى اللهِ سُبْحانَهُ وَ تَجنُّبِ الْمَحارِمِ وَ إِصْلاحِ الْمَعادِ.', NULL, '7', '26', '198', '736', '2', 0, ''),
(12660, 1468, 'الحازِمُ مَنْ جادَ بِمافي يَدِهِ وَ لَمْ يُؤَخَّرْ عَمَلَ يَوْمِهِ إِلى غَدِهِ.', NULL, '7', '26', '198', '736', '2', 0, ''),
(12661, 1469, 'الحِكْمَةُ لا تَحُلُّ قَلْبَ الْمُنافِقِ إِلّا وَ هِيَ عَلى ارْتِحالٍ.', NULL, '7', '26', '198', '736', '2', 0, ''),
(12662, 1470, 'اَلشَّرَفُ عِنْدَ اللهِ بِحُسْنِ الْأَعْمالِ لا بِحُسْنِ الْأَقْوالِ.', NULL, '7', '26', '198', '736', '2', 0, ''),
(12663, 1471, 'الفَضيلَةُ بِحُسْنِ الْكَمالِ وَ مَكارِمِ الْأَفْعالِ لا بِكِثْرَةِ المالِ وَجَلالَةِ الْأَعْمالِ.', NULL, '7', '26', '198', '736', '2', 0, ''),
(12664, 1472, 'الْإِسْتِصْلاحُ لِلأَعْداءِ بِحُسْنِ الْمَقالِ وَ جَميلِ الْأَفْعالِ أَهْوَنُ مِنْ مُلاقاتِهِمْ |وَمُغالَبَتِهِمْ| بِمَضيضِ الْقِتالِ.', NULL, '7', '26', '198', '736', '2', 0, ''),
(12665, 1473, 'الصَّبْرُ عَنِ الشَّهْوَةِ عِفَّةٌ وَ عَنِ الْغَضَبِ نَجْدَةٌ وَ عَنِ الْمَعْصِيَةِ تَوَرُّعٌ.', NULL, '7', '26', '198', '736', '2', 0, ''),
(12666, 1474, 'السَّخاءُ أنْ تَكُونَ بِمالِكَ مُتَبَرِّعاً وَ عَنْ مالِ غَيرِكَ مُتَوَرِّعاً.', NULL, '7', '26', '198', '736', '2', 0, ''),
(12667, 1475, 'الفَقيرُ الرّاضي ناجٍ مِنْ حَبائِل إِبْليسَ وَ الغَنِيُّ واقِعٌ فِي حَبائِلِهِ.', NULL, '7', '26', '198', '736', '2', 0, ''),
(12668, 1476, 'اللَّئيمُ لا يُرْجى خَيْرُهُ وَلا يُسْلَمُ مِنْ شَرِّهِ وَ لا يُؤْمَنُ غَوائِلُهُ.', NULL, '7', '26', '198', '736', '2', 0, ''),
(12669, 1477, 'المُؤْمِنُونَ أنْفُسُهُمْ عَفيفَةٌ وَ حاجاتُهُمْ خَفيفَةُ وَ خَيْراتُهُمْ مَأْمُولَةٌ وَ شُرُورُهُمْ مَأْمُونَةٌ.', NULL, '7', '26', '198', '736', '2', 0, ''),
(12670, 1478, 'المُتَّقُونَ أَنْفُسُهُمْ قانِعَةٌ وَشَهَواتُهُمْ مَيِّتَةٌ وَ وُجُوهُهُمْ مُسْتَبْشِرَةٌ وَ قُلُوبُهُمْ مَحْزُونَةٌ.', NULL, '7', '26', '198', '736', '2', 0, ''),
(12671, 1479, 'المُؤْمِنُ دائِمُ الْفِكْرِ وَكَثيرُ الذِّكْرِ، عَلى النَّعْماءِ شاكِرٌ وَفِي الْبَلاءِ صابِرٌ.', NULL, '7', '26', '198', '736', '2', 0, ''),
(12672, 1480, 'الدُّنْيا عَرَضٌ حاضِرٌ يَأْكُلُ مِنْهُ الْبَرُّ وَ الْفاجِرُ وَ الْآخِرَةُ دارُ حَقٍّ يَحْكُمُ فيها مَلِكٌ قادِرٌ.', NULL, '7', '26', '198', '736', '2', 0, ''),
(12673, 1481, 'الْإِيمانُ هُوَ التَّسْليمُ وَالتَّسْليمُ هُوَ الْيَقينُ وَ الْيَقينُ هُوَ التَّصْديقُ وَالتَّصْديقُ هُوَ الْإِقْرارُ وَالْإِقْرارُ هُوَ الْأَداءُ وَ الْأَداءُ هُو الْعَمَلُ.', NULL, '7', '26', '198', '736', '2', 0, ''),
