(12838, 1646, 'الزَّمانُ يَخُونُ صاحِبَهُ وَلا يَسْتَعْتِبُ لِمَنْ عاتَبَهُ.', NULL, '7', '26', '198', '736', '2', 0, ''),
(12839, 1647, 'أَلْإِيمانُ وَ الْعَقْلُ أَخوانِ تَوْأَمانِ وَ رَفيقانِ لا يَفْتَرِقانِ لا يَقْبَلُ اللهُ سُبْحانَهُ وَ تَعالى أَحَدَهُما إِلّا بِصاحِبِهِ.', NULL, '7', '26', '198', '736', '2', 0, ''),
(12840, 1648, 'المَذَلَّةُ وَ الْمَهانَةُ وَالشَّقاءُ، فِي الْحِرْصِ وَ الطَّمَع.', NULL, '7', '26', '198', '736', '2', 0, ''),
(12841, 1649, 'النّاسُ كَالشَّجَرِ شُرْبُهُ واحِدٌ وَ ثَمَرُهُ مُخْتَلِفٌ.', NULL, '7', '26', '198', '736', '2', 0, ''),
(12842, 1650, 'العَقْلُ صاحِبُ جَيْشِ الرَّحْمنِ وَ الْهَوى قائِدُ جَيْشِ الشَّيْطانِ وَالنَّفْسُ مُتَجاذَبَةٌ بَيْنَهُما فَأَيُّهُما غَلَبَ كانَتْ في حَيِّزِهِ.', NULL, '7', '26', '198', '736', '2', 0, ''),
(12843, 1651, 'العِلْمُ عِلْمانِ مَطْبُوعٌ وَمَسْمُوعٌ وَ لا يَنْفَعُ الْمَطْبُوعُ إِذا لَمْ يَكُ مَسْمُوعٌ.', NULL, '7', '26', '198', '736', '2', 0, ''),
