(17014, 5822, 'عادَةُ الأغْمارِ| قَطْعُ مَوادِّالْإِحْسانِ.', NULL, '7', '43', '251', '789', '2', 0, ''),
(17015, 5823, 'عادَةُ اللِّئامِ قُبْحُ الْوَقيعَةِ.', NULL, '7', '43', '251', '789', '2', 0, ''),
(17016, 5824, 'عادَةُ الْكِرامِ حُسْنُ الصَّنيعَةِ.', NULL, '7', '43', '251', '789', '2', 0, ''),
(17017, 5825, 'عِلْمُ الْمُنافِقِ في لِسانِه.', NULL, '7', '43', '251', '789', '2', 0, ''),
(17018, 5826, 'عِلْمُ الْمُؤْمِنِ في عَمَلِه.', NULL, '7', '43', '251', '789', '2', 0, ''),
(17019, 5827, 'عِلْمٌ لا يَنْفَعُ كَدَواءٍ لا يَنْجَعُ.', NULL, '7', '43', '251', '789', '2', 0, ''),
(17020, 5828, 'عَبْدُ الشَّهْوَةِ أَذَلُّ مِنْ عَبْدِ الرِّقِّ.', NULL, '7', '43', '251', '789', '2', 0, ''),
(17021, 5829, 'عَبْدُ الشَّهْوَةِ أَسيرٌ لا يُفَكُّ أَسْرُهُ.', NULL, '7', '43', '251', '789', '2', 0, ''),
(17022, 5830, 'عِلَّةُ الْمُعاداةِ قِلَّةُ الْمُبالاةِ.', NULL, '7', '43', '251', '789', '2', 0, ''),
(17023, 5831, 'عَلِّمُوا أَوْلادَكُمُ الصَّلاةَ لِسَبْعٍ وَ خُذُوهُمْ بِها إِذا بَلَغُوا الْحُلُمَ.', NULL, '7', '43', '251', '789', '2', 0, ''),
(17024, 5832, 'عِظَمُ الْجَسَدِ وَ طُولُهُ لا يَنْفَعُ إِذا كانَ الْقَلْبُ خاوِياً.', NULL, '7', '43', '251', '789', '2', 0, ''),
(17025, 5833, 'عَلَيْكُمْ بِالْقَصْدِ فِي الْمَطاعِمِ فَإِنَّهُ أَبْعَدُ مِنَ السَّرَفِ وَ أَصْحُّ لِلبَدَنِ وَ أَعْوَنُ عَلى
INSERT INTO `words` (`_id`, `BookId`, `Wisdom`, `enWisdom`, `Qsm`, `Bab`, `Fsl`, `Topic`, `Source`, `fav`, `lastcheckdate`) VALUES
(18002, 6810, 'لِلكِرامِ فَضيلَةُ الْمُبادَرَةِ إِلى فِعْلِ الْمَعْرُوفِ وَ إِسْداءِ الصَّنائِعِ.', NULL, '7', '48', '265', '803', '2', 0, ''),
(18003, 6811, 'لِلْإِنْسانِ فَضيلَتانِ عَقْلٌ وَ مَنْطِقٌ فَبِالْعَقْلِ يَسْتَفْيدُ وَ بِالْمَنْطِقِ يُفيدُ.', NULL, '7', '48', '265', '803', '2', 0, ''),
(18004, 6812, 'لِلْمُتَّقي هُدىً في رَشادٍ وَ تَحَرُّجٌ عَنْ فَسادٍ وَ حِرْصٌ فِي إِصْلاحِ مَعادٍ.', NULL, '7', '48', '265', '803', '2', 0, ''),
(18005, 6813, 'لِيَكُنْ مَوْئِلُكَ إِلى الْحَقِّ فَإِنَّ الْحقَّ أَقْوى مُعينٍ.', NULL, '7', '48', '265', '803', '2', 0, ''),
(18006, 6814, 'لِيَكُنْ مَرْجَعُكَ إِلى الصِّدْقِ فَإِنَّ الصِّدْقَ خَيْرُ قَرينٍ.', NULL, '7', '48', '265', '803', '2', 0, ''),
(18007, 6815, 'لِلحَقِّ دَوْلَةٌ.', NULL, '7', '48', '265', '803', '2', 0, ''),
(18008, 6816, 'لِلْباطِلِ جَوْلَةٌ.', NULL, '7', '48', '265', '803', '2', 0, ''),
(18009, 6817, 'لِلطّالِبِ الْبالِغِ لَذَّةُ الْإِدْراكِ.', NULL, '7', '48', '265', '803', '2', 0, ''),
(18010, 6818, 'لِلْآئِسِ الْخائِبِ مَضضَضُ الْهَلاكِ.', NULL, '7', '48', '265', '803', '2', 0, ''),
(18011, 6819, 'لِلعادَةِ عَلى كُلِّ إِنْسانٍ سُلْطانٌ.', NULL, '7', '48', '265', '803', '2', 0, ''),
(18012, 6820, 'لِلعاقِلِ في كُلِّ عَمَلٍ إِحْسانٌ.', NULL, '7', '48', '265', '803', '2', 0, ''),
(18013, 6821, 'لِلْجاهِلِ في كُلِّ حالَةٍ خُسْرانٌ.', NULL, '7', '48', '265', '803', '2', 0, ''),
(18014, 6822, 'لِلْظّالِمِ "الْبادي غَداً" بِكفِّهِ عَضَّةٌ.', NULL, '7', '48', '265', '803', '2', 0, ''),
(18015, 6823, 'لِلمُسْتَحْلي لَذَّةَ الدُّنْيا غُصَّةٌ.', NULL, '7', '48', '265', '803', '2', 0, ''),
(18016, 6824, 'لِلأَحْمَقِ مَعَ كُلِّ قَوْلٍ يَمينٌ.', NULL, '7', '48', '265', '803', '2', 0, ''),
(18017, 6825, 'لِرُسُلِ اللهِ في كُلِّ حُكْمٍ تَبْيينٌ.', NULL, '7', '48', '265', '803', '2', 0, ''),
(18018, 6826, 'لِلْكَيِّسِ فِي كُلِّ شَيْ ءٍ اتِّعاظٌ.', NULL, '7', '48', '265', '803', '2', 0, ''),
(18019, 6827, 'لِلعاقِلِ فِي كُلِّ عَمَلٍ ارْتِياضٌ.', NULL, '7', '48', '265', '803', '2', 0, ''),
(18020, 6828, 'لَقَدْ بُصِّرْتُمْ إِنْ أَبْصَرْتُمْ وَ أُسْمِعْتُمْ إِنْ سَمِعْتُمْ وَ هُديتُمْ إِنِ اهْتَدَيْتُمْ.', NULL, '7', '48', '265', '803', '2', 0, ''),
(18021, 6829, 'لَدُنْياكُمْ عِنْدي أَهْوَنُ مِنْ عُراقِ خِنْزيرٍ عَلى يَدِ مَجْذُومٍ.', NULL, '7', '48', '265', '803', '2', 0, ''),
(18022, 6830, 'وَ قال عليه السّلام لِمَنْ يَسْتَصْغِرُهُ عَنْ مِثْلِ مَقالِه: لَقَدْ طِرْتَ شَكيراً وَ هَدَرْتَ سُقْباً.', NULL, '7', '48', '265', '803', '2', 0, ''),
(18023, 6831, 'لِيكُنْ مَسْأَلَتُكَ |في| ما يَبْقى |لَكَ| جَمالُهُ وَ يَنْفى عَنْكَ وَبالَهُ.', NULL, '7', '48', '265', '803', '2', 0, ''),
(18024, 6832, 'لِلْقُلُوبِ خَواطِرُ سَوْءِ وَ الْعُقُولُ تَزْجُرُ عَنْها.', NULL, '7', '48', '265', '803', '2', 0, ''),
(18025, 6833, 'لِيكْفِكُمْ مِنَ الْعِيانِ السَّماعُ وَ مِنَ الْغَيْبِ الْخَبَرُ.', NULL, '7', '48', '265', '803', '2', 0, ''),
(18026, 6834, 'لِأَنْ تَكُونَ تَابِعاً فِي الْخَيرِ خَيرٌ لَكَ مِنْ أَنْ تَكُونَ مَتْبُوعاً فِي الشَّرِّ.', NULL, '7', '48', '265', '803', '2', 0, ''),
(18027, 6835, 'لِيَكُفَّ مَنْ عَلِمَ مِنْكُمْ مِنْ عَيْبِ غَيرِه لِما يَعْرِفُ مِنْ عَيْبِ نَفْسِه.', NULL, '7', '48', '265', '803', '2', 0, ''),
(18028, 6836, 'لَتَرجْعُ الْفُرُوعُ إِلى أُصُولِها وَ الْمَعْلُولاتُ إِلى عِلَلِها وَ الْجُزْئِيّاتُ إِلى كُلِّيّاتِها.', NULL, '7', '48', '265', '803', '2', 0, ''),
(18029, 6837, 'لِلظّالِمِ مِنَ الرِّجالِ ثَلاثُ عَلاماتٍ: يَظلِمُ مَنْ فَوْقَهُ بِالْمَعْصِيَةِ، وَ مَنْ دُونَهُ بِالْغَلَبَةِ، وَ يُظاهِرُ الْقَوْمَ الظَّلَمَةَ.', NULL, '7', '48', '265', '803', '2', 0, ''),
(18030, 6838, 'لِيكُنِ الشُّكْرُ شاغِلاً لَكَ عَلى مُعافاتِكَ مِمَّا ابْتُلِي بِه غَيرُكَ.', NULL, '7', '48', '265', '803', '2', 0, ''),
(18031, 6839, 'لِيُرَ عَلَيْكَ أَثَرُ ما أَنْعَمَ اللهُ بِه عَلَيْكَ.', NULL, '7', '48', '265', '803', '2', 0, ''),
(18032, 6840, 'لِيَنْهَكَ عَنْ مَعائِبِ النّاسِ ما تَعْرِفُ مِنْ مَعائِبِكَ.', NULL, '7', '48', '265', '803', '2', 0, ''),
(18033, 6841, 'لِحُبِّ الدُّنْيا صُمَّتِ الْأَسْماعُ عَنْ سَماعِ الْحِكْمَةِ وَ عَمِيَتِ الْقُلُوبُ عَنْ نُورِ الْبَصيرَةِ.', NULL, '7', '48', '265', '803', '2', 0, ''),
(18034, 6842, 'لِيكُنْ أَحَبُّ النّاسِ إِلَيْكَ مَنْ |هَداكَ إلى مَراشِدِكَ وَ| كَشَفَ لَكَ عَنْ مَعائِبِكَ.', NULL, '7', '48', '265', '803', '2', 0, ''),
(18035, 6843, 'لِيَكُنْ أَوْثَقَ النّاسِ لَدَيْكَ أَنْطَقهُمْ بِالصِّدْقِ.', NULL, '7', '48', '265', '803', '2', 0, ''),
(18036, 6844, 'لِيَخْشَعْ لِلّهِ قَلْبُكَ فَمَنْ خَشَعَ قَلْبُهُ خَشَعَتْ جَميعُ جَوارِحه.', NULL, '7', '48', '265', '803', '2', 0, ''),
(18037, 6845, 'لَبِئْسَ الْمَتْجَرُ أَنْ تَرى الدُّنْيا لِنَفْسِكَ ثَمَناً وَ فيما لَكَ عِنْدَ اللهِ عِوَضاً.', NULL, '7', '48', '265', '803', '2', 0, ''),
(18038, 6846, 'لَقَدْ كاشَفَتْكُمُ الدُّنْيا الْغِطاءَ وَ آذَنَتْكُمْ عَلى سَواءٍ.', NULL, '7', '48', '265', '803', '2', 0, ''),
(18039, 6847, 'لِلمُتَجَرّي عَلى الْمَعاصي سَخَطُ اللهِ.', NULL, '7', '48', '265', '803', '2', 0, ''),
(18040, 6848, 'لَقَدْ أَتْعَبَكَ مَنْ أَكْرَمَكَ إِنْ كُنْتَ كَريماً وَ لَقَدْ أَراحَكَ مَنْ أَهانَكَ إِنْ كُنْتَ حَليماً.', NULL, '7', '48', '265', '803', '2', 0, ''),
(18041, 6849, 'لَقَدْ جاهَرَتْكُمُ الْعِبَرُ وَ زَجَرَكُمْ ما فيهِ مُزْدَجَرٌ وَ ما بَلَّغَ عَنِ اللهِ بَعْدَ رُسُلِ السَّماءِ مِثْلُ النُّذُرِ.', NULL, '7', '48', '265', '803', '2', 0, ''),
(18042, 6850, 'لِطالِبِ الْعِلْمِ عِزُّ الدُّنْيا وَ فَوْزُ الْاخِرَةِ.', NULL, '7', '48', '265', '803', '2', 0, ''),
(18043, 6851, 'لِمُبغِضينا أَمْواجُ مِنْ سَخَطِ اللهِ.', NULL, '7', '48', '265', '803', '2', 0, ''),
(18044, 6852, 'لَقَدْ رَقَعْتُ مِدْرَعَتي هذِه حَتَّى اسْتَحْيَيْتُ مِنْ راقِعِها فَقالَ لي قائِلٌ: أَلا تَنْبِذُها؟ فَقُلْتُ لَهُ: اعْزُبْ عَنّي فَعِنْدَ الصَّباحِ يَحْمَدُ الْقَوْمُ السُّرى.', NULL, '7', '48', '265', '803', '2', 0, ''),
(18045, 6853, 'لَيْسَتِ الْأَنْسابُ بِالْاباءَ وَ الْاُمَّهاتِ لكِنَّها بِالْفَضائِلِ الْمَحْمُوداتِ.', NULL, '7', '48', '265', '803', '2', 0, ''),
(18046, 6854, 'لِلمُؤْمِنِ عَقْلٌ وَفِيٌّ وَ حِلْمٌ رَضِيٌّ وَ رَغْبَةٌ فِي الْحَسَناتِ وَ فِرارٌ مِنَ السَّيِّئاتِ.', NULL, '7', '48', '265', '803', '2', 0, ''),
(18047, 6855, 'لَتَعْطِفَنَّ عَلَيْنَا الدُّنْيا بَعْدَ شِماسِها عَطْفَ الضَّرُوسِ عَلى وَلَدِها.', NULL, '7', '48', '265', '803', '2', 0, ''),
(18048, 6856, 'لِلمُؤْمِنِ ثَلاثُ ساعاتٍ: ساعَةٌ يُناجي فيها رَبَّهُ، وَ ساعَةٌ يُحاسِبُ فيها نَفْسَهُ، وَساعَةٌ يُخَلّي فيها بَينَ نَفْسِه وَ بَينَ لَذّاتِها فيما يَحِلُّ وَ يَجْمُلُ.', NULL, '7', '48', '265', '803', '2', 0, ''),
(18049, 6857, 'لٍيكُنْ أَبَرَّ النَّاسِ عِنْدَكَ أَعْمَلُهُمْ بِالرِّفْقِ.', NULL, '7', '48', '265', '803', '2', 0, ''),
(18050, 6858, 'لِيكُنْ زُهْدُكَ فيما |يَنْفَدُ وَ يزُولُ فَإِنَّهُ لا يَبْقى لَكَ وَ لا تَبْقى لَهُ.', NULL, '7', '48', '265', '803', '2', 0, ''),
(18051, 6859, 'لِيكُنْ أَحَبَّ النّاسِ إِلَيْكَ وَ أَحْظاهُمْ لَدَيْكَ أَكْثَرُهُمْ سَعْياً في مَنافِعِ النّاسِ.', NULL, '7', '48', '265', '803', '2', 0, ''),
(18052, 6860, 'لِيَكُنْ أَبْغَضَ النّاسِ إِلَيْكَ وَ أَبْعَدَهُمْ مِنْكَ أَطْلَبُهُمْ لِمَعائِبِ النّاسِ.', NULL, '7', '48', '265', '803', '2', 0, ''),
(18053, 6861, 'لِيَكُنْ أَوْثَقَ الذَّخائِرِ عِنْدَكَ الْعَمَلُ الصّالِحُ.', NULL, '7', '48', '265', '803', '2', 0, ''),
(18054, 6862, 'لِيَكُنْ مَرْجِعُكَ إِلى الْحَقِّ فَمَنْ فارَقَ الْحَقَّ هَلَكَ.', NULL, '7', '48', '265', '803', '2', 0, ''),
(18055, 6863, 'لِيَكُنْ زادَكَ التُّقى.', NULL, '7', '48', '265', '803', '2', 0, ''),
(18056, 6864, 'لِيَكُنْ شِعارَكَ الْهُدى.', NULL, '7', '48', '265', '803', '2', 0, ''),
(18057, 6865, 'لِيَكُنْ سَميرَكَ الْقُرْآنُ.', NULL, '7', '48', '265', '803', '2', 0, ''),
(18058, 6866, 'لِيَكُنْ سَجِيَّتُكَ الْإِحْسانَ.', NULL, '7', '48', '265', '803', '2', 0, ''),
(18059, 6867, 'لِيَكُنْ مَرْكَبُكَ الْعَدْلََ فَمَنْ رَكِبَهُ مَلَكَ.', NULL, '7', '48', '265', '803', '2', 0, ''),
(18060, 6868, 'لِيَكُنْ شيمَتَكَ الْوَقارُ فَمَنْ كَثُرَ خُرْقُهُ اسْتَرْذَلَ.', NULL, '7', '48', '265', '803', '2', 0, ''),
(18061, 6869, 'لَئِنْ أَمِرَ الْباطِلْ لَقَديماً فَعَلَ.', NULL, '7', '48', '265', '803', '2', 0, ''),
(18062, 6870, 'لَئِنْ قَلَّ الْحَقُّ فَلَرُبَّما وَ لَعَلَّ.', NULL, '7', '48', '265', '803', '2', 0, ''),
(18063, 6871, 'لَقَلَّما أَدبَرَ شَيْ ءٌ فَأَقْبَلَ.', NULL, '7', '48', '265', '803', '2', 0, ''),
(18064, 6872, 'لَرُبَّما أَقْبَلَ الْمُدْبِرُ وَ أَدْبَرَ الْمُقْبِلُ.', NULL, '7', '48', '265', '803', '2', 0, ''),
(18065, 6873, 'لِيَكُنْ أَحْظَا النّاسِ مِنْكَ أَحْوَطُهُمْ عَلى الضُّعَفاءِ وَ أَعْمَلُهُمْ بِالْحَقِّ.', NULL, '7', '48', '265', '803', '2', 0, ''),
(18066, 6874, 'لِيكُنْ أَحَبَّ الْاُمُورِ إِلَيْكَ أَعَمُّها في الْعَدْلِ وَ أَقْسَطُها بِالْحَقِّ.', NULL, '7', '48', '265', '803', '2', 0, ''),
