(18164, 6972, 'لَيْسَ لِإِبْليسَ جُنْدٌ أَعْظَمَ مِنَ الْغَضَبِ وَ النِّساءِ.', NULL, '7', '48', '267', '805', '2', 0, ''),
(18165, 6973, 'لَيْسَ لِأَحَدٍ بَعْدَ الْقُرْآنِ مِنْ فَاقَةٍ وَ لا لِأَحَدٍ قَبْلَ الْقُرآن غِنىً.', NULL, '7', '48', '267', '805', '2', 0, ''),
(18166, 6974, 'لَيْسَ بَلَدٌ أَحَقَّ بِكَ مِنْ بَلَدٍ، خَيْرُ البِلادِ ما حَمَلَكَ.', NULL, '7', '48', '267', '805', '2', 0, ''),
(18167, 6975, 'لَيْسَ شَيْ ءٌ أَعَزَّ مِنَ الْكِبْريتِ الْأَحْمَرِ إِلَّا ما بَقِيَ مِنْ عُمْرِ الْمُؤْمِنِ.', NULL, '7', '48', '267', '805', '2', 0, ''),
(18168, 6976, 'لَيْسَ ثَوابٌ عِنْدَ اللهِ سُبْحانَهُ أَعْظَمَ مِنْ ثَوابِ السُّلْطانِ الْعادِلِ وَ الرَّجُلِ الْمُحْسِنِ.', NULL, '7', '48', '267', '805', '2', 0, ''),
(18169, 6977, 'لَيْسَ كُلُّ مَنْ طَلَبَ وَجَدَ.', NULL, '7', '48', '267', '805', '2', 0, ''),
(18170, 6978, 'لَيْسَ كُلُّ مَنْ ضَلّ فَقَِدَ.', NULL, '7', '48', '267', '805', '2', 0, ''),
(18171, 6979, 'لَيْسَ شَيْ ءٌ أَدْعى إِلى زَوالِ نِعْمَةٍ وَ تَعْجيلِ نِقْمَةٍ مِنْ إِقامَةٍ عَلى ظُلْمٍ.', NULL, '7', '48', '267', '805', '2', 0, ''),
(18172, 6980, 'لَيْسَ فِي الْغُرْبَةِ عارٌ وَ إِنَّمَا الْعارُ فِي الْوَطَنِ الْإِفْتِقارُ.', NULL, '7', '48', '267', '805', '2', 0, ''),
(18173, 6981, 'لَيْسَ لِأَحَدٍ مِنْ دُنْياهُ إِلَّا ما أَنْفَقَهُ عَلى أُخْراهُ.', NULL, '7', '48', '267', '805', '2', 0, ''),
(18174, 6982, 'لَيْسَ مَعَ الْخِلافِ ائْتِلافٌ.', NULL, '7', '48', '267', '805', '2', 0, ''),
(18175, 6983, 'لَيْسَ مَعَ الشَّرِّ عَفافٌ.', NULL, '7', '48', '267', '805', '2', 0, ''),
(18176, 6984, 'لَيسَ شَيْ ءٌ أَفْسَدَ لِلْامُورِ وَ لا أَبْلَغُ في هَلاكِ الْجمْهُورِ مِنَ الْجَوْرِ.', NULL, '7', '48', '267', '805', '2', 0, ''),
(18177, 6985, 'لَيْسَ شَيْ ءٌ أَحْمَدَ عاقِبَةً وَ لا أَلَذَّ مَغَبَّةً وَ لا أَدْفَع لِسُوءٍ أَدَبٍ وَ لا أَعْوَنَ عَلى دَرْكِ مَطْلَبٍ مِنَ الصَّبْرِ.', NULL, '7', '48', '267', '805', '2', 0, ''),
(18178, 6986, 'لَيْسَ في شَرَفٍ سَرَفٌ.', NULL, '7', '48', '267', '805', '2', 0, ''),
(18179, 6987, 'لَيْسَ شَيْ ءٌ أَدْعى لِخَيْرٍ وَ لا أَنْجى مِنْ شَرٍّ مِنْ صُحْبَةِ الْأَبْرارِ.', NULL, '7', '48', '267', '805', '2', 0, ''),
(18180, 6988, 'لَيْسَ فِي الْجَوارِح أَقَلُّ شُكْراً مِنَ الْعيْنِ فَلا تُعْطُوها سُؤْلَها فَيَشْغَلكُمْ عَنْ ذِكْرِ اللهِ.', NULL, '7', '48', '267', '805', '2', 0, ''),
(18181, 6989, 'لَيْسَ فِي الْمَعاصي أَشَدُّ مِنِ اتِّباعِ الشَّهْوَةِ فَلا تُطيعُوها فَيَقْطَعَكُمْ عَنِ اللهِ.', NULL, '7', '48', '267', '805', '2', 0, ''),
(18182, 6990, 'لَيْسَ كُلُّ مَغْرُورٍ بِناجٍ وَ لا كُلُّ طالِبٍ بِمُحْتاجٍ.', NULL, '7', '48', '267', '805', '2', 0, ''),
(18183, 6991, 'لَيْسَ لِلْعاقِلِ أَنْ يَكُونَ شاخِصاً إِلَّا في ثَلاثٍ: خُطْوَةٍ في مَعادٍ، أَوْ مَرَمَّةٍ لِمَعاشٍ، أَوْ لَذَّةٍ في غَيْرِ مُحَرَّمٍ.', NULL, '7', '48', '267', '805', '2', 0, ''),
(18184, 6992, 'لَيْسَ بِحَكيمٍ مَنْ شَكا ضُرَّهُ إِلى غَيرِ رَحيمٍ.', NULL, '7', '48', '267', '805', '2', 0, ''),
(18185, 6993, 'لَيْسَ كُلُّ مُجْمِلٍ بِمَحْرُومٍ.', NULL, '7', '48', '267', '805', '2', 0, ''),
(18186, 6994, 'لَيْسَ الْخَيرُ أَنْ يَكْثُرَ مالُكَ وَ وَلَدُكَ وَ إِنَّمَا الْخَيرُ أَنْ يَكْثُرَ عِلْمُكَ وَ يَعْظُمَ حِلْمُكَ.', NULL, '7', '48', '267', '805', '2', 0, ''),
(18187, 6995, 'لَيْسَ بِحَكيمٍ مَنِ ابْتَذَلَ بِانْبِساطِه إِلى غَيرِ حَميمٍ.', NULL, '7', '48', '267', '805', '2', 0, ''),
(18188, 6996, 'لَيْسَ بِحَكيمٍ مَنْ قَصَدَ بِحاجَتِه غَيرَ كَريمٍ.', NULL, '7', '48', '267', '805', '2', 0, ''),
(18189, 6997, 'لَيْسَ مِنَ الْعَدْلِ الْقَضاءُ عَلى الثِّقَةِ بِالظَّنِّ.', NULL, '7', '48', '267', '805', '2', 0, ''),
(18190, 6998, 'لَيْسَ مِنَ الْكَرَمِ تَكْديرُ الْمِنَنِ بِالْمَنِّ.', NULL, '7', '48', '267', '805', '2', 0, ''),
(18191, 6999, 'لَيْسَ عَنِ الْاخِرَةِ عِوَضٌ وَ لَيْسَتِ الدُّنْيا لِلنَّفْسِ بِثَمَنٍ.', NULL, '7', '48', '267', '805', '2', 0, ''),
(18192, 7000, 'لَيْسَ لَكَ بِأَخٍ مَنِ احْتَجْتَ إِلى مُداراتِه.', NULL, '7', '48', '267', '805', '2', 0, ''),
(18193, 7001, 'لَيْسَ بِرَفيقٍ مَحْمُودِ الطَّريقَةِ مَنْ أَحْوَجَ صاحِبَهُ إِلى مُماراتِه.', NULL, '7', '48', '267', '805', '2', 0, ''),
(18194, 7002, 'لَيْسَ لَكَ بِأَخٍ مَنْ أَحْوَجَكَ إِلى حاكِمٍ بَيْنَكَ وَ بَيْنَهُ.', NULL, '7', '48', '267', '805', '2', 0, ''),
(18195, 7003, 'لَيْسَ فِي الْبَرْقِ اللّامِعِ مُسْتَمْتَعٌ لِمَنْ يَخُوضُ فِي الظُّلْمَةِ.', NULL, '7', '48', '267', '805', '2', 0, ''),
(18196, 7004, 'لَيْسَ لِلْكَذوبِ أَمانَةٌ وَ لا لِفُجُورٍ صِيانَةٌ.', NULL, '7', '48', '267', '805', '2', 0, ''),
(18197, 7005, 'لَيْسَ في شُرْبِ الْمُسْكِرِ وَ الْمَسْحِ عَلى الْخُفَّيْنِ تَقِيَّةٌ.', NULL, '7', '48', '267', '805', '2', 0, ''),
(18198, 7006, 'لَيْسَ لِلْعَبْدِ أَنْ يَخْرُجَ في سَفَرٍ في شَهْرِ رَمضانَ لِقَوْلِه عَزَّ وَ جَلَّ: ''فَمَنْ شَهِدَ مِنْكُمُ الشَّهْرَ فَلْيَصُمْهُ''.', NULL, '7', '48', '267', '805', '2', 0, ''),
(18199, 7007, 'لَيْسَ عَمَلٌ أَحَبَّ إِلى اللهِ مِنَ الصَّلاةِ فَلا يَشْغَلَنَّكُمْ عَنْ أَوْقاتِها |شَيْ ءٌ مِنْ|
INSERT INTO `words` (`_id`, `BookId`, `Wisdom`, `enWisdom`, `Qsm`, `Bab`, `Fsl`, `Topic`, `Source`, `fav`, `lastcheckdate`) VALUES
(19002, 7810, 'مَنْ لَمْ يُجاهِدْ نَفْسَهُ لَمْ يَنَلِ الْفَوْزَ.', NULL, '7', '49', '271', '809', '2', 0, ''),
(19003, 7811, 'مَنْ لَمْ يُقَدِّمْهُ الْحَزْمُ أَخَّرَهُ الْعَجْزُ.', NULL, '7', '49', '271', '809', '2', 0, ''),
(19004, 7812, 'مَنْ لَمْ يَنْفَعْهُ حاضِرُ لُبِّه فَهُوَ عَنْ غائِبِه أَعْجَز وَ من عَاتِبه أَعْوَزُ.', NULL, '7', '49', '271', '809', '2', 0, ''),
(19005, 7813, 'مَنْ كَمُلَ عَقْلُهُ اسْتَهانَ بِالْشَّهَواتِ.', NULL, '7', '49', '271', '809', '2', 0, ''),
(19006, 7814, 'مَنْ صَدَقَ وَرَعُهُ اجْتَنَبَ الْمُحَرَّماتِ.', NULL, '7', '49', '271', '809', '2', 0, ''),
(19007, 7815, 'مَنْ عَرَفَ النّاسَ لَمْ يَعْتَمِدْ عَلَيْهِمْ.', NULL, '7', '49', '271', '809', '2', 0, ''),
(19008, 7816, 'مَنْ جَهِلَ النّاسَ اسْتَنامَ إِلَيْهِمْ.', NULL, '7', '49', '271', '809', '2', 0, ''),
(19009, 7817, 'مَنِ ابْتاعَ آخِرَتَهُ بِدُنْياهُ رَبِحَهُما.', NULL, '7', '49', '271', '809', '2', 0, ''),
(19010, 7818, 'مَنْ ابْتاعَ آخِرَتَهُ بِدُنْياهُ خَسِرَهُما.', NULL, '7', '49', '271', '809', '2', 0, ''),
(19011, 7819, 'مَنْ صَحِبَ الْأَشْرارَ لَمْ يَسْلَمْ.', NULL, '7', '49', '271', '809', '2', 0, ''),
(19012, 7820, 'مَنْ أَلَحَّ فِي السُّؤالِ أَبْرَمَ.', NULL, '7', '49', '271', '809', '2', 0, ''),
(19013, 7821, 'مَنْ أَجْهَدَ نَفْسَهُ في صَلاحِها سَعَدَ.', NULL, '7', '49', '271', '809', '2', 0, ''),
(19014, 7822, 'مَنْ أَهْمَلَ نَفْسَهُ في لَذّاتِها شَقِيَ وَ بَعُدَ.', NULL, '7', '49', '271', '809', '2', 0, ''),
(19015, 7823, 'مَنْ تَعَلَّمَ الْعِلْمَ لِلْعَمَلِ بِه لَمْ يُوحِشْهُ كَسادُهُ.', NULL, '7', '49', '271', '809', '2', 0, ''),
(19016, 7824, 'مَنْ عَمِلَ بِالْعِلْمِ بَلَغَ بُغْيَتَهُ مِنَ الْاخِرَةِ وَ مُرادَهُ.', NULL, '7', '49', '271', '809', '2', 0, ''),
(19017, 7825, 'مَنْ ظَلَمَ عِبادَ اللهِ كانَ اللهُ خَصْمَهُ دُونَ عِبادِه.', NULL, '7', '49', '271', '809', '2', 0, ''),
(19018, 7826, 'مَنْ أَمَرَ بِالْمَعْرُوفِ شَدَّ ظُهُورَ الْمُؤْمِنينَ.', NULL, '7', '49', '271', '809', '2', 0, ''),
(19019, 7827, 'مَنْ نَهى عَنِ الْمُنْكَرِ أَرْغَمَ أُنُوفَ الْفاسِقينَ.', NULL, '7', '49', '271', '809', '2', 0, ''),
(19020, 7828, 'مَنْ تَوَكَّلَ عَلى اللهِ غَنِيَ عَنْ عِبادِه.', NULL, '7', '49', '271', '809', '2', 0, ''),
(19021, 7829, 'مَنْ أَخْلَصَ لِلّهِ اسْتَظْهَرَ لِمَعاشِه وَ مَعادِه.', NULL, '7', '49', '271', '809', '2', 0, ''),
(19022, 7830, 'مَنْ ضَيَّعَ عاقِلاً دَلَّ عَلى ضَعْفِ عَقْلِه.', NULL, '7', '49', '271', '809', '2', 0, ''),
(19023, 7831, 'مَنِ اصْطَنَعَ جاهِلاً بَرْهَنَ عَنْ وُفُورِ جَهْلِه.', NULL, '7', '49', '271', '809', '2', 0, ''),
(19024, 7832, 'مَنِ اشْتَغَلَ بِذِكْرِ اللهِ طَيَّبَ اللهُ ذِكْرَهُ.', NULL, '7', '49', '271', '809', '2', 0, ''),
(19025, 7833, 'مَنِ اشْتَغَلَ بِذِكْرِ النّاسِ قَطَعَهُ اللهُ عَنْ ذِكْرِه.', NULL, '7', '49', '271', '809', '2', 0, ''),
(19026, 7834, 'مَنْ أَسَرَّ إِلى غَيرِ ثِقَةٍ ضَيَّعَ سِرَّهُ.', NULL, '7', '49', '271', '809', '2', 0, ''),
(19027, 7835, 'مَنِ اسْتَعانَ بِغَيْرِ مُسْتَقِلٍّ ضَيَّعَ أَمْرَهُ.', NULL, '7', '49', '271', '809', '2', 0, ''),
(19028, 7836, 'مَنِ اسْتَعانَ بِالضَّعيفِ أَبانَ عَنْ ضَعْفِه.', NULL, '7', '49', '271', '809', '2', 0, ''),
(19029, 7837, 'مَنْ وادَّ السَّخيفَ أَعْرَبَ عَنْ سَخَفِه.', NULL, '7', '49', '271', '809', '2', 0, ''),
(19030, 7838, 'مَنِ اسْتَصْلَحَ عَدُوَّهُ زادَ في عُدَدِه.', NULL, '7', '49', '271', '809', '2', 0, ''),
(19031, 7839, 'مَنِ اسْتَفْسَدَ صَديقَهُ نَقَصَ مِنْ عُدَدِه.', NULL, '7', '49', '271', '809', '2', 0, ''),
(19032, 7840, 'مَنْ سالَمَ النّاسَ سُتِرَتْ عُيُوبُهُ.', NULL, '7', '49', '271', '809', '2', 0, ''),
(19033, 7841, 'مَنْ تَتَبَّعَ عُيُوبُ النّاسِ كُشِفَتْ عُيُوبُهُ.', NULL, '7', '49', '271', '809', '2', 0, ''),
(19034, 7842, 'مَنِ اعْتَبَرَ بِعَقْلِه اسْتَبانَ.', NULL, '7', '49', '271', '809', '2', 0, ''),
(19035, 7843, 'مَنْ أَفْشى سِرّاً اسْتُودِعَهُ فَقَدْ خانَ.', NULL, '7', '49', '271', '809', '2', 0, ''),
(19036, 7844, 'مَنْ كَتَمَ عِلْماً فَكَأَنَّهُ جاهِلٌ.', NULL, '7', '49', '271', '809', '2', 0, ''),
(19037, 7845, 'مَنْ عَمَرَ دارَ إِقامَتِه فَهُوَ الْعاقِلُ.', NULL, '7', '49', '271', '809', '2', 0, ''),
(19038, 7846, 'مَنِ انْتَظَرَ الْعاقِبَةَ صَبَرَ.', NULL, '7', '49', '271', '809', '2', 0, ''),
(19039, 7847, 'مَنْ سَلَّمَ أَمْرَهُ إِلى اللهِ اسْتَظْهَرَ.', NULL, '7', '49', '271', '809', '2', 0, ''),
(19040, 7848, 'مَنْ حَسُنَتْ مَساعيهِ طابَتْ مَراعيهِ.', NULL, '7', '49', '271', '809', '2', 0, ''),
(19041, 7849, 'مَنْ كَثُرَ تَعَدّيهِ كَثُرَتْ أَعاديهِ.', NULL, '7', '49', '271', '809', '2', 0, ''),
(19042, 7850, 'مَنْ أَساءَ النِّيَّةَ عَدِمَ الْاُمْنِيَّةَ.', NULL, '7', '49', '271', '809', '2', 0, ''),
(19043, 7851, 'مَنِ اعْتَمَدَ عَلى الْاُمْنِيَّةِ قَطَعَتْهُ الْمَنِيَّةَ.', NULL, '7', '49', '271', '809', '2', 0, ''),
(19044, 7852, 'مَنْ ساءَ مَقْصَدُهُ ساءَ مَوْرِدُهُ.', NULL, '7', '49', '271', '809', '2', 0, ''),
(19045, 7853, 'منْ ساءَ عَزْمُهُ رَجَعَ عَلَيْهِ سَهْمُهُ.', NULL, '7', '49', '271', '809', '2', 0, ''),
(19046, 7854, 'مَنْ خالَفَ عِلْمَهُ عَظُمَ إِثْمُهُ.', NULL, '7', '49', '271', '809', '2', 0, ''),
(19047, 7855, 'مَنْ سائَتْ سَجيَّتُهُ سَرَّتْ مَنيَّتُةُ.', NULL, '7', '49', '271', '809', '2', 0, ''),
(19048, 7856, 'مَنْ طالَتْ غَفْلَتُهُ تَعَجَّلَتْ هَلَكَتُهُ.', NULL, '7', '49', '271', '809', '2', 0, ''),
