(19482, 8290, 'مَنْ لَمْ يُذِبْ نَفْسَهُ فِي اكْتِسابِ الْعِلمِ لَمْ يَحْرُزْ قَصَباتِ السَّبَقِ.', NULL, '7', '49', '271', '809', '2', 0, ''),
(19483, 8291, 'مَنْ أَنْكَرَ عُيُوبَ النّاسِ وَ رَضِيَها لِنَفْسِه فَذلِكَ الْأَحْمَقُ.', NULL, '7', '49', '271', '809', '2', 0, ''),
(19484, 8292, 'مَنِ اقْتَصَرَ عَلى الْكَفافِ تَعَجَّلَ الرَّاحَةَ وَ تَبَوَّءَ خَفْضَ الدِّعَةِ.', NULL, '7', '49', '271', '809', '2', 0, ''),
(19485, 8293, 'مَنْ أَحَبَّ رِفْعَةً فِي الْاخِرَةِ فَلْيَمْقُتْ فِي الدُّنْيا الرِّفْعَةَ.', NULL, '7', '49', '271', '809', '2', 0, ''),
(19486, 8294, 'مَنْ تَذَلَّلَ لِأَبْناءِ الدُّنْيا تَعَرّى مِنْ لِباسِ الْتَّقْوى.', NULL, '7', '49', '271', '809', '2', 0, ''),
(19487, 8295, 'مَنْ قَصَّرَ نَظَرَهُ عَلى الدُّنْيا عَمِيَ عَنْ سَبيلِ الْهُدى.', NULL, '7', '49', '271', '809', '2', 0, ''),
(19488, 8296, 'مَنْ لَمْ يُنَزِّهْ نَفْسَهُ عَنْ دَناءَ ةِ الْمَطامِعِ فَقَدْ أَذَلَّ نَفْسَهُ وَ هُوَ في الْاخِرَةِ أَذَلُّ وَ أَخْزى.', NULL, '7', '49', '271', '809', '2', 0, ''),
(19489, 8297, 'مَنْ عَمَرَ قَلْبَهُ بِدَوامِ الذِّكرِ حَسُنَتْ أَفْعالُهُ فِي السِّرِّ وَ الْجَهْرِ.', NULL, '7', '49', '271', '809', '2', 0, ''),
(19490, 8298, 'مَنْ جَهِلَ قَدرَهُ جَهِلَ كُلِّ قَدْرٍ.', NULL, '7', '49', '271', '809', '2', 0, ''),
(19491, 8299, 'مَنْ ضَيَّعَ أَمْرَهُ ضَيَّعَ كُلَّ أَمْرٍ.', NULL, '7', '49', '271', '809', '2', 0, ''),
(19492, 8300, 'مَنْ نَسِيَ اللهَ سُبْحانَهُ أَنْساهُ نَفْسَهُ وَ أَعْمى قَلْبَهُ.', NULL, '7', '49', '271', '809', '2', 0, ''),
(19493, 8301, 'مَنْ ذَكَرَ اللهَ أَحْيى قَلْبَهُ وَ اسْتَنارَ عَقْلُهُ وَ لُبُّهُ.', NULL, '7', '49', '271', '809', '2', 0, ''),
(19494, 8302, 'مَنِ اسْتَغْنى كَرُمَ عَلى أَهْلِه وَ مَنِ افْتَقَرَ هانَ عَلى أَهْلِه.', NULL, '7', '49', '271', '809', '2', 0, ''),
(19495, 8303, 'مَنْ يَقْبِضْ يَدَهُ عَنْ عَشيرَتِه فَإِنَّما يَقْبِضُ يَداً واحِدةً عَنْهُمْ وَ تُقْبَضُ عَنْهُ أَيْدٍ
INSERT INTO `words` (`_id`, `BookId`, `Wisdom`, `enWisdom`, `Qsm`, `Bab`, `Fsl`, `Topic`, `Source`, `fav`, `lastcheckdate`) VALUES
(20002, 8810, 'مَا أَخْلَقَ مَنْ عَرَفَ رَبَّهُ أَنْ يَعْتَرِفَ بِذَنْبِه.', NULL, '7', '49', '273', '811', '2', 0, ''),
(20003, 8811, 'مَا خَيرُ دارٍ تَنْقُضُ نَقْضَ الْبَناءِ وَ عُمْرٍ يَفْنى فَناءَ الزَّادِ.', NULL, '7', '49', '273', '811', '2', 0, ''),
(20004, 8812, 'مَا أَنْفَعَ الْمَوْتَ لِمَنْ أَشْعَرَ الْإِيْمانَ وَ التَّقْوى قَلْبَهُ.', NULL, '7', '49', '273', '811', '2', 0, ''),
(20005, 8813, 'مَا لا يَنْبَغي أَنْ تَفْعَلَهُ في الْجَهْرِ لا تَفْعَلْهُ فِي السِّرِّ.', NULL, '7', '49', '273', '811', '2', 0, ''),
(20006, 8814, 'مَا أَراكُمْ إِلَّا أَشْباحاً بِلا أَرْوَاحِ وَ أَرْواحاً بِلا فَلاحِ وَ نُسّاكاً بِلا صَلاحِ وَ تُجّاراً بِلا أَرْباحٍ.', NULL, '7', '49', '273', '811', '2', 0, ''),
(20007, 8815, 'مَا مَزَحَ امْرُؤٌ مَزْحَةً إِلَّا مَجَّ مِنْ عَقْلِه مَجَّةً.', NULL, '7', '49', '273', '811', '2', 0, ''),
(20008, 8816, 'مَا التَذَّ أَحَدٌ مِنَ الدُّنْيا لَذَّةً إِلَّا كانَتْ لَهُ يَوْمَ الْقِيامَةِ غُصَّةً.', NULL, '7', '49', '273', '811', '2', 0, ''),
(20009, 8817, 'مَا زَادَ فِي الدُّنْيا نَقَصَ فِي الْاخِرَةِ.', NULL, '7', '49', '273', '811', '2', 0, ''),
(20010, 8818, 'مَا نَقَصَ فِي الدُّنْيا زادَ فِي الْاخِرَةِ.', NULL, '7', '49', '273', '811', '2', 0, ''),
(20011, 8819, 'مَا أَقْرَبَ الرَّاحَةَ مِنَ التَّعَبِ.', NULL, '7', '49', '273', '811', '2', 0, ''),
