(20013, 8821, 'مَا أَخْسَرَ مَنْ لَمْ يَكُنْ لَهُ فِي الْاخِرَةِ نَصيبٌ.', NULL, '7', '49', '273', '811', '2', 0, ''),
(20014, 8822, 'مَا أَشْجَعَ الْبَرِي ءَ وَ أَجْبَنَ الْمُريبَ.', NULL, '7', '49', '273', '811', '2', 0, ''),
