(20078, 8886, 'مَا أَقْرَبَ الْحَيَّ مِنَ الْمَيِّتِ لِلِحاقِه بِه.', NULL, '7', '49', '273', '811', '2', 0, ''),
(20079, 8887, 'مَا أَبْعَدَ الْمَيِّتَ مِنَ الْحَيِّ لِانْقِطاعِه عَنْهُ.', NULL, '7', '49', '273', '811', '2', 0, ''),
(20080, 8888, 'مَا أَنْعَمَ اللهُ عَلى عَبْدٍ نعْمَةً فَظَلَمَ فيها إِلَّا كانَ حَقيقاً أَنْ يُزيلَها عَنْهُ.', NULL, '7', '49', '273', '811', '2', 0, ''),
(20081, 8889, 'مَا كَرُمَتْ عَلى عَبْدٍ نَفْسُهُ إِلَّا هانَتِ الدُّنْيا في عَيْنِه.', NULL, '7', '49', '273', '811', '2', 0, ''),
(20082, 8890, 'مَا أَمِنَ عَذابَ اللهِ مَنْ لَمْ يَأْمَنِ النّاسُ شَرَّهُ.', NULL, '7', '49', '273', '811', '2', 0, ''),
(20083, 8891, 'مَا غَشَّ نَفْسَهُ مَنْ يَنْصَحُ غَيرَهُ.', NULL, '7', '49', '273', '811', '2', 0, ''),
(20084, 8892, 'مَا قَسَمَ اللهُ سُبْحانَهُ بَيْنَ عِبادِه شَيْئاً أَفْضَلَ مِنَ الْعَقْل.', NULL, '7', '49', '273', '811', '2', 0, ''),
(20085, 8893, 'مَا دُنْياكَ الَّتي تَحَبَّبَتْ إِلَيْكَ بِخَيرٍ مِنَ الْاخِرَة الَّتي قَبَّحَها سُوءُ النَّظَرِ عِنْدَكَ.', NULL, '7', '49', '273', '811', '2', 0, ''),
(20086, 8894, 'مَا بَعْدَ النَّبِيِّينَ إِلَّا اللَّبْسُ.', NULL, '7', '49', '273', '811', '2', 0, ''),
(20087, 8895, 'مَا مِنْ جِهادٍ أَفْضَلَ مِنْ جِهادِ النَّفْسِ.', NULL, '7', '49', '273', '811', '2', 0, ''),
(20088, 8896, 'مَا قَدَّمْتَ مِنْ دُنْياكَ فَلِنَفْسِكَ وَ مَا أَخَّرْتَ مِنْها فَلِلْعَدُوِّ.', NULL, '7', '49', '273', '811', '2', 0, ''),
(20089, 8897, 'مَا قَالَ النّاسُ لِشَيْ ءٍ طُوبى لَهُ إِلَّا وَقَدْ خَبأ لَهُ الدَّهْرُ يَوْمَ سَوْءٍ.', NULL, '7', '49', '273', '811', '2', 0, ''),
(20090, 8898, 'مَا كانَ اللهُ سُبْحانَهُ لِيَفْتَحَ عَلى عَبْدٍ بابِ الشُّكْرِ وَ يُغْلِقَ عَنْهُ بابَ الْمَزيدِ.', NULL, '7', '49', '273', '811', '2', 0, ''),
(20091, 8899, 'مَا زَالَتْ عَنْكُمْ نِعْمَةٌ وَ لا غَضارَةُ عَيْشٍ إِلَّا بِذُنُوبٍ اجْتَرَحْتُمُوها وَ لَيْسَ اللهُ بِظَلامٍ لِلْعَبيدِ.', NULL, '7', '49', '273', '811', '2', 0, ''),
(20092, 8900, 'مَا آمَنَ بِالْقُرْآنِ مَنِ اسْتَحَلَّ مَحارِمَهُ.', NULL, '7', '49', '273', '811', '2', 0, ''),
(20093, 8901, 'مَا أَعْظَمَ الْمُصيبَةَ فِي الدُّنْيا مَعَ عَظيمِ الْفاقَةِ غَداً.', NULL, '7', '49', '273', '811', '2', 0, ''),
(20094, 8902, 'مَا نِلْتَ مِنْ دُنْياكَ فَلا تُكْثرْ بِه فَرَحاً وَمَا فاتَكَ مِنْها فَلا تَأْسَ عَلَيْهِ حَزَناً.', NULL, '7', '49', '273', '811', '2', 0, ''),
(20095, 8903, 'مَا أَكَلْتَهُ راحَ وَ مَا أَطْعَمْتَهُ فاحَ.', NULL, '7', '49', '273', '811', '2', 0, ''),
(20096, 8904, 'مَا الْإِنْسانُ لَوْلَا اللِّسانُ إِلَّا صُورَةٌ مُمَثَّلَةٌ أَوْ بَهيمَةٌ مُهْمَلَةٌ.', NULL, '7', '49', '273', '811', '2', 0, ''),
(20097, 8905, 'مَا أَصْدَقَ الْإِنْسانَ عَلى نَفْسِه وَ أَيُّ دَليلٍ كَفِعْله.', NULL, '7', '49', '273', '811', '2', 0, ''),
(20098, 8906, 'مَا أَعْظَمَ - اللَّهُمَّ - مَا نَرى مِنْ خَلْقِكَ وَ مَا أَصْغَرَ عَظيمَهُ في جَنْبِ مَا غابَ عَنّا مِنْ قُدْرَتِكَ.', NULL, '7', '49', '273', '811', '2', 0, ''),
(20099, 8907, 'مَا أَهْوَلَ اللَّهُمَّ مَا نُشاهِدُهُ مِنْ مَلَكُوتِكَ وَ مَا أَحْقَرَ ذلِكَ فيما غابَ عَنّا مِنْ عَظيمِ سُلْطانِكَ.', NULL, '7', '49', '273', '811', '2', 0, ''),
(20100, 8908, 'مَا أَخَذَ اللهُ سُبْحانَهُ عَلى الْجاهِلِ أَنْ يَتَعَلَّمَ حَتَّى أَخَذَ عَلى الْعالِمِ أَنْ يُعَلِّمَ.', NULL, '7', '49', '273', '811', '2', 0, ''),
(20101, 8909, 'مَا أَفادَ الْعِلْمُ مَنْ لَمْ يَفْهَمْ وَ لا نَفَعَ الْحِلمُ مَنْ لَمْ يَحْلُمْ.', NULL, '7', '49', '273', '811', '2', 0, ''),
(20102, 8910, 'مَا أَهَمَّني ذَنْبٌ أُمْهِلْتُ فيهِ حَتّى أُصَلِّيَ رَكْعَتْينِ.', NULL, '7', '49', '273', '811', '2', 0, ''),
(20103, 8911, 'مَا أَقْبَحَ بِالْإِنْسانِ أَنْ يَكُونَ ذا وَجْهَيْنِ.', NULL, '7', '49', '273', '811', '2', 0, ''),
(20104, 8912, 'مَا شَيْ ءٌ مِنْ مَعْصِيَةِ اللهِ تَأْتي إِلَّا في شَهْوَةٍ.', NULL, '7', '49', '273', '811', '2', 0, ''),
(20105, 8913, 'مَا شَيْ ءٌ مِنْ طاعَةِ اللهِ تَأْتي إِلَّا في كُرْهٍ.', NULL, '7', '49', '273', '811', '2', 0, ''),
(20106, 8914, 'مَا قَضَى اللهُ سُبْحانَهُ عَلى عَبْدٍ بِقَضاءٍ فَرَضِيَ بِه إِلَّا كانَتِ الْخِيَرَةُ لَهُ فيهِ.', NULL, '7', '49', '273', '811', '2', 0, ''),
(20107, 8915, 'مَا أَعْطَى اللهُ سُبْحانَهُ الْعَبْدَ شَيْئاً مِنْ خَيرِ الدُّنْيا وَ الْاخِرَةِ إِلَّا بِحُسْنِ خُلْقِه وَ حُسْنِ نِيَّتِه.', NULL, '7', '49', '273', '811', '2', 0, ''),
(20108, 8916, 'مَا دَفَعَ اللهُ عَنِ الْعَبْدِ الْمُؤْمِنِ شَيْئاً مِنْ بَلاءِ الدُّنْيا وَ عَذابِ الْاخِرَةِ إِلَّا بِرِضاهُ بِقَضائِه وَ حُسْنِ صَبْرِه عَلى بَلائِه.', NULL, '7', '49', '273', '811', '2', 0, ''),
(20109, 8917, 'مَا تَآخى قَوْمٌ عَلى غَيرِ ذاتِ اللهِ سُبْحانَهُ إِلَّا كانَتْ أُخُوَّتُهُمْ عَلَيْهِمْ تِرَةً يَوْمَ الْعَرْضِ عَلى اللهِ.', NULL, '7', '49', '273', '811', '2', 0, ''),
(20110, 8918, 'مَا تَوَسَّلَ أَحَدٌ إِلَيَّ بِوَسيلَةٍ أَجَلَّ عِنْدي مِنْ يَدٍ سَبَقَتْ مِنِّي إِلَيْهِ لِاُرْبِيَها عنْدهُ بِاتِّباعِها أُختَها فَإِنَّ مَنْعَ الْأَواخِرِ يَقْطَعُ شُكْرَ الْأَوائِلِ.', NULL, '7', '49', '273', '811', '2', 0, ''),
(20111, 8919, 'مَا آنَسَكَ أَيُّها الْإنْسانُ بِهَلَكَةِ نَفْسِكَ أَما مِنْ دائِكَ بُلُولٌ أَمْ لَيْسَ لَكَ مِنْ نَوْمَتِك يَقَظَةٌ أَمَّا تَرْحَمُ مِنْ نَفْسِكَ مَا تَرْحَمُ مِنْ غَيْرِكَ.', NULL, '7', '49', '273', '811', '2', 0, ''),
(20112, 8920, 'مَا الْمَغْبُوطُ إِلَّا مَنْ كانَتْ هِمَّتُهُ نَفْسَهُ لا يُغِبُّها عَنْ مُحاسَبَتِها وَ مُجاهَدَتِها وَ مُطالَبَتِها.', NULL, '7', '49', '273', '811', '2', 0, ''),
(20113, 8921, 'مَا الْمَغْرُورُ الَّذي ظَفَرَ مِنَ الدُّنْيا بِأَدْنى شَهْوَتِه كَالْاخَرِ الَّذي ظَفَرَ مِنَ الْاخِرَةِ بِأَعْلى هِمَّتِه.', NULL, '7', '49', '273', '811', '2', 0, ''),
(20114, 8922, 'مَا الْمَغْبُوطُ الَّذي فازَ مِنْ دارِ الْبَقاءِ بِبُغْيَتِه كَالْمَغْبُونِ الَّذي فاتَهُ النَّعْيمُ لِسُوءِ اخْتِيارِه وَ شَقاوَتِه.', NULL, '7', '49', '273', '811', '2', 0, ''),
(20115, 8923, 'مَا |أَصْدَق الْمَرْءِ عَلى نَفْسِهِ، وَ أَىُّ شاهِدٍ عَلَيْهِ كَفِعْلِهِ، وَ لا يُعْرَفُ الرَّجُلُ
INSERT INTO `words` (`_id`, `BookId`, `Wisdom`, `enWisdom`, `Qsm`, `Bab`, `Fsl`, `Topic`, `Source`, `fav`, `lastcheckdate`) VALUES
(21002, 9810, 'لا يَرْؤُسُ مَنْ خَلا عَنْ "حُسْنِ" الْأَدَبِ وَ صَبا إِلى اللَّعَبِ.', NULL, '7', '53', '280', '818', '2', 0, ''),
(21003, 9811, 'لا يُفْلِحُ مَنْ وَلَهَ بِاللِّعَبِ وَ اسْتُهْتِرَ بِالطَّرَبِ.', NULL, '7', '53', '280', '818', '2', 0, ''),
(21004, 9812, 'لا خَيْرَ فِي الْكَذّابينَ وَ لا فِي الْعُلَماءِ الْأَفّاكينَ.', NULL, '7', '53', '280', '818', '2', 0, ''),
(21005, 9813, 'لا خَيْرَ في قَوْمٍ لَيْسُوا بِناصِحينَ وَ لا يُحِبُّونَ النّاصِحينَ.', NULL, '7', '53', '280', '818', '2', 0, ''),
(21006, 9814, 'لا يَنْجُو مِنَ اللهِ مَنْ لا يَنْجُو النّاسُ مِنْ شَرِّه.', NULL, '7', '53', '280', '818', '2', 0, ''),
(21007, 9815, 'لا يُؤْمِنُ اللهُ عَذابَهُ مَنْ لا يَأْمَنُ الْعِبادُ جَوْرَهُ.', NULL, '7', '53', '280', '818', '2', 0, ''),
(21008, 9816, 'لا يُنْتَصَفُ مِنْ سَفيهٍ قَطُّ إِلَّا بِالْحِلْمِ عَنْهُ.', NULL, '7', '53', '280', '818', '2', 0, ''),
(21009, 9817, 'لا يُقابِلُ مُسْي ءٌ قَطُّ بِأَفْضَلَ مِنَ الْعَفْوِ عَنْهُ.', NULL, '7', '53', '280', '818', '2', 0, ''),
